window.STEPS=Object.assign(window.STEPS||{},{"고2-202006-04":{"길":"기준각을 구한 뒤 제2사분면의 대칭각으로 옮긴다","단계":[{"제목":"기준각 찾기","힌트":"$\\sin x=\\dfrac{1}{2}$ 이 되는 가장 작은 양의 각은?","식":["$\\sin\\dfrac{\\pi}{6}=\\dfrac{1}{2}$"],"설명":"제1사분면에서 사인값이 $\\dfrac{1}{2}$ 인 각이 기준각이다.","확인":null,"스킬":"T5"},{"제목":"구간에 맞는 각 고르기","고비":true,"힌트":"구간 $\\dfrac{\\pi}{2}\\le x\\le\\pi$ 는 제몇 사분면이고, 그 사분면에서 사인값이 같은 각은?","식":["$x=\\pi-\\dfrac{\\pi}{6}=\\dfrac{5}{6}\\pi$"],"설명":"구간이 제2사분면이므로 $y=\\sin x$ 의 그래프에서 $\\dfrac{\\pi}{2}$ 를 기준으로 대칭인 각을 고른다. $\\pi$ 에서 기준각을 뺀 값이 해이다.","확인":null,"스킬":"T5"}]},"고2-202006-05":{"길":"진수를 3.24와 10의 곱으로 쪼개 표의 값에 1을 더한다","단계":[{"제목":"진수를 표의 수와 10의 곱으로 나누기","고비":true,"힌트":"$32.4$ 를 $1$ 이상 $10$ 미만의 수와 $10$ 의 곱으로 쓰면?","식":["$32.4=3.24\\times10$","$\\log32.4=\\log3.24+\\log10=\\log3.24+1$"],"설명":"상용로그표는 $1$ 이상 $10$ 미만의 수만 다루므로 진수의 소수점을 옮겨 표에 있는 꼴로 만든다. $\\log10=1$ 이다.","확인":"3.24","스킬":"A9"},{"제목":"표 값을 읽어 더하기","힌트":"표에서 $3.2$ 행과 $4$ 열이 만나는 칸의 값은?","식":["$\\log3.24=0.5105$","$\\log32.4=1+0.5105=1.5105$"],"설명":"수가 $3.2$ 인 행과 $4$ 인 열이 만나는 칸이 $\\log3.24$ 의 소수 부분이다. 여기에 정수 부분 $1$ 을 더한다.","확인":"1.5105","스킬":"A9"}]},"고2-202006-06":{"길":"사인의 제곱과 부호를 정한 뒤 사인을 코사인으로 나눈다","단계":[{"제목":"사인의 제곱 구하기","힌트":"$\\sin^2\\theta+\\cos^2\\theta=1$ 에서 $\\sin^2\\theta$ 는?","식":["$\\sin^2\\theta=1-\\cos^2\\theta=1-\\dfrac{16}{25}=\\dfrac{9}{25}$"],"설명":"$\\cos\\theta=-\\dfrac{4}{5}$ 이므로 $\\cos^2\\theta=\\dfrac{16}{25}$ 이다.","확인":"9/25","스킬":"T5"},{"제목":"사분면으로 사인의 부호 정하기","고비":true,"힌트":"$\\pi<\\theta<\\dfrac{3}{2}\\pi$ 는 제몇 사분면이고, 그곳에서 $\\sin\\theta$ 의 부호는?","식":["$\\sin\\theta=-\\dfrac{3}{5}$"],"설명":"$\\theta$ 가 제3사분면의 각이므로 $y$ 좌표에 해당하는 $\\sin\\theta$ 는 음수이다. $\\sin^2\\theta=\\dfrac{9}{25}$ 에서 음의 근을 택한다.","확인":"-3/5","스킬":"T5"},{"제목":"탄젠트 계산하기","힌트":"$\\tan\\theta$ 는 $\\sin\\theta$ 와 $\\cos\\theta$ 로 어떻게 나타낼까?","식":["$\\tan\\theta=\\dfrac{\\sin\\theta}{\\cos\\theta}=\\dfrac{-\\frac{3}{5}}{-\\frac{4}{5}}=\\dfrac{3}{4}$"],"설명":"$\\tan\\theta=\\dfrac{\\sin\\theta}{\\cos\\theta}$ 이고 분자와 분모가 모두 음수이므로 값은 양수이다.","확인":"3/4","스킬":"T5"}]},"고2-202006-07":{"길":"밑이 1보다 작으면 감소함수이므로 왼쪽 끝에서 최댓값이 나온다","단계":[{"제목":"증가·감소 판단하기","고비":true,"힌트":"밑 $\\dfrac{1}{3}$ 이 $1$ 보다 작을 때, $x$ 가 커지면 $\\left(\\dfrac{1}{3}\\right)^{2x}$ 은 커지는가 작아지는가?","식":["$f(x)=2+\\left(\\dfrac{1}{9}\\right)^{x}$"],"설명":"밑이 $1$ 보다 작은 지수함수는 $x$ 가 증가하면 값이 감소한다. 따라서 $f(x)$ 는 구간의 왼쪽 끝 $x=-1$ 에서 최댓값을 갖는다.","확인":null,"스킬":"T3"},{"제목":"음수 지수 계산하기","힌트":"$x=-1$ 을 넣으면 $\\left(\\dfrac{1}{3}\\right)^{-2}$ 의 값은?","식":["$\\left(\\dfrac{1}{3}\\right)^{-2}=3^{2}=9$"],"설명":"음수 지수는 밑의 역수로 바꾼 거듭제곱이다.","확인":"9","스킬":"A9"},{"제목":"최댓값 구하기","힌트":"$f(-1)$ 의 값은?","식":["$f(-1)=2+9=11$"],"설명":"$f(-1)=2+\\left(\\dfrac{1}{3}\\right)^{-2}$ 에 앞의 값을 넣어 더한다.","확인":"11","스킬":"T3"}]},"고2-202006-08":{"길":"평행이동한 식에 점의 좌표를 넣어 a 를 구한다","단계":[{"제목":"평행이동한 식 세우기","고비":true,"힌트":"$x$ 축으로 $a$, $y$ 축으로 $1$ 만큼 옮기면 $x$ 와 $y$ 자리에 각각 무엇이 들어가는가?","식":["$y=\\log_2(x-a)+1$"],"설명":"$x$ 축 방향으로 $a$ 만큼 옮기면 $x$ 대신 $x-a$ 를, $y$ 축 방향으로 $1$ 만큼 옮기면 식 끝에 $+1$ 을 쓴다.","확인":null,"스킬":"G4"},{"제목":"점을 대입해 로그값 구하기","힌트":"점 $(9,3)$ 의 좌표를 넣으면 $\\log_2(9-a)$ 는?","식":["$3=\\log_2(9-a)+1$","$\\log_2(9-a)=2$"],"설명":"$x=9$, $y=3$ 을 식에 넣고 $+1$ 을 이항한다.","확인":"2","스킬":"G4"},{"제목":"지수로 바꿔 a 구하기","힌트":"$\\log_2(9-a)=2$ 를 지수로 바꾸면?","식":["$9-a=2^{2}=4$","$a=5$"],"설명":"$\\log_2 N=2$ 는 $N=2^{2}$ 과 같다.","확인":"5","스킬":"A9"}]},"고2-202006-09":{"길":"점근선과 y축의 교점을 로그함수에 넣어 k 를 구한다","단계":[{"제목":"점근선 구하기","고비":true,"힌트":"$y=2^x$ 의 점근선은 $x$ 축이다. 아래로 $1$ 만큼 옮기면?","식":["$y=2^x-1$ 의 점근선: $y=-1$"],"설명":"$y=2^x$ 의 점근선 $y=0$ 을 $y$ 축 방향으로 $-1$ 만큼 평행이동한 것이 $y=2^x-1$ 의 점근선이다.","확인":"-1","스킬":"T4"},{"제목":"만나는 점의 좌표 찾기","힌트":"직선 $y=-1$ 과 $y$ 축($x=0$)이 만나는 점의 좌표는?","식":["$(0,\\,-1)$"],"설명":"점근선과 로그함수의 그래프가 만나는 점이 $y$ 축 위에 있으므로 $x$ 좌표는 $0$ 이다.","확인":null,"스킬":"T4"},{"제목":"로그함수에 대입해 k 구하기","힌트":"점 $(0,-1)$ 을 $y=\\log_2(x+k)$ 에 넣으면?","식":["$-1=\\log_2 k$","$k=2^{-1}=\\dfrac{1}{2}$"],"설명":"$x=0$, $y=-1$ 을 넣으면 $\\log_2 k=-1$ 이고, 지수로 바꾸면 $k=2^{-1}$ 이다.","확인":"1/2","스킬":"A9"}]},"고2-202006-10":{"길":"최댓값·최솟값으로 a, c 를, 이웃한 두 최댓값 사이의 거리로 b 를 읽는다","단계":[{"제목":"최댓값·최솟값을 식으로 나타내기","힌트":"$a>0$ 일 때 $a\\sin bx+c$ 의 최댓값과 최솟값은 $a$, $c$ 로 어떻게 쓰이는가?","식":["$a+c=3$","$-a+c=-1$"],"설명":"$\\sin bx$ 는 $-1$ 이상 $1$ 이하이다. $a>0$ 이므로 $\\sin bx=1$ 일 때 최댓값 $a+c$, $\\sin bx=-1$ 일 때 최솟값 $-a+c$ 이다. 그래프에서 최댓값은 $3$, 최솟값은 $-1$ 이다.","확인":null,"스킬":"T2"},{"제목":"a 의 값 구하기","힌트":"두 식을 변끼리 빼면 $2a$ 는?","식":["$2a=4$","$a=2,\\ c=1$"],"설명":"$(a+c)-(-a+c)=3-(-1)$ 이므로 $2a=4$ 이고, 이를 대입하면 $c=1$ 이다.","확인":"2","스킬":"T2"},{"제목":"주기로 b 구하기","고비":true,"힌트":"그래프에서 이웃한 두 최댓값의 $x$ 좌표는 $\\dfrac{\\pi}{4}$, $\\dfrac{5}{4}\\pi$ 이다. 한 주기는?","식":["$\\dfrac{5}{4}\\pi-\\dfrac{\\pi}{4}=\\pi$","$\\dfrac{2\\pi}{b}=\\pi$, $b=2$"],"설명":"이웃한 두 최댓값 사이의 거리가 한 주기이다. $y=a\\sin bx+c$ 의 주기는 $\\dfrac{2\\pi}{b}$ 이다.","확인":"2","스킬":"T2"},{"제목":"a+b+c 계산하기","힌트":"구한 세 상수를 더하면?","식":["$a+b+c=2+2+1=5$"],"설명":"$a=2$, $b=2$, $c=1$ 을 더한다.","확인":"5","스킬":"T2"}]},"고2-202006-11":{"길":"로그로 바꾸고 밑을 2로 통일한 뒤 18을 곱으로 쪼갠다","단계":[{"제목":"지수방정식을 로그로 바꾸고 밑 통일하기","힌트":"$8^x=18$ 에서 $x$ 를 로그로 나타낸 뒤 밑을 $2$ 로 바꾸면?","식":["$x=\\log_8 18=\\log_{2^{3}}18=\\dfrac{1}{3}\\log_2 18$"],"설명":"$8^x=18$ 은 $x=\\log_8 18$ 이다. $8=2^{3}$ 이므로 밑을 $2$ 로 바꾸면 $\\dfrac{1}{3}$ 이 앞에 붙는다.","확인":null,"스킬":"A9"},{"제목":"진수를 곱으로 쪼개 합으로 나타내기","고비":true,"힌트":"$18$ 을 $2$ 와 $3$ 의 거듭제곱의 곱으로 쓰면?","식":["$\\log_2 18=\\log_2(2\\times3^{2})=1+2\\log_2 3$"],"설명":"$18=2\\times3^{2}$ 이고, 곱의 로그는 로그의 합이다. $\\log_2 3^{2}=2\\log_2 3$ 이다.","확인":null,"스킬":"A9"},{"제목":"k 의 값 읽기","힌트":"$x=\\dfrac{1}{3}\\left(1+2\\log_2 3\\right)$ 을 $\\dfrac{1}{3}+k\\log_2 3$ 과 비교하면?","식":["$x=\\dfrac{1}{3}+\\dfrac{2}{3}\\log_2 3$","$k=\\dfrac{2}{3}$"],"설명":"괄호를 풀어 $\\log_2 3$ 의 계수를 읽는다.","확인":"2/3","스킬":"A9"}]},"고2-202006-12":{"길":"2의 x제곱을 t 로 치환해 이차부등식으로 푼다","단계":[{"제목":"치환해 이차부등식 세우기","힌트":"$2^x=t$ 로 놓으면 $4^x$ 는 $t$ 로 어떻게 쓰이고, $t$ 의 범위는?","식":["$4^x=(2^x)^2=t^2$","$t^2-10t+16\\le0\\ (t>0)$"],"설명":"$4^x=(2^2)^x=(2^x)^2$ 이다. $2^x$ 는 항상 양수이므로 $t>0$ 이다.","확인":null,"스킬":"A1"},{"제목":"t 의 범위 구하기","고비":true,"힌트":"$t^2-10t+16$ 을 인수분해하면?","식":["$(t-2)(t-8)\\le0$","$2\\le t\\le8$"],"설명":"두 근 $2$, $8$ 사이에서 이차식이 $0$ 이하이다. 이는 $t>0$ 을 만족한다.","확인":null,"스킬":"A1"},{"제목":"x 의 범위로 바꿔 자연수의 합 구하기","힌트":"$2\\le2^x\\le8$ 을 밑이 $2$ 인 거듭제곱으로 비교하면 $x$ 의 범위는?","식":["$2^1\\le2^x\\le2^3$, $1\\le x\\le3$","$1+2+3=6$"],"설명":"밑이 $1$ 보다 크므로 지수의 대소가 그대로 유지된다. 조건을 만족시키는 자연수는 $1,\\ 2,\\ 3$ 이다.","확인":"6","스킬":"A9"}]},"고2-202006-13":{"길":"두 별을 A, B 로 정해 관계식에 넣고 log k 를 구한다","단계":[{"제목":"관계식에 값 넣기","힌트":"등급 $4.8$ 인 별을 $\\mathrm{A}$, $1.3$ 인 별을 $\\mathrm{B}$ 로 놓으면 $M_A-M_B$ 와 $\\dfrac{L_A}{L_B}$ 는?","식":["$M_A-M_B=4.8-1.3=3.5$","$\\dfrac{L_A}{L_B}=\\dfrac{L}{kL}=\\dfrac{1}{k}$","$3.5=-2.5\\log\\dfrac{1}{k}$"],"설명":"별 $\\mathrm{A}$ 의 광도는 $L$, 별 $\\mathrm{B}$ 의 광도는 $kL$ 이다. 광도의 단위가 같으므로 $L$ 은 약분된다.","확인":"3.5","스킬":"C7"},{"제목":"log k 구하기","고비":true,"힌트":"$\\log\\dfrac{1}{k}$ 를 $\\log k$ 로 바꾸면?","식":["$3.5=2.5\\log k$","$\\log k=\\dfrac{3.5}{2.5}=\\dfrac{7}{5}$"],"설명":"$\\log\\dfrac{1}{k}=-\\log k$ 이므로 $-2.5\\log\\dfrac{1}{k}=2.5\\log k$ 이다.","확인":"7/5","스킬":"A9"},{"제목":"k 의 값 구하기","힌트":"$\\log k=\\dfrac{7}{5}$ 을 지수로 바꾸면?","식":["$k=10^{\\frac{7}{5}}$"],"설명":"상용로그이므로 밑은 $10$ 이다. $\\log k=\\dfrac{7}{5}$ 이면 $k=10^{\\frac{7}{5}}$ 이다.","확인":null,"스킬":"A9"}]},"고2-202006-14":{"길":"역함수 위의 점의 좌표를 맞바꿔 원래 함수의 식에 넣는다","단계":[{"제목":"역함수의 점을 원래 함수의 점으로 바꾸기","힌트":"역함수 위의 점 $(p,q)$ 는 원래 함수 $y=3^x-a$ 위의 어떤 점인가?","식":["$(3,\\log_3 b)\\to(\\log_3 b,\\ 3)$","$(2b,\\log_3 12)\\to(\\log_3 12,\\ 2b)$"],"설명":"역함수의 그래프는 $y=x$ 에 대하여 대칭이므로 $x$ 좌표와 $y$ 좌표를 서로 바꾼 점이 $y=3^x-a$ 위에 있다.","확인":null,"스킬":"T1"},{"제목":"두 점을 대입해 식 세우기","고비":true,"힌트":"$x=\\log_3 b$ 일 때 $3^{x}$ 는?","식":["$3=3^{\\log_3 b}-a=b-a$","$2b=3^{\\log_3 12}-a=12-a$"],"설명":"$3^{\\log_3 N}=N$ 이므로 지수의 로그가 사라지고 $b$, $12$ 가 남는다.","확인":null,"스킬":"A9"},{"제목":"연립해 b 구하기","힌트":"$b-a=3$ 과 $2b=12-a$ 에서 $a$ 를 없애면?","식":["$b-a=3,\\quad 2b+a=12$","$3b=15,\\ b=5$"],"설명":"두 식을 변끼리 더하면 $a$ 가 소거된다.","확인":"5","스킬":"A10"},{"제목":"a+b 계산하기","힌트":"$b=5$ 를 $b-a=3$ 에 넣어 $a$ 를 구한 뒤 $a+b$ 는?","식":["$a=2$","$a+b=2+5=7$"],"설명":"$5-a=3$ 이므로 $a=2$ 이다.","확인":"7","스킬":"A10"}]},"고2-202006-15":{"길":"점근선으로 구간을 나눠 세 구간 모두 만나도록 하는 n 의 범위를 구한다","단계":[{"제목":"점근선과 구간 나누기","힌트":"$y=\\tan\\pi x$ 의 주기와, $0\\le x\\le2$ 안에 있는 점근선은?","식":["주기 $\\dfrac{\\pi}{\\pi}=1$","점근선 $x=\\dfrac{1}{2},\\ x=\\dfrac{3}{2}$"],"설명":"$y=\\tan\\pi x$ 의 주기는 $1$ 이고 $x=\\dfrac{1}{2}$ 에서 점근선이 생긴다. 구간 $0\\le x\\le2$ 는 점근선 두 개로 세 구간으로 나뉜다.","확인":null,"스킬":"T2"},{"제목":"구간마다 만나는 점의 개수 따지기","고비":true,"힌트":"각 구간에서 $\\tan\\pi x$ 는 증가하고 직선은 감소한다. 앞의 두 구간 $\\left[0,\\dfrac{1}{2}\\right)$, $\\left(\\dfrac{1}{2},\\dfrac{3}{2}\\right)$ 에서는 몇 번씩 만나는가?","식":["$\\left[0,\\dfrac{1}{2}\\right)$: 1개","$\\left(\\dfrac{1}{2},\\dfrac{3}{2}\\right)$: 1개"],"설명":"곡선이 증가하고 직선이 감소하므로 각 구간에서 많아야 한 번 만난다. 두 구간은 곡선의 값이 직선의 값을 넘나들므로 항상 한 점에서 만난다. 서로 다른 세 점이 되려면 마지막 구간 $\\left(\\dfrac{3}{2},2\\right]$ 에서도 만나야 한다.","확인":null,"스킬":"G1"},{"제목":"마지막 구간에서 만날 조건","힌트":"$x=2$ 에서 $\\tan\\pi x$ 의 값은 $0$ 이다. 직선이 $x=2$ 에서 $0$ 이하이려면 $x$ 절편은 어디에 있어야 하는가?","식":["$x$ 절편: $-\\dfrac{10}{3}x+n=0$ 에서 $x=\\dfrac{3}{10}n$","$\\dfrac{3}{10}n\\le2,\\quad n\\le\\dfrac{20}{3}$"],"설명":"직선이 감소하므로 $x$ 절편이 $2$ 이하이면 $x=2$ 에서 직선의 값이 $0$ 이하가 되어, $\\left(\\dfrac{3}{2},2\\right]$ 에서 곡선과 만난다.","확인":"20/3","스킬":"G1"},{"제목":"자연수 n 의 최댓값 구하기","힌트":"$n\\le\\dfrac{20}{3}$ 을 만족시키는 가장 큰 자연수는?","식":["$\\dfrac{20}{3}=6.66\\cdots$","$n=6$"],"설명":"$\\dfrac{20}{3}$ 은 $6$ 과 $7$ 사이의 수이므로 자연수 $n$ 의 최댓값은 $6$ 이다.","확인":"6","스킬":"G1"}]},"고2-202006-16":{"길":"두 점을 문자로 놓고 중점·외분점 조건으로 a, b 를 구해 거리를 잰다","단계":[{"제목":"중점 조건으로 ab 구하기","힌트":"$\\mathrm{A}(a,\\log_2 a)$, $\\mathrm{B}(b,\\log_2 b)$ 로 놓고 중점의 $y$ 좌표가 $0$ 이라는 조건을 식으로 쓰면?","식":["$\\dfrac{\\log_2 a+\\log_2 b}{2}=0$","$\\log_2 ab=0,\\ ab=1$"],"설명":"중점이 $x$ 축 위에 있으므로 중점의 $y$ 좌표가 $0$ 이다. 로그의 합은 진수의 곱의 로그이다.","확인":"1","스킬":"C7"},{"제목":"외분점 조건으로 a 와 b 의 관계 구하기","고비":true,"힌트":"$1:2$ 로 외분하는 점의 $x$ 좌표는 $a$, $b$ 로 어떻게 나타내는가?","식":["$\\dfrac{1\\times b-2\\times a}{1-2}=2a-b$","$2a-b=0,\\ b=2a$"],"설명":"외분점의 $x$ 좌표는 $\\dfrac{mx_2-nx_1}{m-n}$ 이다. $y$ 축 위의 점이므로 이 값이 $0$ 이다.","확인":null,"스킬":"S4"},{"제목":"a, b 의 값 구하기","힌트":"$ab=1$ 에 $b=2a$ 를 넣으면 $a$ 는? (단, $a>0$)","식":["$2a^2=1,\\quad a^2=\\dfrac{1}{2}$","$a=\\dfrac{\\sqrt{2}}{2},\\ b=\\sqrt{2}$"],"설명":"로그의 진수는 양수이므로 $a>0$ 이다.","확인":null,"스킬":"A2"},{"제목":"두 점의 좌표 구하기","힌트":"$\\log_2\\dfrac{\\sqrt{2}}{2}$ 는 $2$ 의 몇 제곱의 로그인가?","식":["$\\log_2\\dfrac{\\sqrt{2}}{2}=\\log_2 2^{-\\frac{1}{2}}=-\\dfrac{1}{2}$","$\\mathrm{A}\\left(\\dfrac{\\sqrt{2}}{2},-\\dfrac{1}{2}\\right),\\ \\mathrm{B}\\left(\\sqrt{2},\\dfrac{1}{2}\\right)$"],"설명":"$\\dfrac{\\sqrt{2}}{2}=2^{-\\frac{1}{2}}$ 이고 $\\sqrt{2}=2^{\\frac{1}{2}}$ 이다.","확인":"-1/2","스킬":"A9"},{"제목":"선분 AB 의 길이 구하기","힌트":"두 점의 $x$ 좌표의 차와 $y$ 좌표의 차는 각각?","식":["$\\sqrt{2}-\\dfrac{\\sqrt{2}}{2}=\\dfrac{\\sqrt{2}}{2},\\quad \\dfrac{1}{2}-\\left(-\\dfrac{1}{2}\\right)=1$","$\\overline{\\mathrm{AB}}=\\sqrt{\\left(\\dfrac{\\sqrt{2}}{2}\\right)^2+1^2}=\\sqrt{\\dfrac{3}{2}}=\\dfrac{\\sqrt{6}}{2}$"],"설명":"두 점 사이의 거리는 좌표의 차를 두 변으로 하는 직각삼각형의 빗변이다.","확인":null,"스킬":"S3"}]},"고2-202006-17":{"길":"두 근이 x=π/2 에 대칭임을 써서 코사인으로 바꾼 뒤 k 를 구한다","단계":[{"제목":"두 근의 대칭 관계 찾기","고비":true,"힌트":"$0<k<1$ 일 때 $y=\\sin x$ 의 그래프와 $y=k$ 의 두 교점은 직선 $x=\\dfrac{\\pi}{2}$ 에 대해 어떤 위치인가?","식":["$\\dfrac{\\alpha+\\beta}{2}=\\dfrac{\\pi}{2}$","$\\beta=\\pi-\\alpha$"],"설명":"$y=\\sin x$ 의 그래프는 $x=\\dfrac{\\pi}{2}$ 에 대칭이므로 두 근 $\\alpha$, $\\beta$ 의 중점이 $\\dfrac{\\pi}{2}$ 이다.","확인":null,"스킬":"T5"},{"제목":"(β−α)/2 를 α 로 나타내기","힌트":"$\\beta=\\pi-\\alpha$ 를 $\\dfrac{\\beta-\\alpha}{2}$ 에 넣으면?","식":["$\\dfrac{\\beta-\\alpha}{2}=\\dfrac{\\pi-2\\alpha}{2}=\\dfrac{\\pi}{2}-\\alpha$","$\\sin\\left(\\dfrac{\\pi}{2}-\\alpha\\right)=\\cos\\alpha=\\dfrac{5}{7}$"],"설명":"$\\sin\\left(\\dfrac{\\pi}{2}-\\alpha\\right)=\\cos\\alpha$ 이므로 주어진 조건에서 $\\cos\\alpha$ 의 값이 정해진다.","확인":null,"스킬":"T5"},{"제목":"k 의 제곱 구하기","힌트":"$k=\\sin\\alpha$ 이다. $\\sin^2\\alpha+\\cos^2\\alpha=1$ 을 이용하면 $k^2$ 은?","식":["$k^2=\\sin^2\\alpha=1-\\cos^2\\alpha=1-\\dfrac{25}{49}=\\dfrac{24}{49}$"],"설명":"$\\alpha$ 는 $\\sin x=k$ 의 근이므로 $\\sin\\alpha=k$ 이다.","확인":"24/49","스킬":"T5"},{"제목":"k 의 값 정하기","힌트":"$0<k<1$ 이므로 $k^2=\\dfrac{24}{49}$ 에서 $k$ 는?","식":["$k=\\sqrt{\\dfrac{24}{49}}=\\dfrac{2\\sqrt{6}}{7}$"],"설명":"$k>0$ 이므로 양의 제곱근을 택한다. $\\sqrt{24}=2\\sqrt{6}$ 이다.","확인":null,"스킬":"T5"}]},"고2-202006-18":{"길":"직각삼각형과 이등변삼각형의 각을 이어 가·나·다를 구한 뒤 값을 넣는다","단계":[{"제목":"(가) 구하기","힌트":"삼각형 $\\mathrm{OAB}$ 는 $\\overline{\\mathrm{OA}}=\\overline{\\mathrm{OB}}$ 이고 $\\mathrm{M}$ 은 $\\overline{\\mathrm{AB}}$ 의 중점이다. 직각삼각형 $\\mathrm{OAM}$ 에서 $\\overline{\\mathrm{MA}}$ 는?","식":["$\\overline{\\mathrm{MA}}=\\overline{\\mathrm{OA}}\\sin\\dfrac{\\theta}{2}=\\sin\\dfrac{\\theta}{2}$","$f(\\theta)=\\sin\\dfrac{\\theta}{2}$"],"설명":"이등변삼각형에서 꼭짓점과 밑변의 중점을 이은 선분은 밑변에 수직이고 꼭지각을 이등분한다. 따라서 $\\angle\\mathrm{AOM}=\\dfrac{\\theta}{2}$ 이고 빗변 $\\overline{\\mathrm{OA}}=1$ 이다.","확인":null,"스킬":"S6"},{"제목":"(나) 구하기","힌트":"삼각형 $\\mathrm{AMP}$ 에서 $\\overline{\\mathrm{MA}}=\\overline{\\mathrm{MP}}$ 이고 $\\angle\\mathrm{MAP}=\\dfrac{\\pi}{2}-\\dfrac{\\theta}{2}$ 일 때 $\\angle\\mathrm{AMP}$ 는?","식":["$\\angle\\mathrm{AMP}=\\pi-2\\left(\\dfrac{\\pi}{2}-\\dfrac{\\theta}{2}\\right)=\\theta$","$g(\\theta)=\\theta$"],"설명":"이등변삼각형의 두 밑각은 같고 세 각의 합은 $\\pi$ 이다. 같은 방법으로 $\\angle\\mathrm{BMQ}=\\theta$ 이다.","확인":null,"스킬":"S10"},{"제목":"(다) 구하기","고비":true,"힌트":"세 점 $\\mathrm{A}$, $\\mathrm{M}$, $\\mathrm{B}$ 는 한 직선 위에 있다. $\\angle\\mathrm{PMQ}$ 는?","식":["$\\angle\\mathrm{PMQ}=\\pi-\\angle\\mathrm{AMP}-\\angle\\mathrm{BMQ}=\\pi-2\\theta$","$h(\\theta)=\\pi-2\\theta$"],"설명":"평각 $\\pi$ 에서 두 각 $\\angle\\mathrm{AMP}$, $\\angle\\mathrm{BMQ}$ 를 빼면 부채꼴의 중심각이 남는다.","확인":null,"스킬":"S10"},{"제목":"세 함수의 값 구하기","힌트":"$f\\left(\\dfrac{\\pi}{3}\\right)$ 의 값은?","식":["$f\\left(\\dfrac{\\pi}{3}\\right)=\\sin\\dfrac{\\pi}{6}=\\dfrac{1}{2}$","$g\\left(\\dfrac{\\pi}{6}\\right)=\\dfrac{\\pi}{6},\\quad h\\left(\\dfrac{\\pi}{4}\\right)=\\pi-\\dfrac{\\pi}{2}=\\dfrac{\\pi}{2}$"],"설명":"$f$ 에는 $\\dfrac{\\theta}{2}$ 가 들어가므로 $\\sin\\dfrac{\\pi}{6}$ 을 계산한다. $g$ 는 각을 그대로 쓰고 $h$ 는 $\\pi-2\\theta$ 에 넣는다.","확인":"1/2","스킬":"T5"},{"제목":"식의 값 계산하기","힌트":"$\\dfrac{f\\left(\\frac{\\pi}{3}\\right)\\times g\\left(\\frac{\\pi}{6}\\right)}{h\\left(\\frac{\\pi}{4}\\right)}$ 는?","식":["$\\dfrac{\\frac{1}{2}\\times\\frac{\\pi}{6}}{\\frac{\\pi}{2}}=\\dfrac{\\pi}{12}\\times\\dfrac{2}{\\pi}=\\dfrac{1}{6}$"],"설명":"분자는 $\\dfrac{\\pi}{12}$ 이고 분모는 $\\dfrac{\\pi}{2}$ 이다. $\\pi$ 가 약분된다.","확인":"1/6","스킬":"S6"}]},"고2-202006-19":{"길":"지름에 대한 직각으로 BQ 를 구해 Q 의 x좌표를 sin θ 의 이차식으로 쓴다","단계":[{"제목":"PB 의 길이 구하기","힌트":"$\\overline{\\mathrm{AB}}$ 가 원의 지름이면 $\\angle\\mathrm{APB}$ 는? 그때 직각삼각형 $\\mathrm{APB}$ 에서 $\\overline{\\mathrm{PB}}$ 는?","식":["$\\angle\\mathrm{APB}=\\dfrac{\\pi}{2}$","$\\overline{\\mathrm{PB}}=\\overline{\\mathrm{AB}}\\sin\\theta=2\\sin\\theta$"],"설명":"지름에 대한 원주각은 직각이다. $\\overline{\\mathrm{AB}}=2$ 이고 $\\angle\\mathrm{PAB}=\\theta$ 이므로 $\\theta$ 의 대변 $\\overline{\\mathrm{PB}}$ 는 빗변에 $\\sin\\theta$ 를 곱한 값이다.","확인":null,"스킬":"S5"},{"제목":"BQ 의 길이 구하기","힌트":"$\\overline{\\mathrm{PQ}}=3$ 이고 $\\overline{\\mathrm{PB}}=2\\sin\\theta$ 일 때 $\\overline{\\mathrm{BQ}}$ 는?","식":["$\\overline{\\mathrm{BQ}}=3-2\\sin\\theta$"],"설명":"$\\overline{\\mathrm{PB}}<3$ 이므로 $\\mathrm{Q}$ 는 $\\mathrm{B}$ 를 지나 반직선 $\\mathrm{PB}$ 의 연장선 위에 있다. 따라서 $\\overline{\\mathrm{PQ}}-\\overline{\\mathrm{PB}}$ 가 $\\overline{\\mathrm{BQ}}$ 이다.","확인":null,"스킬":"S10"},{"제목":"Q 의 x좌표를 sin θ 로 나타내기","고비":true,"힌트":"$\\angle\\mathrm{PBA}$ 의 크기와, $\\overline{\\mathrm{BQ}}$ 가 $x$ 축과 이루는 각은?","식":["$\\angle\\mathrm{PBA}=\\dfrac{\\pi}{2}-\\theta$","$x_{\\mathrm{Q}}=1+\\overline{\\mathrm{BQ}}\\cos\\left(\\dfrac{\\pi}{2}-\\theta\\right)$","$x_{\\mathrm{Q}}=1+(3-2\\sin\\theta)\\sin\\theta=1+3\\sin\\theta-2\\sin^2\\theta$"],"설명":"$\\mathrm{Q}$ 는 $\\mathrm{PB}$ 의 연장선 위에 있어 $\\angle\\mathrm{PBA}$ 의 맞꼭지각을 이룬다. $\\mathrm{B}$ 의 $x$ 좌표 $1$ 에 $\\overline{\\mathrm{BQ}}$ 의 가로 성분을 더한다. $\\cos\\left(\\dfrac{\\pi}{2}-\\theta\\right)=\\sin\\theta$ 이다.","확인":null,"스킬":"S6"},{"제목":"완전제곱식으로 최대 찾기","힌트":"$\\sin\\theta=s$ 로 놓은 이차식 $-2s^2+3s+1$ 을 완전제곱식으로 고치면 어느 $s$ 에서 최대인가?","식":["$-2s^2+3s+1=-2\\left(s-\\dfrac{3}{4}\\right)^2+\\dfrac{17}{8}$","$s=\\dfrac{3}{4}$ 일 때 최대"],"설명":"$s^2$ 의 계수가 음수이므로 꼭짓점에서 최대이다. $0<\\theta<\\dfrac{\\pi}{2}$ 에서 $0<s<1$ 이므로 $s=\\dfrac{3}{4}$ 가 범위 안에 있다.","확인":"3/4","스킬":"A6"},{"제목":"sin²θ 의 값 구하기","힌트":"$\\sin\\theta=\\dfrac{3}{4}$ 일 때 $\\sin^2\\theta$ 는?","식":["$\\sin^2\\theta=\\left(\\dfrac{3}{4}\\right)^2=\\dfrac{9}{16}$"],"설명":"최대가 되는 순간의 $\\sin\\theta$ 를 제곱한다.","확인":"9/16","스킬":"T5"}]},"고2-202006-20":{"길":"네 점의 좌표를 a 로 쓰고 ㄱ, ㄴ, ㄷ 을 차례로 따진다","단계":[{"제목":"ㄱ 판단하기","힌트":"$y=\\log_a x$ 와 $y=2$ 가 만나는 점 $\\mathrm{A}$ 의 $x$ 좌표는?","식":["$\\log_a x=2$","$x=a^2,\\quad \\mathrm{A}(a^2,\\ 2)$"],"설명":"$\\log_a x=2$ 를 지수로 바꾸면 $x=a^2$ 이다. 같은 방법으로 $\\log_{a+2}x=2$ 에서 $\\mathrm{B}\\left((a+2)^2,\\ 2\\right)$ 이다. ㄱ은 참이다.","확인":null,"스킬":"A9"},{"제목":"ㄴ 판단하기","힌트":"점 $\\mathrm{C}\\left(a^2,\\ \\log_{a+2}a^2\\right)$ 일 때 $\\overline{\\mathrm{AC}}=1$ 이면 $a$ 는?","식":["$\\overline{\\mathrm{AC}}=2-\\log_{a+2}a^2=1,\\quad \\log_{a+2}a^2=1$","$a^2=a+2,\\ (a-2)(a+1)=0,\\ a=2$"],"설명":"$\\mathrm{C}$ 가 $\\mathrm{A}$ 의 아래에 있으므로 $\\overline{\\mathrm{AC}}$ 는 두 $y$ 좌표의 차이다. $a>1$ 이므로 $a=-1$ 은 버린다. ㄴ은 참이다.","확인":null,"스킬":"A9"},{"제목":"ㄷ 의 넓이비를 선분의 비로 바꾸기","고비":true,"힌트":"두 삼각형 $\\mathrm{ACB}$, $\\mathrm{ABD}$ 에서 $\\overline{\\mathrm{AC}}$ 와 $\\overline{\\mathrm{BD}}$ 는 $y$ 축에 평행하다. 두 밑변에 대한 높이는 각각?","식":["높이는 두 직선 $x=a^2$, $x=(a+2)^2$ 사이의 거리로 같다","$\\dfrac{S_2}{S_1}=\\dfrac{\\frac{1}{2}\\times\\overline{\\mathrm{BD}}\\times h}{\\frac{1}{2}\\times\\overline{\\mathrm{AC}}\\times h}=\\dfrac{\\overline{\\mathrm{BD}}}{\\overline{\\mathrm{AC}}}$"],"설명":"$\\overline{\\mathrm{AC}}$ 를 밑변으로 한 높이는 $\\mathrm{B}$ 에서 직선 $x=a^2$ 까지의 거리이고, $\\overline{\\mathrm{BD}}$ 를 밑변으로 한 높이는 $\\mathrm{A}$ 에서 직선 $x=(a+2)^2$ 까지의 거리이다. 두 값이 같아 비가 밑변의 비로 줄어든다.","확인":null,"스킬":"S12"},{"제목":"ㄷ 계산하고 결론 내기","힌트":"$t=\\log_a(a+2)$ 로 놓고 $\\overline{\\mathrm{AC}}$, $\\overline{\\mathrm{BD}}$ 를 $t$ 로 나타내면?","식":["$\\overline{\\mathrm{AC}}=2-2\\log_{a+2}a=2-\\dfrac{2}{t},\\quad \\overline{\\mathrm{BD}}=2t-2$","$\\dfrac{\\overline{\\mathrm{BD}}}{\\overline{\\mathrm{AC}}}=\\dfrac{2(t-1)}{\\frac{2(t-1)}{t}}=t=\\log_a(a+2)$"],"설명":"$\\log_{a+2}a=\\dfrac{1}{\\log_a(a+2)}=\\dfrac{1}{t}$ 이다. $\\mathrm{D}$ 의 $y$ 좌표는 $2\\log_a(a+2)$ 이다. ㄷ도 참이므로 ㄱ, ㄴ, ㄷ 모두 옳다.","확인":null,"스킬":"A9"}]},"고2-202006-21":{"길":"sin 4x 의 그래프가 y=1, y=-1 과 만나는 점을 세어 33번째 점의 위치로 n 의 범위를 정한다","단계":[{"제목":"방정식을 두 직선과의 교점으로 바꾸기","힌트":"$\\sin^2(4x)-1=0$ 에서 $\\sin 4x$ 의 값은?","식":["$\\sin^2 4x=1$","$\\sin4x=1$ 또는 $\\sin4x=-1$"],"설명":"실근의 개수는 $y=\\sin4x$ 의 그래프가 직선 $y=1$, $y=-1$ 과 만나는 점의 개수와 같다.","확인":null,"스킬":"T5"},{"제목":"한 주기에서 만나는 점의 개수","힌트":"$y=\\sin4x$ 의 주기는? 한 주기 동안 $y=1$ 과 $y=-1$ 에 몇 번씩 닿는가?","식":["주기 $\\dfrac{2\\pi}{4}=\\dfrac{\\pi}{2}$","한 주기에 $y=1$ 에서 $1$ 개, $y=-1$ 에서 $1$ 개"],"설명":"최댓값 $1$ 과 최솟값 $-1$ 을 한 주기에 한 번씩 갖는다. 따라서 한 주기에 만나는 점은 $2$ 개이다.","확인":"2","스킬":"T2"},{"제목":"33번째 점의 위치 찾기","힌트":"$0<x\\le8\\pi$ 는 몇 주기이고, 그 안의 점은 몇 개인가?","식":["$8\\pi\\div\\dfrac{\\pi}{2}=16$ 주기, $2\\times16=32$개","33번째 점: $x=8\\pi+\\dfrac{\\pi}{8}$ ($\\sin4x=1$)"],"설명":"$x=8\\pi$ 까지 $32$ 개이므로 $33$ 번째 점은 다음 주기에서 처음 만나는 $y=1$ 위의 점이다. 그다음 $34$ 번째 점은 $x=8\\pi+\\dfrac{3}{8}\\pi$ ($y=-1$) 이다.","확인":"32","스킬":"P1"},{"제목":"n 의 범위 구하기","고비":true,"힌트":"$x<\\dfrac{n}{12}\\pi$ 의 범위에 $33$ 번째 점은 들어가고 $34$ 번째 점은 들어가지 않으려면?","식":["$8\\pi+\\dfrac{\\pi}{8}<\\dfrac{n}{12}\\pi\\le8\\pi+\\dfrac{3}{8}\\pi$","$97.5<n\\le100.5$"],"설명":"각 변에 $\\dfrac{12}{\\pi}$ 를 곱하면 $96+1.5<n\\le96+4.5$ 이다.","확인":null,"스킬":"T2"},{"제목":"n 의 값의 합 구하기","힌트":"$97.5<n\\le100.5$ 인 자연수 $n$ 은?","식":["$n=98,\\ 99,\\ 100$","$98+99+100=297$"],"설명":"범위 안의 자연수를 모두 더한다.","확인":"297","스킬":"P1"}]},"고2-202006-22":{"길":"8 을 2 의 거듭제곱으로 바꿔 지수끼리 더한다","단계":[{"제목":"밑을 2로 통일하기","고비":true,"힌트":"$8$ 을 $2$ 의 거듭제곱으로 쓰면 $8^{\\frac{1}{2}}$ 은?","식":["$8^{\\frac{1}{2}}=\\left(2^3\\right)^{\\frac{1}{2}}=2^{\\frac{3}{2}}$"],"설명":"$8=2^3$ 이고 $(a^m)^n=a^{mn}$ 이다.","확인":"3/2","스킬":"A9"},{"제목":"지수끼리 더해 계산하기","힌트":"밑이 같은 두 거듭제곱의 곱은 지수를 어떻게 하는가?","식":["$2^{\\frac{1}{2}}\\times2^{\\frac{3}{2}}=2^{\\frac{1}{2}+\\frac{3}{2}}=2^2=4$"],"설명":"$a^m\\times a^n=a^{m+n}$ 이다.","확인":"4","스킬":"A9"}]},"고2-202006-23":{"길":"로그를 지수로 바꿔 x 를 구한다","단계":[{"제목":"지수 꼴로 바꾸기","고비":true,"힌트":"$\\log_2(x+5)=4$ 를 지수로 나타내면 $x+5$ 는?","식":["$x+5=2^4=16$"],"설명":"$\\log_a N=b$ 는 $N=a^b$ 와 같다.","확인":"16","스킬":"A9"},{"제목":"x 구하기","힌트":"$x+5=16$ 에서 $x$ 는?","식":["$x=16-5=11$"],"설명":"진수 $x+5=16$ 은 양수이므로 조건을 만족시킨다.","확인":"11","스킬":"A9"}]},"고2-202006-24":{"길":"cos²θ 를 1-sin²θ 로 바꿔 sin²θ 하나의 식으로 푼다","단계":[{"제목":"sin²θ 만의 식으로 바꾸기","고비":true,"힌트":"$\\sin^2\\theta+\\cos^2\\theta=1$ 로 $\\cos^2\\theta$ 를 바꿔 넣으면?","식":["$2\\left(1-\\sin^2\\theta\\right)-\\sin^2\\theta=1$","$2-3\\sin^2\\theta=1$"],"설명":"$\\cos^2\\theta=1-\\sin^2\\theta$ 를 대입하면 문자가 $\\sin^2\\theta$ 하나만 남는다.","확인":null,"스킬":"T5"},{"제목":"sin²θ 의 값 구하기","힌트":"$2-3\\sin^2\\theta=1$ 에서 $\\sin^2\\theta$ 는?","식":["$3\\sin^2\\theta=1$","$\\sin^2\\theta=\\dfrac{1}{3}$"],"설명":"$\\sin^2\\theta$ 를 한 문자로 보고 일차방정식을 푼다.","확인":"1/3","스킬":"T5"},{"제목":"60sin²θ 계산하기","힌트":"구한 값에 $60$ 을 곱하면?","식":["$60\\sin^2\\theta=60\\times\\dfrac{1}{3}=20$"],"설명":"$\\dfrac{1}{3}$ 에 $60$ 을 곱한다.","확인":"20","스킬":"T5"}]},"고2-202006-25":{"길":"sin(x+π/2) 를 cos x 로 바꾼 뒤 점의 좌표를 넣는다","단계":[{"제목":"식을 코사인으로 바꾸기","고비":true,"힌트":"$\\sin\\left(x+\\dfrac{\\pi}{2}\\right)$ 는 어떤 삼각함수와 같은가?","식":["$\\sin\\left(x+\\dfrac{\\pi}{2}\\right)=\\cos x$","$y=k\\cos x+10$"],"설명":"$\\dfrac{\\pi}{2}$ 만큼 평행이동한 사인 그래프는 코사인 그래프와 같다.","확인":null,"스킬":"T5"},{"제목":"점의 좌표 대입하기","힌트":"$x=\\dfrac{\\pi}{3}$, $y=14$ 를 넣을 때 $\\cos\\dfrac{\\pi}{3}$ 의 값은?","식":["$14=k\\cos\\dfrac{\\pi}{3}+10$","$\\cos\\dfrac{\\pi}{3}=\\dfrac{1}{2}$"],"설명":"단위원에서 $\\dfrac{\\pi}{3}$ 의 $x$ 좌표가 $\\dfrac{1}{2}$ 이다.","확인":"1/2","스킬":"T5"},{"제목":"k 의 값 구하기","힌트":"$14=\\dfrac{1}{2}k+10$ 을 풀면?","식":["$\\dfrac{1}{2}k=4$","$k=8$"],"설명":"$10$ 을 이항한 뒤 양변에 $2$ 를 곱한다.","확인":"8","스킬":"T5"}]},"고2-202006-26":{"길":"(가)에서 a 를 구하고 (나)의 두 로그를 곱해 log_a b 하나로 만든다","단계":[{"제목":"a 의 값 구하기","힌트":"$\\log_2(\\log_4a)=1$ 을 바깥 로그부터 지수로 바꾸면?","식":["$\\log_4a=2^1=2$","$a=4^2=16$"],"설명":"$\\log_2 N=1$ 이면 $N=2$ 이므로 $\\log_4a=2$ 이다. 한 번 더 지수로 바꾼다.","확인":"16","스킬":"A9"},{"제목":"(나)를 log_a b 로 줄이기","고비":true,"힌트":"$\\log_a5\\times\\log_5b$ 의 밑을 같은 상용로그로 바꿔 곱하면?","식":["$\\log_a5\\times\\log_5b=\\dfrac{\\log5}{\\log a}\\times\\dfrac{\\log b}{\\log5}=\\dfrac{\\log b}{\\log a}=\\log_ab$","$\\log_ab=\\dfrac{3}{2}$"],"설명":"밑변환 공식으로 두 로그를 분수로 쓰면 $\\log5$ 가 약분되어 $\\log_ab$ 만 남는다.","확인":null,"스킬":"A9"},{"제목":"b 의 값 구하기","힌트":"$\\log_ab=\\dfrac{3}{2}$ 를 지수로 바꾸고 $a=16$ 을 넣으면?","식":["$b=a^{\\frac{3}{2}}=16^{\\frac{3}{2}}=\\left(4^2\\right)^{\\frac{3}{2}}=4^3=64$"],"설명":"$16=4^2$ 으로 쓰면 지수가 약분된다.","확인":"64","스킬":"A9"},{"제목":"a+b 계산하기","힌트":"구한 두 값을 더하면?","식":["$a+b=16+64=80$"],"설명":"$a=16$, $b=64$ 이다.","확인":"80","스킬":"A9"}]},"고2-202006-27":{"길":"A 의 x좌표를 -a, B 의 x좌표를 5a 로 놓고 두 함숫값이 같다는 식으로 a 와 k 를 구한다","단계":[{"제목":"A, B 의 x좌표 놓기","힌트":"$\\overline{\\mathrm{AC}}:\\overline{\\mathrm{CB}}=1:5$ 이고 $\\mathrm{C}$ 는 $y$ 축 위의 점이다. $\\mathrm{A}$ 의 $x$ 좌표를 $-a$ ($a>0$) 라 하면 $\\mathrm{B}$ 의 $x$ 좌표는?","식":["$x_{\\mathrm{A}}=-a,\\quad x_{\\mathrm{B}}=5a$"],"설명":"세 점이 직선 $y=k$ 위에 있고 $\\mathrm{C}$ 의 $x$ 좌표가 $0$ 이므로 선분의 길이비가 $x$ 좌표의 절댓값의 비이다. 그림에서 $\\mathrm{A}$ 는 $y$ 축의 왼쪽, $\\mathrm{B}$ 는 오른쪽에 있다.","확인":null,"스킬":"G1"},{"제목":"두 점의 y좌표가 같다는 식 세우기","힌트":"$\\mathrm{A}$ 는 $y=f(x)$ 위에, $\\mathrm{B}$ 는 $y=g(x)$ 위에 있고 두 점의 $y$ 좌표는 모두 $k$ 이다. 이를 식으로 쓰면?","식":["$f(-a)=g(5a)$","$\\left(\\dfrac{1}{2}\\right)^{-a-1}=4^{5a-1}$"],"설명":"$f(x)=\\left(\\dfrac{1}{2}\\right)^{x-1}$ 에 $x=-a$ 를, $g(x)=4^{x-1}$ 에 $x=5a$ 를 넣는다.","확인":null,"스킬":"G1"},{"제목":"밑을 2로 통일해 a 구하기","고비":true,"힌트":"$\\dfrac{1}{2}=2^{-1}$, $4=2^2$ 으로 쓰고 지수를 비교하면?","식":["$2^{a+1}=2^{10a-2}$","$a+1=10a-2,\\quad a=\\dfrac{1}{3}$"],"설명":"밑이 같은 두 거듭제곱이 같으면 지수가 같다.","확인":"1/3","스킬":"A9"},{"제목":"k 구하기","힌트":"점 $(5a,\\ k)$ 가 $y=g(x)$ 위에 있다. $a=\\dfrac{1}{3}$ 을 넣으면 $k$ 는?","식":["$k=g(5a)=4^{5a-1}=4^{\\frac{2}{3}}$"],"설명":"$5a-1=\\dfrac{5}{3}-1=\\dfrac{2}{3}$ 이다.","확인":null,"스킬":"A9"},{"제목":"k³ 계산하기","힌트":"$k=4^{\\frac{2}{3}}$ 의 세제곱은?","식":["$k^3=\\left(4^{\\frac{2}{3}}\\right)^3=4^2=16$"],"설명":"$(a^m)^n=a^{mn}$ 이므로 지수 $\\dfrac{2}{3}\\times3=2$ 이다.","확인":"16","스킬":"A9"}]},"고2-202006-28":{"길":"A, B 의 자연수 원소의 조건을 구해 C={2,4,6} 이 되는 k 의 범위를 센다","단계":[{"제목":"A 에 속하는 자연수의 조건","힌트":"자연수 $x$ 가 $\\sqrt{a}$ 꼴이려면 $a$ 는 얼마이고, 그 $a$ 가 범위 $1\\le a\\le k$ 에 들어갈 조건은?","식":["$\\sqrt{a}=x\\ \\Rightarrow\\ a=x^2$","$x\\in A\\iff x^2\\le k$"],"설명":"$x$ 가 자연수이면 $a=x^2$ 도 자연수이므로 $x=\\sqrt{a}$ 로 나타낼 수 있다. 단 $a\\le k$ 이어야 한다. 표에서 $a=1,4,9,\\cdots$ 일 때 $\\sqrt{a}=1,2,3,\\cdots$ 이다.","확인":null,"스킬":"N8"},{"제목":"B 에 속하는 자연수의 조건","고비":true,"힌트":"$\\log_{\\sqrt{3}}b=x$ 를 지수로 바꾸면 $b$ 는? $b$ 가 자연수이려면 $x$ 는 어떤 수여야 하는가?","식":["$b=(\\sqrt{3})^x=3^{\\frac{x}{2}}$","$x=2,4,6,8,\\cdots$ 일 때 $b=3,9,27,81,\\cdots$"],"설명":"$3^{\\frac{x}{2}}$ 이 자연수이려면 $\\dfrac{x}{2}$ 가 자연수이어야 하므로 $x$ 는 짝수이다. $x\\in B$ 이려면 $3^{\\frac{x}{2}}\\le k$ 도 필요하다.","확인":null,"스킬":"A9"},{"제목":"2, 4, 6 이 모두 C 에 들어갈 조건","힌트":"$x$ 가 $C$ 에 들어가려면 $k\\ge x^2$ 과 $k\\ge3^{\\frac{x}{2}}$ 이 모두 필요하다. $x=2,4,6$ 이 모두 들어가기 위한 $k$ 의 최솟값은?","식":["$x=2$: $\\max(4,3)=4$","$x=4$: $\\max(16,9)=16$","$x=6$: $\\max(36,27)=36$"],"설명":"$x$ 가 클수록 필요한 $k$ 가 커지므로 $C$ 의 원소는 작은 짝수부터 채워진다. $n(C)=3$ 이면 $C=\\{2,4,6\\}$ 이고, $x=6$ 이 들어가려면 $k\\ge36$ 이다.","확인":"36","스킬":"N8"},{"제목":"8 이 C 에 들어가지 않을 조건","힌트":"$x=8$ 이 $C$ 에 들어가기 시작하는 $k$ 를 구하면, $x=8$ 이 들어가지 않는 $k$ 의 최댓값은?","식":["$x=8$: $\\max(64,81)=81$","$k<81,\\quad k\\le80$"],"설명":"$k\\ge81$ 이면 $8\\in C$ 가 되어 $n(C)\\ge4$ 이다. 따라서 $k\\le80$ 이다.","확인":"80","스킬":"N8"},{"제목":"k 의 개수 세기","힌트":"$36\\le k\\le80$ 인 자연수 $k$ 의 개수는?","식":["$80-36+1=45$"],"설명":"양 끝을 모두 포함하므로 차에 $1$ 을 더한다.","확인":"45","스킬":"N8"}]},"고2-202006-29":{"길":"감소함수라는 점으로 두 교점이 제2·4사분면에 있을 조건을 세우고 k 의 범위를 합친다","단계":[{"제목":"두 교점의 위치 정하기","힌트":"$x$ 가 커지면 $f(x)$ 는 커지는가 작아지는가? 그러면 (가), (나)를 만족시키는 두 교점의 부호는?","식":["$a<0<b$","$f(a)>0>f(b)$"],"설명":"밑 $\\dfrac{1}{2}$ 이 $1$ 보다 작아 $f$ 는 감소한다. (가)에서 $a$, $b$ 는 부호가 다르고, (나)에서 $f(a)$, $f(b)$ 도 부호가 다르다. $f$ 가 감소하므로 왼쪽 점의 $y$ 좌표가 양수이다. 곡선은 제2사분면에서 원과 만나고 제4사분면에서 다시 만난다.","확인":null,"스킬":"G1"},{"제목":"원과의 위치를 부등식 세 개로 옮기기","고비":true,"힌트":"곡선이 원의 위쪽 왼편에서 들어와 아래쪽 오른편으로 나가려면, $x=-8$, $x=0$, $x=8$ 에서 $f$ 의 값은 각각 어떤 범위인가?","식":["$-8<f(0)<8$","$f(-8)>0,\\quad f(8)<0$"],"설명":"$x=0$ 에서 곡선이 원 안에 있어야 하고, 원의 왼쪽 끝 $x=-8$ 에서는 $x$ 축 위쪽, 오른쪽 끝 $x=8$ 에서는 $x$ 축 아래쪽에 있어야 한다.","확인":null,"스킬":"C7"},{"제목":"f(0) 조건으로 k 범위 구하기","힌트":"$-8<2\\log_{\\frac{1}{2}}(k-7)+2<8$ 에서 $\\log_{\\frac{1}{2}}(k-7)$ 의 범위는?","식":["$-5<\\log_{\\frac{1}{2}}(k-7)<3$","$\\left(\\dfrac{1}{2}\\right)^3<k-7<\\left(\\dfrac{1}{2}\\right)^{-5}$","$\\dfrac{57}{8}<k<39$"],"설명":"밑이 $1$ 보다 작아 지수로 바꿀 때 부등호의 방향이 바뀐다. $\\dfrac{1}{8}<k-7<32$ 이다.","확인":null,"스킬":"A9"},{"제목":"f(−8) 조건으로 k 범위 구하기","힌트":"$2\\log_{\\frac{1}{2}}(k-15)+2>0$ 을 풀면?","식":["$\\log_{\\frac{1}{2}}(k-15)>-1$","$k-15<2,\\quad k<17$"],"설명":"밑이 $1$ 보다 작아 지수로 바꾸면 부등호의 방향이 바뀐다. $k\\le15$ 이면 $x=-8$ 에서 정의되지 않지만 곡선이 점근선을 따라 위에서 내려오므로 조건이 성립한다.","확인":null,"스킬":"A9"},{"제목":"f(8) 조건으로 k 범위 구하기","힌트":"$2\\log_{\\frac{1}{2}}(1+k)+2<0$ 을 풀면?","식":["$\\log_{\\frac{1}{2}}(1+k)<-1$","$1+k>2,\\quad k>1$"],"설명":"같은 방법으로 지수로 바꾸고 부등호의 방향을 뒤집는다.","확인":null,"스킬":"A9"},{"제목":"범위를 합쳐 자연수 k 의 최솟값 구하기","힌트":"세 범위 $\\dfrac{57}{8}<k<39$, $k<17$, $k>1$ 의 공통 범위에서 가장 작은 자연수는?","식":["$\\dfrac{57}{8}<k<17$","$\\dfrac{57}{8}=7.125$ 이므로 $m=8$"],"설명":"세 조건을 모두 만족시키는 범위는 $\\dfrac{57}{8}<k<17$ 이다.","확인":"8","스킬":"G1"},{"제목":"최댓값과 M+m 구하기","힌트":"$k<17$ 인 가장 큰 자연수는? 그때 $M+m$ 은?","식":["$M=16$","$M+m=16+8=24$"],"설명":"$k$ 는 $8,9,\\cdots,16$ 이다.","확인":"24","스킬":"G1"}]},"고2-202006-30":{"길":"(가)로 a≤π 를, 경우를 나눠 a=π 와 k=-1/2 를 확정한 뒤 |f|=1/4 의 근의 합을 대칭으로 구한다","단계":[{"제목":"(가)로 a 의 범위 좁히기","힌트":"$a>\\pi$ 이면 $\\pi<x<a$ 에서 $\\sin x$ 의 부호는? 그때 $\\left|\\sin x-\\dfrac{1}{2}\\right|$ 는 $\\dfrac{1}{2}$ 과 비교해 어떤가?","식":["$\\pi<x<a$ 이면 $\\sin x<0$, $\\sin x-\\dfrac{1}{2}<-\\dfrac{1}{2}$","$|f(x)|>\\dfrac{1}{2}$ 이므로 (가)에 어긋난다.  $0<a\\le\\pi$"],"설명":"(가)는 $|f(x)|\\le\\dfrac{1}{2}$ 이라는 뜻이다. $x<a$ 의 범위에서 $f(x)=\\sin x-\\dfrac{1}{2}$ 이므로 $\\sin x<0$ 인 구간이 들어가면 안 된다.","확인":null,"스킬":"C9"},{"제목":"k>0 인 경우와 k=0 인 경우 가려내기","고비":true,"힌트":"$a\\le\\pi$ 일 때 $a\\le x\\le2\\pi$ 에는 $x=\\dfrac{3}{2}\\pi$ 가 들어 있다. $k>0$ 이면 이 점에서 $f$ 의 값은? $k=0$ 이면 (나)의 실근은 몇 개까지 가능한가?","식":["$k>0$: $f\\left(\\dfrac{3}{2}\\pi\\right)=-k-\\dfrac{1}{2}$, $|f|=k+\\dfrac{1}{2}>\\dfrac{1}{2}$","$k=0$: $f(x)=-\\dfrac{1}{2}$ ($a\\le x\\le2\\pi$), 실근은 $0\\le x<a$ 에서 최대 $2$개"],"설명":"$k>0$ 이면 (가)가 깨지고, $k=0$ 이면 (나)의 실근 $3$ 개가 불가능하다. 따라서 $k<0$ 이다.","확인":null,"스킬":"C2"},{"제목":"k<0 일 때 a 확정하기","힌트":"$k<0$ 이고 $0<a<\\pi$ 이면 $\\sin a$ 의 부호는? $f(a)=k\\sin a-\\dfrac{1}{2}$ 는 $-\\dfrac{1}{2}$ 보다 큰가 작은가?","식":["$\\sin a>0,\\ k<0$ 이므로 $f(a)=k\\sin a-\\dfrac{1}{2}<-\\dfrac{1}{2}$","$|f(a)|>\\dfrac{1}{2}$ 이므로 (가)에 어긋난다.  $a=\\pi$"],"설명":"$a<\\pi$ 이면 $x=a$ 에서 $k\\sin a$ 가 음수가 되어 (가)가 깨진다. $0<a\\le\\pi$ 였으므로 $a=\\pi$ 만 남는다.","확인":null,"스킬":"C2"},{"제목":"(나)로 k 구하기","힌트":"$0\\le x<\\pi$ 에서 $\\sin x=\\dfrac{1}{2}$ 의 근은 몇 개인가? 그러면 $\\pi\\le x\\le2\\pi$ 에서 $f(x)=0$ 의 근은 몇 개여야 하는가?","식":["$[0,\\pi)$ 에서 $\\sin x=\\dfrac{1}{2}$: $\\dfrac{\\pi}{6},\\ \\dfrac{5}{6}\\pi$ 의 $2$개","$[\\pi,2\\pi]$ 에서 근이 $1$개이려면 $x=\\dfrac{3}{2}\\pi$ 에서 $f=0$","$k\\times(-1)-\\dfrac{1}{2}=0,\\quad k=-\\dfrac{1}{2}$"],"설명":"$[\\pi,2\\pi]$ 에서 $k\\sin x-\\dfrac{1}{2}$ 의 최댓값은 $x=\\dfrac{3}{2}\\pi$ 에서 $-k-\\dfrac{1}{2}$ 이다. 이 값이 $0$ 이면 근이 $1$ 개, $0$ 보다 크면 $2$ 개이다. 전체 실근이 $3$ 개이므로 최댓값이 $0$ 이다.","확인":"-1/2","스킬":"C2"},{"제목":"0≤x<π 에서 |f|=1/4 의 근의 합","힌트":"$\\left|\\sin x-\\dfrac{1}{2}\\right|=\\dfrac{1}{4}$ 를 풀면 $\\sin x$ 는 어떤 값이고, 근은 모두 몇 개인가?","식":["$\\sin x=\\dfrac{3}{4}$ 또는 $\\sin x=\\dfrac{1}{4}$","각각 $x=p$, $\\pi-p$ 의 두 근 → 근 $4$개, 합 $\\pi+\\pi=2\\pi$"],"설명":"$[0,\\pi)$ 에서 $y=\\sin x$ 는 직선 $x=\\dfrac{\\pi}{2}$ 에 대칭이므로 같은 값을 갖는 두 근의 합은 $\\pi$ 이다. 두 값에 대해 합이 $\\pi$ 인 쌍이 $2$ 개이다.","확인":null,"스킬":"T2"},{"제목":"π≤x≤2π 에서 |f|=1/4 의 근의 합 S","힌트":"$\\pi\\le x\\le2\\pi$ 에서 $f(x)=-\\dfrac{1}{2}\\sin x-\\dfrac{1}{2}$ 이다. $|f(x)|=\\dfrac{1}{4}$ 의 두 근은 어느 직선에 대칭인가?","식":["$\\dfrac{\\alpha_5+\\alpha_6}{2}=\\dfrac{3\\pi}{2}$, $\\alpha_5+\\alpha_6=3\\pi$","$S=2\\pi+3\\pi=5\\pi$"],"설명":"$f$ 는 $x=\\dfrac{3}{2}\\pi$ 에서 $0$ 이 되고 그 양쪽으로 대칭인 모양이므로 $|f|=\\dfrac{1}{4}$ 의 두 근의 합은 $2\\times\\dfrac{3}{2}\\pi=3\\pi$ 이다.","확인":null,"스킬":"T2"},{"제목":"구하는 값 계산하기","힌트":"$a=\\pi$, $S=5\\pi$, $k=-\\dfrac{1}{2}$ 를 식에 넣으면?","식":["$20\\left(\\dfrac{\\pi+5\\pi}{\\pi}-\\dfrac{1}{2}\\right)=20\\left(6-\\dfrac{1}{2}\\right)=20\\times\\dfrac{11}{2}=110$"],"설명":"$\\dfrac{a+S}{\\pi}=\\dfrac{6\\pi}{\\pi}=6$ 이다.","확인":"110","스킬":"C2"}]},"고2-202009-04":{"길":"2π/3 을 π−π/3 으로 쓰고 제2사분면 부호를 붙인다","단계":[{"제목":"π 에서 기준각을 빼는 꼴로 나타내기","힌트":"$\\dfrac{2}{3}\\pi$ 를 $\\pi$ 와 $\\dfrac{\\pi}{3}$ 로 어떻게 쓸까?","식":["$\\dfrac{2}{3}\\pi=\\pi-\\dfrac{\\pi}{3}$"],"설명":"$\\dfrac{2}{3}\\pi$ 는 제2사분면의 각이고 기준각은 $\\dfrac{\\pi}{3}$ 이다.","확인":null,"스킬":"T5"},{"제목":"부호를 붙여 값 구하기","고비":true,"힌트":"$\\cos\\left(\\pi-\\dfrac{\\pi}{3}\\right)$ 는 $\\cos\\dfrac{\\pi}{3}$ 와 부호가 같은가 다른가?","식":["$\\cos\\left(\\pi-\\dfrac{\\pi}{3}\\right)=-\\cos\\dfrac{\\pi}{3}=-\\dfrac{1}{2}$"],"설명":"제2사분면에서 $x$ 좌표에 해당하는 코사인은 음수이다. $\\cos\\dfrac{\\pi}{3}=\\dfrac{1}{2}$ 이다.","확인":"-1/2","스킬":"T5"}]},"고2-202009-06":{"길":"부채꼴 넓이 공식에 중심각과 넓이를 넣어 r 을 구한다","단계":[{"제목":"공식에 넣어 r² 구하기","고비":true,"힌트":"반지름 $r$, 중심각 $\\dfrac{\\pi}{4}$ 인 부채꼴의 넓이를 식으로 쓰고 $8\\pi$ 와 같게 놓으면?","식":["$\\dfrac{1}{2}\\times r^2\\times\\dfrac{\\pi}{4}=8\\pi$","$\\dfrac{\\pi}{8}r^2=8\\pi,\\quad r^2=64$"],"설명":"중심각이 $\\theta$ 인 부채꼴의 넓이는 $\\dfrac{1}{2}r^2\\theta$ 이다. 양변을 $\\dfrac{\\pi}{8}$ 로 나눈다.","확인":"64","스킬":"C7"},{"제목":"r 구하기","힌트":"$r^2=64$ 에서 반지름 $r$ 은?","식":["$r=8$"],"설명":"반지름은 양수이므로 $r>0$ 인 값을 택한다.","확인":"8","스킬":"C7"}]},"고2-202009-07":{"길":"점화식에 a_4 부터 거꾸로 대입해 a_3, a_2 를 구한다","단계":[{"제목":"a₃ 구하기","고비":true,"힌트":"$a_{n+1}=2a_n+1$ 에 $n=3$ 을 넣고 $a_4=31$ 을 쓰면 $a_3$ 은?","식":["$a_4=2a_3+1=31$","$a_3=15$"],"설명":"$a_4$ 가 $a_3$ 으로 정해지는 식이므로 $a_3$ 에 대한 일차방정식을 푼다.","확인":"15","스킬":"C5"},{"제목":"a₂ 구하기","힌트":"$n=2$ 를 넣고 $a_3=15$ 를 쓰면 $a_2$ 는?","식":["$a_3=2a_2+1=15$","$a_2=7$"],"설명":"같은 방법으로 한 번 더 거꾸로 올라간다.","확인":"7","스킬":"C5"}]},"고2-202009-08":{"길":"log_8 b 를 밑 2 로 바꿔 b=a³ 임을 얻고 log_a b 를 구한다","단계":[{"제목":"밑을 2로 통일하기","힌트":"$8=2^3$ 이므로 $\\log_8b$ 를 밑이 $2$ 인 로그로 쓰면?","식":["$\\log_8b=\\log_{2^3}b=\\dfrac{1}{3}\\log_2b$"],"설명":"$\\log_{a^m}b=\\dfrac{1}{m}\\log_ab$ 이다.","확인":null,"스킬":"A9"},{"제목":"a 와 b 의 관계 구하기","고비":true,"힌트":"$\\log_2a=\\dfrac{1}{3}\\log_2b$ 에서 양변에 $3$ 을 곱해 진수끼리 비교하면?","식":["$3\\log_2a=\\log_2a^3=\\log_2b$","$b=a^3$"],"설명":"$3\\log_2a=\\log_2a^3$ 이고 로그의 값이 같으면 진수도 같다.","확인":null,"스킬":"A9"},{"제목":"log_a b 계산하기","힌트":"$b=a^3$ 을 $\\log_ab$ 에 넣으면?","식":["$\\log_ab=\\log_aa^3=3$"],"설명":"$\\log_aa^3=3\\log_aa=3$ 이다.","확인":"3","스킬":"A9"}]},"고2-202009-09":{"길":"공비 r 로 세 항을 써서 r 의 이차방정식을 풀고 양수 조건으로 고른다","단계":[{"제목":"공비로 식 세우기","힌트":"첫째항 $a_1$, 공비 $r$ 일 때 $a_2$, $a_3$ 을 $a_1$, $r$ 로 쓰고 $a_3=4a_1+3a_2$ 에 넣으면?","식":["$a_1r^2=4a_1+3a_1r$","$a_1\\left(r^2-3r-4\\right)=0$"],"설명":"$a_2=a_1r$, $a_3=a_1r^2$ 이다. 모든 항이 양수이므로 $a_1>0$ 이고, 양변을 $a_1$ 으로 나눌 수 있다.","확인":null,"스킬":"P1"},{"제목":"공비 정하기","고비":true,"힌트":"$r^2-3r-4=0$ 을 인수분해하면 두 근은? 모든 항이 양수라는 조건으로 하나를 고르면?","식":["$(r-4)(r+1)=0$","$r=4$"],"설명":"모든 항이 양수이면 공비도 양수이다. $r=-1$ 이면 항의 부호가 번갈아 바뀌어 조건에 어긋난다.","확인":"4","스킬":"P1"},{"제목":"a₆/a₄ 계산하기","힌트":"$a_6$ 과 $a_4$ 는 몇 번의 곱으로 이어지는가?","식":["$\\dfrac{a_6}{a_4}=r^2=16$"],"설명":"$a_6=a_4\\times r^2$ 이다.","확인":"16","스킬":"P1"}]},"고2-202009-10":{"길":"사인값의 비를 변의 비로 바꿔 세 변을 k 로 놓고 코사인법칙을 쓴다","단계":[{"제목":"변의 길이의 비 구하기","고비":true,"힌트":"$\\dfrac{2}{\\sin A}=\\dfrac{3}{\\sin B}=\\dfrac{4}{\\sin C}$ 에서 $\\sin A:\\sin B:\\sin C$ 는? 사인법칙으로 $a:b:c$ 는?","식":["$\\sin A:\\sin B:\\sin C=2:3:4$","$a:b:c=2:3:4$"],"설명":"$\\overline{\\mathrm{BC}}=a$, $\\overline{\\mathrm{CA}}=b$, $\\overline{\\mathrm{AB}}=c$ 라 하면 사인법칙에서 $a:b:c=\\sin A:\\sin B:\\sin C$ 이다. 주어진 식에서 각 분모를 분자의 비로 읽는다.","확인":null,"스킬":"S6"},{"제목":"코사인법칙으로 cos C 구하기","힌트":"$a=2k$, $b=3k$, $c=4k$ ($k>0$) 로 놓고 $\\cos C$ 의 식을 세우면?","식":["$\\cos C=\\dfrac{a^2+b^2-c^2}{2ab}=\\dfrac{4k^2+9k^2-16k^2}{12k^2}$","$\\cos C=-\\dfrac{1}{4}$"],"설명":"$\\angle C$ 의 대변이 $c$ 이므로 $c^2$ 을 빼는 꼴이다. $k^2$ 이 약분된다.","확인":"-1/4","스킬":"S6"}]},"고2-202009-11":{"길":"공비 2 를 구하고 두 합을 등비수열의 합으로 써서 2의 n제곱을 구한다","단계":[{"제목":"공비 구하기","힌트":"$a_4=a_2r^2$ 이므로 $a_4=4a_2$ 에서 $r$ 은? (단, $r>0$)","식":["$a_2r^2=4a_2,\\quad r^2=4$","$r=2$"],"설명":"$a_2\\ne0$ 이므로 양변을 $a_2$ 로 나눈다. 공비가 양수이므로 $r=-2$ 는 버린다.","확인":"2","스킬":"P1"},{"제목":"두 합을 등비수열의 합으로 쓰기","고비":true,"힌트":"$a_k^{\\,2}$ 의 첫째항과 공비는? 두 합을 각각 $n$ 으로 나타내면?","식":["$\\displaystyle\\sum_{k=1}^{n}a_k=\\dfrac{\\frac{1}{5}(2^n-1)}{2-1}$","$\\displaystyle\\sum_{k=1}^{n}a_k^{\\,2}=\\dfrac{\\left(\\frac{1}{5}\\right)^2\\left(4^n-1\\right)}{4-1}$"],"설명":"$a_k=\\dfrac{1}{5}\\times2^{k-1}$ 이므로 $a_k^{\\,2}=\\dfrac{1}{25}\\times4^{k-1}$ 이다. 첫째항이 $\\dfrac{1}{25}$, 공비가 $4$ 인 등비수열이다.","확인":null,"스킬":"P6"},{"제목":"방정식을 세워 2ⁿ 구하기","힌트":"두 합을 $\\displaystyle\\sum a_k=\\dfrac{3}{13}\\sum a_k^{\\,2}$ 에 넣고 양변에 $325$ 를 곱한 뒤 $4^n-1=(2^n-1)(2^n+1)$ 로 인수분해하면?","식":["$\\dfrac{1}{5}(2^n-1)=\\dfrac{3}{13}\\times\\dfrac{4^n-1}{75}$","$65\\left(2^n-1\\right)=\\left(2^n-1\\right)\\left(2^n+1\\right)$","$2^n+1=65$"],"설명":"$n\\ge1$ 이므로 $2^n-1\\ne0$ 이다. 양변을 $2^n-1$ 로 나눈다.","확인":"65","스킬":"P6"},{"제목":"n 구하기","힌트":"$2^n+1=65$ 에서 $n$ 은?","식":["$2^n=64=2^6$","$n=6$"],"설명":"$64$ 를 $2$ 의 거듭제곱으로 쓰면 지수가 $n$ 이다.","확인":"6","스킬":"A9"}]},"고2-202009-12":{"길":"sin x 를 t 로 치환해 구간에서 이차식의 최솟값이 0 이상이 되는 k 를 구한다","단계":[{"제목":"치환해 t 의 범위 정하기","힌트":"$\\sin x=t$ 로 놓으면 $t$ 의 범위는? 부등식은 $t$ 로 어떻게 쓰이는가?","식":["$-1\\le t\\le1$","$t^2-4t-5k+5\\ge0$"],"설명":"$0\\le x<2\\pi$ 에서 $\\sin x$ 는 $-1$ 이상 $1$ 이하의 모든 값을 갖는다. 부등식이 항상 성립하려면 이 범위의 모든 $t$ 에서 성립해야 한다.","확인":null,"스킬":"C1"},{"제목":"구간에서 최솟값의 위치 찾기","고비":true,"힌트":"$t^2-4t-5k+5$ 를 완전제곱식으로 고치면 축은? 축이 구간 $-1\\le t\\le1$ 의 안인가 밖인가?","식":["$f(t)=(t-2)^2-5k+1$","축 $t=2$ 는 구간의 오른쪽 밖 → 구간에서 감소 → $t=1$ 에서 최소"],"설명":"$t^2-4t=(t-2)^2-4$ 이므로 $-4+5=1$ 을 더해 정리한다. 축이 구간의 오른쪽에 있어 구간 안에서 감소하므로 오른쪽 끝에서 최솟값을 갖는다. 모든 $t$ 에서 $f(t)\\ge0$ 이려면 최솟값이 $0$ 이상이어야 한다.","확인":null,"스킬":"G7"},{"제목":"최솟값 조건으로 k 의 최댓값 구하기","힌트":"$f(1)\\ge0$ 을 풀면?","식":["$f(1)=(1-2)^2-5k+1=2-5k\\ge0$","$k\\le\\dfrac{2}{5}$"],"설명":"$k$ 의 값이 $\\dfrac{2}{5}$ 이하이면 항상 성립하므로 최댓값은 $\\dfrac{2}{5}$ 이다.","확인":"2/5","스킬":"C1"}]},"고2-202009-13":{"길":"접선 조건을 점과 직선 사이의 거리 1 로 써서 a_n 의 제곱을 구하고 부분분수로 합한다","단계":[{"제목":"접선의 조건을 거리로 쓰기","힌트":"점 $(-1,0)$ 을 지나는 기울기 $a_n$ 의 직선을 식으로 쓰고, 중심 $(n,0)$ 과의 거리를 반지름 $1$ 과 같게 놓으면?","식":["$y=a_n(x+1)$, 즉 $a_nx-y+a_n=0$","$\\dfrac{\\left|a_n(n+1)\\right|}{\\sqrt{a_n^{\\,2}+1}}=1$"],"설명":"원과 직선이 접하면 중심에서 직선까지의 거리가 반지름과 같다. 점과 직선 사이의 거리 공식을 쓴다.","확인":null,"스킬":"S13"},{"제목":"a_n² 구하기","고비":true,"힌트":"양변을 제곱해 분모를 없애면?","식":["$a_n^{\\,2}(n+1)^2=a_n^{\\,2}+1$","$a_n^{\\,2}\\left(n^2+2n\\right)=1,\\quad a_n^{\\,2}=\\dfrac{1}{n(n+2)}$"],"설명":"$a_n^{\\,2}$ 이 들어간 항을 한쪽으로 모으면 $a_n^{\\,2}\\left\\{(n+1)^2-1\\right\\}=1$ 이다.","확인":null,"스킬":"S13"},{"제목":"부분분수로 나누기","힌트":"$\\dfrac{1}{n(n+2)}$ 을 $\\dfrac{1}{n}$ 과 $\\dfrac{1}{n+2}$ 의 차로 쓰면?","식":["$\\dfrac{1}{n(n+2)}=\\dfrac{1}{2}\\left(\\dfrac{1}{n}-\\dfrac{1}{n+2}\\right)$"],"설명":"통분하면 $\\dfrac{1}{n}-\\dfrac{1}{n+2}=\\dfrac{2}{n(n+2)}$ 이므로 $\\dfrac{1}{2}$ 을 곱한다.","확인":null,"스킬":"P6"},{"제목":"n=1 부터 5 까지 합하기","힌트":"합을 전개하면 어떤 항이 남는가?","식":["$\\displaystyle\\sum_{n=1}^{5}a_n^{\\,2}=\\dfrac{1}{2}\\left(1+\\dfrac{1}{2}-\\dfrac{1}{6}-\\dfrac{1}{7}\\right)=\\dfrac{25}{42}$"],"설명":"$\\dfrac{1}{3},\\ \\dfrac{1}{4},\\ \\dfrac{1}{5}$ 는 더해졌다가 빼져 사라지고 앞의 두 항과 뒤의 두 항만 남는다.","확인":"25/42","스킬":"P6"}]},"고2-202009-14":{"길":"각 n 에 대해 해들이 짝으로 대칭인 축을 찾아 합을 구한다","단계":[{"제목":"f(2) 구하기","힌트":"$y=\\sin2x$ 의 주기는? $0\\le x<\\pi$ 에서 $\\sin2x=\\dfrac{1}{5}$ 의 해는 몇 개이고 어느 직선에 대칭인가?","식":["주기 $\\pi$, 해 $2$개, 직선 $x=\\dfrac{\\pi}{4}$ 에 대칭","$f(2)=2\\times\\dfrac{\\pi}{4}=\\dfrac{\\pi}{2}$"],"설명":"$[0,\\pi)$ 는 한 주기이고, 이 주기 안에서 극대인 점 $x=\\dfrac{\\pi}{4}$ 의 양쪽에 해가 한 개씩 있다. 대칭인 두 해의 합은 대칭축의 $2$ 배이다.","확인":"2","스킬":"T5"},{"제목":"n=5 에서 대칭축 찾기","고비":true,"힌트":"$y=\\sin5x$ 의 주기는? $0\\le x<\\pi$ 에서 위로 볼록한 부분(극대인 점)은 몇 개인가?","식":["주기 $\\dfrac{2\\pi}{5}$, 극대인 점 $x=\\dfrac{\\pi}{10},\\ \\dfrac{\\pi}{2},\\ \\dfrac{9\\pi}{10}$"],"설명":"$[0,\\pi)$ 는 $2.5$ 주기이다. 직선 $y=\\dfrac{1}{5}$ 은 $y$ 축 위쪽의 각 볼록한 부분과 두 번씩 만나고, 두 해는 그 부분의 대칭축에 대칭이다. 아래로 볼록한 부분은 만나지 않는다.","확인":"3","스킬":"T2"},{"제목":"f(5) 구하기","힌트":"세 대칭축에 대해 해가 두 개씩 있을 때 해의 합은?","식":["$f(5)=2\\left(\\dfrac{\\pi}{10}+\\dfrac{\\pi}{2}+\\dfrac{9\\pi}{10}\\right)=2\\times\\dfrac{15\\pi}{10}=3\\pi$"],"설명":"대칭인 두 해의 합은 각각 대칭축의 $2$ 배이다.","확인":null,"스킬":"T2"},{"제목":"f(2)+f(5) 구하기","힌트":"앞에서 구한 두 값을 더하면?","식":["$f(2)+f(5)=\\dfrac{\\pi}{2}+3\\pi=\\dfrac{7}{2}\\pi$"],"설명":"$\\dfrac{\\pi}{2}$ 와 $3\\pi$ 를 통분해 더한다.","확인":null,"스킬":"T2"}]},"고2-202009-15":{"길":"진수가 구간에서 양수일 조건과 f(-1)<f(1) 조건을 합쳐 정수 m 을 센다","단계":[{"제목":"정의되는 m 의 범위 구하기","힌트":"$-1\\le x\\le1$ 의 모든 $x$ 에서 $mx+5>0$ 이려면 양 끝 $x=-1$, $x=1$ 에서 어떤 부등식이 필요한가?","식":["$5-m>0,\\quad 5+m>0$","$-5<m<5$"],"설명":"$mx+5$ 는 $x$ 에 대한 일차식이어서 구간의 양 끝에서 양수이면 구간 전체에서 양수이다. 로그의 진수는 양수이어야 한다.","확인":null,"스킬":"T3"},{"제목":"f(−1)<f(1) 로 m 의 부호 정하기","고비":true,"힌트":"$f(-1)$ 과 $f(1)$ 을 쓰고 부등식에 넣은 뒤 부호를 없애면?","식":["$-\\log_3(5-m)<-\\log_3(5+m)$","$\\log_3(5-m)>\\log_3(5+m)$","$5-m>5+m,\\quad m<0$"],"설명":"양변에 $-1$ 을 곱하면 부등호의 방향이 바뀐다. 밑 $3$ 이 $1$ 보다 크므로 진수의 대소가 그대로이다.","확인":null,"스킬":"C2"},{"제목":"정수 m 의 개수 세기","힌트":"$-5<m<5$ 와 $m<0$ 의 공통 범위에서 정수는?","식":["$-5<m<0$","$m=-4,\\ -3,\\ -2,\\ -1\\ \\Rightarrow\\ 4$개"],"설명":"양 끝 $-5$ 와 $0$ 은 포함되지 않는다.","확인":"4","스킬":"T3"}]},"고2-202009-16":{"길":"AD=a 로 놓고 코사인법칙으로 a 를 구한 뒤 넓이의 차로 삼각형 BDE 의 넓이를 구한다","단계":[{"제목":"변의 길이를 a 로 나타내기","힌트":"$\\overline{\\mathrm{AD}}=\\overline{\\mathrm{CE}}=a$ 이면 $\\overline{\\mathrm{AE}}$ 는? 삼각형 $\\mathrm{ADE}$ 에서 $\\angle\\mathrm{A}$ 는?","식":["$\\overline{\\mathrm{AE}}=\\overline{\\mathrm{AC}}+\\overline{\\mathrm{CE}}=a+1$","$\\angle\\mathrm{A}=\\dfrac{\\pi}{3}$"],"설명":"$\\mathrm{E}$ 는 선분 $\\mathrm{AC}$ 의 연장선 위에 있고 $\\overline{\\mathrm{AC}}=1$ 이다. 정삼각형이므로 $\\angle\\mathrm{BAC}=\\dfrac{\\pi}{3}$ 이다.","확인":null,"스킬":"S6"},{"제목":"코사인법칙으로 a 구하기","고비":true,"힌트":"삼각형 $\\mathrm{ADE}$ 에서 $\\overline{\\mathrm{DE}}^{\\,2}$ 를 코사인법칙으로 쓰면?","식":["$13=a^2+(a+1)^2-2a(a+1)\\cos\\dfrac{\\pi}{3}$","$a^2+a-12=0,\\quad (a+4)(a-3)=0$","$a=3$"],"설명":"$\\cos\\dfrac{\\pi}{3}=\\dfrac{1}{2}$ 이므로 $2a(a+1)\\cos\\dfrac{\\pi}{3}=a(a+1)$ 이다. 길이는 양수이므로 $a=-4$ 는 버린다.","확인":"3","스킬":"S6"},{"제목":"삼각형 ADE 의 넓이 구하기","힌트":"$\\overline{\\mathrm{AD}}=3$, $\\overline{\\mathrm{AE}}=4$, 끼인각 $\\dfrac{\\pi}{3}$ 인 삼각형의 넓이는?","식":["$\\triangle\\mathrm{ADE}=\\dfrac{1}{2}\\times4\\times3\\times\\sin\\dfrac{\\pi}{3}=3\\sqrt{3}$"],"설명":"두 변과 끼인각을 알 때 넓이는 $\\dfrac{1}{2}bc\\sin A$ 이다.","확인":null,"스킬":"S8"},{"제목":"넓이의 차로 삼각형 BDE 구하기","힌트":"$\\mathrm{B}$ 는 선분 $\\mathrm{AD}$ 위의 점이다. 삼각형 $\\mathrm{ABE}$ 의 넓이를 빼면?","식":["$\\triangle\\mathrm{ABE}=\\dfrac{1}{2}\\times4\\times1\\times\\sin\\dfrac{\\pi}{3}=\\sqrt{3}$","$\\triangle\\mathrm{BDE}=3\\sqrt{3}-\\sqrt{3}=2\\sqrt{3}$"],"설명":"삼각형 $\\mathrm{ADE}$ 는 삼각형 $\\mathrm{ABE}$ 와 삼각형 $\\mathrm{BDE}$ 로 나뉜다.","확인":null,"스킬":"S8"}]},"고2-202009-17":{"길":"S_13 이 최대라는 조건으로 공차를 정하고 부호가 바뀌는 곳에서 절댓값을 풀어 합을 구한다","단계":[{"제목":"(나)를 항의 부호 조건으로 바꾸기","고비":true,"힌트":"모든 $n$ 에서 $S_n\\le S_{13}$ 이려면 $S_{13}$ 과 $S_{12}$, $S_{14}$ 를 비교해 $a_{13}$, $a_{14}$ 의 부호는?","식":["$S_{13}\\ge S_{12}\\ \\Rightarrow\\ a_{13}\\ge0$","$S_{13}\\ge S_{14}\\ \\Rightarrow\\ a_{14}\\le0$"],"설명":"$S_{13}-S_{12}=a_{13}$ 이고 $S_{14}-S_{13}=a_{14}$ 이다. 합이 $13$ 항에서 최대이면 $13$ 번째 항까지는 더해도 손해가 없고 $14$ 번째 항부터 음수이다.","확인":null,"스킬":"C1"},{"제목":"공차와 첫째항 구하기","힌트":"$a_{13}=37+6d$, $a_{14}=37+7d$ 로 쓰고 부등식을 풀면 정수 $d$ 는?","식":["$37+6d\\ge0,\\ \\ 37+7d\\le0$","$-\\dfrac{37}{6}\\le d\\le-\\dfrac{37}{7}$","$d=-6,\\quad a_1=37-6d=73$"],"설명":"$a_7=37$ 이므로 $a_{13}=a_7+6d$, $a_{14}=a_7+7d$ 이다. $-6.17\\cdots\\le d\\le-5.28\\cdots$ 에서 정수는 $-6$ 뿐이다.","확인":"-6","스킬":"C2"},{"제목":"S₁₃ 구하기","힌트":"첫째항 $73$, 공차 $-6$ 인 등차수열의 첫째항부터 제$13$항까지의 합은?","식":["$S_{13}=\\dfrac{13\\left\\{2\\times73+12\\times(-6)\\right\\}}{2}=\\dfrac{13\\times74}{2}=481$"],"설명":"등차수열의 합 공식 $S_n=\\dfrac{n\\{2a_1+(n-1)d\\}}{2}$ 이다. $a_{13}=1$ 이다.","확인":"481","스킬":"C1"},{"제목":"절댓값을 S 로 바꾸기","힌트":"$a_1,\\cdots,a_{13}$ 은 양수이고 $a_{14},\\cdots,a_{21}$ 은 음수이다. 절댓값을 풀어 $S_{13}$, $S_{21}$ 로 쓰면?","식":["$\\displaystyle\\sum_{k=1}^{21}|a_k|=\\left(a_1+\\cdots+a_{13}\\right)-\\left(a_{14}+\\cdots+a_{21}\\right)$","$=S_{13}-\\left(S_{21}-S_{13}\\right)=2S_{13}-S_{21}$"],"설명":"$a_{14}$ 이후는 음수이므로 절댓값을 벗기면 부호가 바뀐다. $a_{14}+\\cdots+a_{21}=S_{21}-S_{13}$ 이다.","확인":null,"스킬":"C2"},{"제목":"S₂₁ 구해 합 계산하기","힌트":"$S_{21}$ 은? 그때 $2S_{13}-S_{21}$ 은?","식":["$S_{21}=\\dfrac{21\\left\\{2\\times73+20\\times(-6)\\right\\}}{2}=\\dfrac{21\\times26}{2}=273$","$2\\times481-273=689$"],"설명":"$S_{13}=481$ 을 두 배 한 값에서 $S_{21}$ 을 뺀다.","확인":"689","스킬":"C1"}]},"고2-202009-18":{"길":"A, B 의 x 좌표의 합이 0 임을 찾고 보기를 하나씩 좌표로 따진다","단계":[{"제목":"A, B 의 x 좌표 사이의 관계 찾기","힌트":"두 곡선의 식을 같다고 놓고 $2^x=X$ 로 치환하면 $X$ 에 대한 어떤 이차방정식이 되는가? 두 근 $2^\\alpha$, $2^\\beta$ 의 곱은?","식":["$2^x=-2^{-x}+t\\ \\Rightarrow\\ (2^x)^2-t\\cdot2^x+1=0$","$2^\\alpha+2^\\beta=t,\\quad 2^\\alpha\\cdot2^\\beta=1$","$\\alpha+\\beta=0$"],"설명":"$\\mathrm{A}$, $\\mathrm{B}$ 의 $x$ 좌표를 $\\alpha<0<\\beta$ 라 하면 $2^\\alpha$, $2^\\beta$ 는 이 이차방정식의 두 근이다. 근과 계수의 관계에서 곱이 $1$ 이므로 $2^{\\alpha+\\beta}=1$ 이다.","확인":null,"스킬":"A2"},{"제목":"C, D 의 좌표와 ㄱ 판별","힌트":"$x=0$ 을 두 곡선에 각각 대입하면 $\\mathrm{C}$, $\\mathrm{D}$ 의 $y$ 좌표는? 두 점 사이의 거리는?","식":["$\\mathrm{C}(0,1),\\ \\mathrm{D}(0,t-1)$","$\\overline{\\mathrm{CD}}=(t-1)-1=t-2$"],"설명":"$y=-\\left(\\dfrac{1}{2}\\right)^0+t=t-1$ 이다. $t>2$ 이므로 $\\mathrm{D}$ 가 $\\mathrm{C}$ 보다 위에 있고 길이는 $y$ 좌표의 차이다. 따라서 ㄱ 은 옳다.","확인":null,"스킬":"G4"},{"제목":"ㄴ: 두 선분 AC, DB 의 길이 비교","힌트":"$\\overline{\\mathrm{AC}}^{\\,2}$ 와 $\\overline{\\mathrm{DB}}^{\\,2}$ 를 좌표로 쓰고 $2^\\beta=t-2^\\alpha$, $\\beta=-\\alpha$ 를 넣으면?","식":["$\\overline{\\mathrm{AC}}^{\\,2}=\\alpha^2+\\left(2^\\alpha-1\\right)^2$","$\\overline{\\mathrm{DB}}^{\\,2}=\\beta^2+\\left(2^\\beta-t+1\\right)^2=\\alpha^2+\\left(1-2^\\alpha\\right)^2$","$\\overline{\\mathrm{AC}}=\\overline{\\mathrm{DB}}$"],"설명":"$\\mathrm{A}(\\alpha,2^\\alpha)$, $\\mathrm{B}(\\beta,2^\\beta)$ 이다. $2^\\beta-t+1=1-2^\\alpha$ 이고 $\\beta^2=\\alpha^2$ 이므로 두 제곱이 같다. 길이는 양수이므로 ㄴ 은 옳다.","확인":null,"스킬":"C3"},{"제목":"사각형 ACBD 와 대각선의 교점 E 찾기","힌트":"$\\overline{\\mathrm{AD}}$ 와 $\\overline{\\mathrm{CB}}$ 의 길이도 같은가? 그러면 사각형 $\\mathrm{ACBD}$ 는 어떤 사각형이고, 두 대각선 $\\mathrm{AB}$, $\\mathrm{CD}$ 의 교점 $\\mathrm{E}$ 는 $\\overline{\\mathrm{CD}}$ 의 어디인가?","식":["$\\overline{\\mathrm{AD}}=\\overline{\\mathrm{CB}},\\ \\overline{\\mathrm{AC}}=\\overline{\\mathrm{DB}}$ 이므로 사각형 $\\mathrm{ACBD}$ 는 평행사변형","$\\mathrm{E}$ 는 $\\overline{\\mathrm{CD}}$ 의 중점이므로 $\\mathrm{E}\\left(0,\\dfrac{t}{2}\\right)$"],"설명":"$\\overline{\\mathrm{AD}}^{\\,2}=\\alpha^2+\\left(2^\\alpha-t+1\\right)^2=\\beta^2+\\left(1-2^\\beta\\right)^2=\\overline{\\mathrm{CB}}^{\\,2}$ 이다. 두 쌍의 대변이 각각 같으면 평행사변형이고, 평행사변형의 두 대각선은 서로 다른 것을 이등분한다. $\\mathrm{C}$, $\\mathrm{D}$ 의 $y$ 좌표의 평균은 $\\dfrac{1+(t-1)}{2}=\\dfrac{t}{2}$ 이다.","확인":null,"스킬":"S2"},{"제목":"삼각형 ABD, AOB 의 넓이의 비 구하기","고비":true,"힌트":"$\\triangle\\mathrm{ABD}$ 와 $\\triangle\\mathrm{AOB}$ 를 각각 $y$ 축 위의 선분 $\\mathrm{DE}$, $\\mathrm{OE}$ 를 밑변으로 하는 두 삼각형으로 나누면 높이는 무엇인가?","식":["$\\triangle\\mathrm{ABD}=\\dfrac{1}{2}\\cdot\\overline{\\mathrm{DE}}\\cdot(-\\alpha)+\\dfrac{1}{2}\\cdot\\overline{\\mathrm{DE}}\\cdot\\beta=\\dfrac{\\beta(t-2)}{2}$","$\\triangle\\mathrm{AOB}=\\dfrac{1}{2}\\cdot\\overline{\\mathrm{OE}}\\cdot(-\\alpha)+\\dfrac{1}{2}\\cdot\\overline{\\mathrm{OE}}\\cdot\\beta=\\dfrac{\\beta t}{2}$","$\\dfrac{\\triangle\\mathrm{ABD}}{\\triangle\\mathrm{AOB}}=\\dfrac{t-2}{t}$"],"설명":"$\\mathrm{E}$ 가 직선 $\\mathrm{AB}$ 위에 있으므로 두 삼각형 모두 $y$ 축 위의 선분을 밑변으로 하는 두 삼각형으로 나뉘고, $\\mathrm{A}$, $\\mathrm{B}$ 에서 $y$ 축까지의 거리 $-\\alpha$, $\\beta$ 가 높이이다. $\\overline{\\mathrm{DE}}=(t-1)-\\dfrac{t}{2}=\\dfrac{t-2}{2}$, $\\overline{\\mathrm{OE}}=\\dfrac{t}{2}$, $-\\alpha=\\beta$ 이다. 비가 $\\dfrac{t-2}{t}$ 이므로 ㄷ 도 옳고, ㄱ, ㄴ, ㄷ 모두 옳다.","확인":null,"스킬":"G10"}]},"고2-202009-19":{"길":"두 점의 좌표로 두 사다리꼴의 넓이를 t 로 나타내고 비가 자연수가 되는 t 를 찾아 곱한다","단계":[{"제목":"두 점 A, B 의 좌표 구하기","힌트":"$2^x$ 의 값이 각각 $t$, $2t$ 가 되는 $x$ 는?","식":["$2^x=t\\ \\Rightarrow\\ x=\\log_2 t,\\quad 2^x=2t\\ \\Rightarrow\\ x=\\log_2 2t$","$\\mathrm{A}(\\log_2 t,\\ t),\\ \\mathrm{B}(\\log_2 2t,\\ 2t)$"],"설명":"수선의 발은 $\\mathrm{Q}(\\log_2 t,0)$, $\\mathrm{S}(\\log_2 2t,0)$ 이고 $\\mathrm{P}(0,t)$, $\\mathrm{R}(0,2t)$ 이다.","확인":null,"스킬":"A9"},{"제목":"사각형 ABRP 의 넓이 f(t)","힌트":"$\\overline{\\mathrm{PA}}\\parallel\\overline{\\mathrm{RB}}$ 인 사다리꼴이다. 평행한 두 변의 길이와 높이는?","식":["$\\overline{\\mathrm{PA}}=\\log_2 t,\\ \\overline{\\mathrm{RB}}=\\log_2 2t$, 높이 $2t-t=t$","$f(t)=\\dfrac{1}{2}\\left(\\log_2 t+\\log_2 2t\\right)\\cdot t=\\dfrac{t}{2}\\log_2 2t^2$"],"설명":"$\\log_2 t+\\log_2 2t=\\log_2 2t^2$ 이다. 사다리꼴의 넓이는 (윗변 + 아랫변) × 높이 ÷ 2 이다.","확인":null,"스킬":"G10"},{"제목":"사각형 AQSB 의 넓이 g(t)","힌트":"$\\overline{\\mathrm{AQ}}\\parallel\\overline{\\mathrm{BS}}$ 인 사다리꼴이다. 평행한 두 변의 길이와 높이 $\\overline{\\mathrm{QS}}$ 는?","식":["$\\overline{\\mathrm{AQ}}=t,\\ \\overline{\\mathrm{BS}}=2t$, 높이 $\\log_2 2t-\\log_2 t=1$","$g(t)=\\dfrac{1}{2}(t+2t)\\cdot1=\\dfrac{3t}{2}$"],"설명":"$\\log_2 2t-\\log_2 t=\\log_2 2=1$ 이다.","확인":null,"스킬":"G10"},{"제목":"비가 자연수일 때 t 를 n 으로 나타내기","고비":true,"힌트":"$\\dfrac{f(t)}{g(t)}$ 를 간단히 하고 자연수 $n$ 과 같다고 놓으면 $t$ 는 $n$ 의 식으로 어떻게 쓰이는가?","식":["$\\dfrac{f(t)}{g(t)}=\\dfrac{\\frac{t}{2}\\log_2 2t^2}{\\frac{3t}{2}}=\\dfrac{1}{3}\\log_2 2t^2$","$\\dfrac{1}{3}\\log_2 2t^2=n\\ \\Rightarrow\\ 2t^2=2^{3n}$","$t=2^{\\frac{3n-1}{2}}$"],"설명":"$t>0$ 이므로 $t^2=2^{3n-1}$ 의 양의 제곱근을 취한다.","확인":null,"스킬":"A9"},{"제목":"1<t<100 을 만족하는 자연수 n 찾기","힌트":"$n$ 이 커지면 $t$ 도 커진다. $n=4$, $n=5$ 일 때 $t$ 는 각각 $100$ 과 어떻게 비교되는가?","식":["$n=4$: $t=2^{\\frac{11}{2}}<2^6<100$","$n=5$: $t=2^7=128>100$","$n=1,\\ 2,\\ 3,\\ 4$"],"설명":"$n=1$ 일 때 $t=2>1$ 이므로 $n=1$ 부터 $100$ 을 넘기 직전까지의 자연수가 조건을 만족시킨다. 가장 큰 $n$ 은 $4$ 이다.","확인":"4","스킬":"T3"},{"제목":"모든 t 의 값의 곱 구하기","힌트":"$t$ 의 네 값을 $2$ 의 거듭제곱으로 쓰고 곱하면 지수는 어떻게 되는가?","식":["$t=2,\\ 2^{\\frac{5}{2}},\\ 2^4,\\ 2^{\\frac{11}{2}}$","$2^{1+\\frac{5}{2}+4+\\frac{11}{2}}=2^{13}$"],"설명":"$n=1,2,3,4$ 를 $t=2^{\\frac{3n-1}{2}}$ 에 대입한 값이다. 밑이 같으므로 곱은 지수끼리의 합이다.","확인":null,"스킬":"A9"}]},"고2-202009-20":{"길":"귀납 단계의 항들을 하나씩 나열해 비교하여 (가)(나)(다)를 구하고 값을 계산한다","단계":[{"제목":"(가) 구하기","힌트":"$n=1$ 일 때 $S_1=\\displaystyle\\sum_{k=1}^{2}(-1)^{k-1}\\dfrac{1}{k}$ 의 값은?","식":["$S_1=1-\\dfrac{1}{2}=\\dfrac{1}{2}$","$T_1=\\dfrac{1}{1+1}=\\dfrac{1}{2}$"],"설명":"합의 항은 $k=1$, $k=2$ 두 개이다. $T_1$ 과 같으므로 (가)에 알맞은 수는 $a=\\dfrac{1}{2}$ 이다.","확인":"1/2","스킬":"P6"},{"제목":"(나) 구하기","힌트":"$S_{m+1}$ 은 $S_m$ 에 $k=2m+1$, $k=2m+2$ 인 두 항을 더한 것이다. 두 번째 항의 부호는?","식":["$S_{m+1}=S_m+\\dfrac{(-1)^{2m}}{2m+1}+\\dfrac{(-1)^{2m+1}}{2m+2}$","$f(m)=-\\dfrac{1}{2m+2}$"],"설명":"$(-1)^{2m}=1$, $(-1)^{2m+1}=-1$ 이다.","확인":null,"스킬":"P6"},{"제목":"(다) 구하기","고비":true,"힌트":"$T_{m+1}=\\displaystyle\\sum_{k=1}^{m+1}\\dfrac{1}{m+1+k}$ 을 나열하면 $T_m$ 과 어느 항이 겹치고 어느 항이 빠지는가?","식":["$T_m=\\dfrac{1}{m+1}+\\dfrac{1}{m+2}+\\cdots+\\dfrac{1}{2m}$","$T_{m+1}=\\dfrac{1}{m+2}+\\cdots+\\dfrac{1}{2m}+\\dfrac{1}{2m+1}+\\dfrac{1}{2m+2}$","$g(m)=-\\dfrac{1}{m+1}$"],"설명":"$T_{m+1}$ 에는 $\\dfrac{1}{m+1}$ 이 없고 $\\dfrac{1}{2m+1}$, $\\dfrac{1}{2m+2}$ 가 새로 생긴다. 따라서 $T_m$ 에서 $\\dfrac{1}{m+1}$ 을 빼고 두 항을 더한 꼴이다.","확인":null,"스킬":"P6"},{"제목":"g(5)와 f(14)의 비 구하기","힌트":"$g(5)$ 와 $f(14)$ 를 각각 구해 나누면?","식":["$g(5)=-\\dfrac{1}{6},\\quad f(14)=-\\dfrac{1}{2\\times14+2}=-\\dfrac{1}{30}$","$\\dfrac{g(5)}{f(14)}=\\dfrac{-\\frac{1}{6}}{-\\frac{1}{30}}=5$"],"설명":"두 값이 모두 음수이므로 비는 양수이다.","확인":"5","스킬":"P6"},{"제목":"a + g(5)/f(14) 구하기","힌트":"$a=\\dfrac{1}{2}$ 에 앞에서 구한 비를 더하면?","식":["$a+\\dfrac{g(5)}{f(14)}=\\dfrac{1}{2}+5=\\dfrac{11}{2}$"],"설명":"$\\dfrac{1}{2}$ 과 $5$ 를 통분해 더한다.","확인":"11/2","스킬":"P6"}]},"고2-202009-21":{"길":"f 의 주기와 대칭으로 한 주기당 교점 수를 구하고 n 마다 곡선이 지나는 구간 길이에 곱한다","단계":[{"제목":"f 의 그래프 성질 정리","힌트":"$f(-x)=f(x)$ 와 $f(x+4)=f(x)$ 로 $0\\le x\\le4$ 에서의 그래프를 완성하면 $f$ 의 최댓값과 최솟값은?","식":["$f(0)=2,\\ f(1)=3,\\ f(2)=1,\\ f(3)=f(1)=3,\\ f(4)=2$","$1\\le f(x)\\le3$, 주기 $4$"],"설명":"$[0,2]$ 에서 그래프는 $(0,2)\\to(1,3)\\to(2,1)$ 이다. $y$ 축 대칭과 주기 $4$ 에 의해 $[2,4]$ 에서는 $(2,1)\\to(3,3)\\to(4,2)$ 이고 이것이 $4$ 마다 반복된다.","확인":null,"스킬":"T2"},{"제목":"로그함수가 높이 1, 2, 3 을 지나는 점","힌트":"$\\log_{2^n}(x+2n)=1,\\ 2,\\ 3$ 이 되는 $x$ 를 각각 구하면? $1\\le f(x)\\le3$ 이므로 곡선의 어느 부분만 $f$ 와 만나는가?","식":["$y=1$: $x=2^n-2n$","$y=2$: $x=2^{2n}-2n$","$y=3$: $x=2^{3n}-2n$"],"설명":"$x+2n=\\left(2^n\\right)^y$ 에서 $x=2^{ny}-2n$ 이다. 곡선은 증가하므로 높이 $1$ 에서 $3$ 사이의 부분만 $f$ 와 만날 수 있다. 곡선의 높이가 $1$ 이상 $2$ 미만인 구간에서는 한 주기에 $2$ 번, $2$ 이상 $3$ 이하인 구간에서는 한 주기에 $4$ 번 만난다.","확인":null,"스킬":"A9"},{"제목":"n=1 일 때 교점의 개수 a₁","힌트":"$y=\\log_2(x+2)$ 는 $(0,1),\\ (2,2),\\ (6,3)$ 을 지난다. $0\\le x\\le6$ 에서 $f$ 의 그래프와 겹쳐 그리면 교점은 몇 개인가?","식":["$y=\\log_2(x+2)$ 는 $(0,1),\\ (2,2),\\ (6,3)$ 을 지난다","$a_1=5$"],"설명":"$x<0$ 에서는 곡선이 $1$ 보다 작아 $f(x)\\ge1$ 인 그래프와 만나지 않는다. $0\\le x\\le2$ 에서 $1$ 개, $2\\le x\\le6$ 에서 $4$ 개이다.","확인":"5","스킬":"G1"},{"제목":"n=2 일 때 교점의 개수 a₂","고비":true,"힌트":"$y=\\log_4(x+4)$ 는 $(0,1),\\ (12,2),\\ (60,3)$ 을 지난다. $0\\le x<12$ 에서는 한 주기에 몇 번, $12\\le x\\le60$ 에서는 한 주기에 몇 번 만나는가? 각 구간에 주기가 몇 번 들어가는가?","식":["$y=\\log_4(x+4)$ 는 $(0,1),\\ (12,2),\\ (60,3)$ 을 지난다","$0\\le x<12$ 에서 $2\\times\\dfrac{12}{4}=6,\\quad 12\\le x\\le60$ 에서 $4\\times\\dfrac{60-12}{4}=48$","$a_2=6+48=54$"],"설명":"곡선의 높이가 $1$ 이상 $2$ 미만인 구간은 한 주기에 $2$ 번, $2$ 이상 $3$ 이하인 구간은 한 주기에 $4$ 번 만난다. $x=12$ 의 교점은 뒤의 구간에서 센다.","확인":"54","스킬":"T2"},{"제목":"n=3 일 때 교점의 개수 a₃","힌트":"$y=\\log_8(x+6)$ 은 $(2,1),\\ (58,2),\\ (506,3)$ 을 지난다. 시작점의 $x$ 좌표 $2$ 부터 주기를 세면?","식":["$y=\\log_8(x+6)$ 은 $(2,1),\\ (58,2),\\ (506,3)$ 을 지난다","$2\\le x<58$ 에서 $2\\times\\dfrac{58-2}{4}=28,\\quad 58\\le x\\le506$ 에서 $4\\times\\dfrac{506-58}{4}=448$","$a_3=28+448=476$"],"설명":"$f(2)=1$ 이므로 곡선의 시작점 $(2,1)$ 도 교점이고, 이것은 첫 구간에서 센다.","확인":"476","스킬":"T2"},{"제목":"a₁ + a₂ + a₃ 구하기","힌트":"세 값을 더하면?","식":["$a_1+a_2+a_3=5+54+476=535$"],"설명":"구한 세 값을 그대로 더한다.","확인":"535","스킬":"G1"}]},"고2-202009-22":{"길":"음의 지수를 역수로 바꿔 두 값을 곱한다","단계":[{"제목":"각 거듭제곱의 값 구하기","고비":true,"힌트":"$3^4$ 의 값은? $9^{-1}$ 은 $9$ 의 역수이다. 얼마인가?","식":["$3^4=81$","$9^{-1}=\\dfrac{1}{9}$"],"설명":"$a^{-n}=\\dfrac{1}{a^n}$ 이다.","확인":"81","스킬":"A9"},{"제목":"두 값의 곱 구하기","힌트":"$81\\times\\dfrac{1}{9}$ 은?","식":["$81\\times\\dfrac{1}{9}=9$"],"설명":"$81$ 을 $9$ 로 나눈 값이다.","확인":"9","스킬":"A9"}]},"고2-202009-23":{"길":"등차중항으로 y 를 구하고 공차로 x 를 구한다","단계":[{"제목":"y 구하기","고비":true,"힌트":"세 수 $7$, $y$, $13$ 이 이 순서대로 등차수열이면 $y$ 는 $7$ 과 $13$ 의 어떤 값인가?","식":["$2y=7+13$","$y=10$"],"설명":"$y$ 는 $7$ 과 $13$ 의 등차중항이다.","확인":"10","스킬":"P1"},{"제목":"공차와 x 구하기","힌트":"$7$ 과 $y$ 의 차가 공차이다. 공차를 알면 $x$ 는?","식":["공차 $d=10-7=3$","$x=7-3=4$"],"설명":"$x$ 는 $7$ 의 바로 앞 항이므로 $7$ 에서 공차를 뺀다.","확인":"4","스킬":"P1"},{"제목":"x + 2y 구하기","힌트":"구한 $x$, $y$ 를 대입하면?","식":["$x+2y=4+2\\times10=24$"],"설명":"$x=4$, $y=10$ 을 대입한다.","확인":"24","스킬":"P1"}]},"고2-202009-24":{"길":"시그마의 상수배 성질로 6항까지의 합을 구하고 5항까지의 합을 빼서 여섯째 항의 차를 구한다","단계":[{"제목":"6항까지의 합 구하기","힌트":"$\\displaystyle\\sum_{n=1}^{6}\\left(2a_n-2b_n\\right)$ 에서 $2$ 를 시그마 밖으로 빼내면 $\\displaystyle\\sum_{n=1}^{6}\\left(a_n-b_n\\right)$ 은?","식":["$2\\displaystyle\\sum_{n=1}^{6}\\left(a_n-b_n\\right)=56$","$\\displaystyle\\sum_{n=1}^{6}\\left(a_n-b_n\\right)=28$"],"설명":"상수는 시그마 밖으로 뺄 수 있으므로 $56$ 을 $2$ 로 나눈다.","확인":"28","스킬":"P6"},{"제목":"여섯째 항의 차 구하기","고비":true,"힌트":"$6$ 항까지의 합에서 $5$ 항까지의 합을 빼면 어떤 항만 남는가?","식":["$a_6-b_6=\\displaystyle\\sum_{n=1}^{6}\\left(a_n-b_n\\right)-\\sum_{n=1}^{5}\\left(a_n-b_n\\right)$","$=28-10=18$"],"설명":"$n=1$ 부터 $5$ 까지의 항은 서로 없어지고 $n=6$ 인 항 $a_6-b_6$ 만 남는다.","확인":"18","스킬":"P6"}]},"고2-202009-25":{"길":"탄젠트 값과 각의 범위로 사인 값을 구하고 각의 변환 공식으로 식을 사인 하나로 줄인다","단계":[{"제목":"sin θ 의 값 구하기","힌트":"$\\dfrac{\\pi}{2}<\\theta<\\pi$ 에서 $\\sin\\theta$, $\\cos\\theta$ 의 부호는? $1+\\tan^2\\theta=\\dfrac{1}{\\cos^2\\theta}$ 로 $\\cos\\theta$ 를 먼저 구하면?","식":["$\\cos^2\\theta=\\dfrac{1}{1+\\tan^2\\theta}=\\dfrac{9}{25},\\quad \\cos\\theta=-\\dfrac{3}{5}$","$\\sin\\theta=\\tan\\theta\\cos\\theta=\\left(-\\dfrac{4}{3}\\right)\\left(-\\dfrac{3}{5}\\right)=\\dfrac{4}{5}$"],"설명":"제$2$사분면에서는 $\\sin\\theta>0$, $\\cos\\theta<0$ 이므로 $\\cos\\theta$ 는 음수를 택한다.","확인":"4/5","스킬":"T5"},{"제목":"주어진 식을 sin θ 로 나타내기","고비":true,"힌트":"$\\sin(\\pi+\\theta)$ 와 $\\cos\\left(\\dfrac{\\pi}{2}-\\theta\\right)$ 는 각각 $\\sin\\theta$ 의 몇 배인가?","식":["$\\sin(\\pi+\\theta)=-\\sin\\theta,\\quad \\cos\\left(\\dfrac{\\pi}{2}-\\theta\\right)=\\sin\\theta$","$5\\sin(\\pi+\\theta)+10\\cos\\left(\\dfrac{\\pi}{2}-\\theta\\right)=-5\\sin\\theta+10\\sin\\theta=5\\sin\\theta$"],"설명":"$\\pi+\\theta$ 는 $\\theta$ 에서 반 바퀴 돌린 각이므로 부호가 바뀐다. $\\dfrac{\\pi}{2}-\\theta$ 는 사인과 코사인이 서로 바뀐다.","확인":null,"스킬":"T5"},{"제목":"식의 값 구하기","힌트":"$5\\sin\\theta$ 에 $\\sin\\theta=\\dfrac{4}{5}$ 를 넣으면?","식":["$5\\sin\\theta=5\\times\\dfrac{4}{5}=4$"],"설명":"첫 단계에서 구한 $\\sin\\theta$ 의 값을 대입한다.","확인":"4","스킬":"T5"}]},"고2-202009-26":{"길":"평행이동한 식을 5^x 의 상수배 꼴로 바꿔 주어진 식과 비교한다","단계":[{"제목":"평행이동한 함수식 쓰기","힌트":"$y=5^x$ 를 $x$ 축으로 $a$, $y$ 축으로 $b$ 만큼 옮긴 식은? $5^{x-a}$ 를 $5^x$ 의 상수배로 고치면?","식":["$y=5^{x-a}+b$","$y=5^{-a}\\times5^x+b$"],"설명":"$x$ 대신 $x-a$, $y$ 대신 $y-b$ 를 넣는다. 지수법칙으로 $5^{x-a}=5^{-a}\\times5^x$ 이다.","확인":null,"스킬":"G4"},{"제목":"상수배와 평행이동 b 비교하기","고비":true,"힌트":"$\\dfrac{1}{9}\\times5^{x-1}+2$ 도 $5^x$ 의 상수배 꼴로 고치면 $5^x$ 의 계수와 상수항은?","식":["$\\dfrac{1}{9}\\times5^{x-1}+2=\\dfrac{1}{9}\\times\\dfrac{1}{5}\\times5^x+2=\\dfrac{1}{45}\\times5^x+2$","$5^{-a}=\\dfrac{1}{45},\\quad b=2$"],"설명":"두 함수의 그래프가 일치하면 $5^x$ 의 계수와 상수항이 각각 같다.","확인":"1/45","스킬":"A9"},{"제목":"5^a 의 값 구하기","힌트":"$5^{-a}=\\dfrac{1}{45}$ 의 역수를 취하면?","식":["$5^a=\\dfrac{1}{5^{-a}}=45$"],"설명":"$5^{-a}=\\dfrac{1}{5^a}$ 이므로 양변의 역수를 취한다.","확인":"45","스킬":"A9"},{"제목":"5^a + b 의 값 구하기","힌트":"$5^a=45$, $b=2$ 를 더하면?","식":["$5^a+b=45+2=47$"],"설명":"앞에서 구한 두 값을 더한다.","확인":"47","스킬":"G4"}]},"고2-202009-27":{"길":"중심각에서 삼각형 OAB 를 직각이등변으로 보고 각을 따라가 삼각형 OMH 에 코사인법칙을 쓴다","단계":[{"제목":"삼각형 OAB 의 모양 찾기","힌트":"부채꼴의 중심각이 $\\dfrac{3}{2}\\pi$ 이면 선분 $\\mathrm{OA}$, $\\mathrm{OB}$ 가 이루는 $\\angle\\mathrm{AOB}$ 는? 삼각형 $\\mathrm{OAB}$ 는 어떤 삼각형인가?","식":["$\\angle\\mathrm{AOB}=2\\pi-\\dfrac{3}{2}\\pi=\\dfrac{\\pi}{2}$","$\\overline{\\mathrm{OA}}=\\overline{\\mathrm{OB}}=2$ 인 직각이등변삼각형, $\\overline{\\mathrm{AB}}=2\\sqrt{2}$"],"설명":"부채꼴의 호가 큰 쪽이므로 중심각이 $\\dfrac{3}{2}\\pi$ 이고, 나머지 부분의 각이 $\\angle\\mathrm{AOB}$ 이다. 반지름이 모두 $2$ 이다.","확인":null,"스킬":"S3"},{"제목":"O 에서 AB 에 내린 수선의 발 M","힌트":"$\\mathrm{O}$ 에서 $\\overline{\\mathrm{AB}}$ 에 수선을 내린 발을 $\\mathrm{M}$ 이라 하면 $\\overline{\\mathrm{AM}}$, $\\overline{\\mathrm{BM}}$, $\\overline{\\mathrm{OM}}$ 의 길이는?","식":["$\\overline{\\mathrm{AM}}=\\overline{\\mathrm{BM}}=\\sqrt{2}$","$\\overline{\\mathrm{OM}}=\\sqrt{2}\\quad(\\angle\\mathrm{OAM}=\\dfrac{\\pi}{4})$"],"설명":"이등변삼각형에서 꼭짓점에서 밑변에 내린 수선은 밑변을 이등분한다. 삼각형 $\\mathrm{OAM}$ 은 직각이등변삼각형이므로 $\\overline{\\mathrm{OM}}=\\overline{\\mathrm{AM}}$ 이다.","확인":null,"스킬":"S2"},{"제목":"BH 의 길이 구하기","힌트":"삼각형 $\\mathrm{ABH}$ 는 $\\angle\\mathrm{AHB}=\\dfrac{\\pi}{2}$, $\\angle\\mathrm{BAH}=\\dfrac{\\pi}{6}$ 인 직각삼각형이다. $\\overline{\\mathrm{BH}}$ 는?","식":["$\\overline{\\mathrm{BH}}=\\overline{\\mathrm{AB}}\\sin\\dfrac{\\pi}{6}=2\\sqrt{2}\\times\\dfrac{1}{2}=\\sqrt{2}$"],"설명":"$\\overline{\\mathrm{AB}}$ 가 빗변이므로 빗변에 $\\sin\\dfrac{\\pi}{6}$ 을 곱한다.","확인":null,"스킬":"S6"},{"제목":"삼각형 BHM 의 모양과 HM","고비":true,"힌트":"$\\overline{\\mathrm{BM}}$ 과 $\\overline{\\mathrm{BH}}$ 를 비교하고 $\\angle\\mathrm{ABH}$ 를 구하면 삼각형 $\\mathrm{BHM}$ 은 어떤 삼각형인가?","식":["$\\angle\\mathrm{ABH}=\\dfrac{\\pi}{2}-\\dfrac{\\pi}{6}=\\dfrac{\\pi}{3},\\quad \\overline{\\mathrm{BM}}=\\overline{\\mathrm{BH}}=\\sqrt{2}$","삼각형 $\\mathrm{BHM}$ 은 정삼각형, $\\overline{\\mathrm{HM}}=\\sqrt{2},\\ \\angle\\mathrm{BMH}=\\dfrac{\\pi}{3}$"],"설명":"두 변의 길이가 같고 그 끼인각이 $\\dfrac{\\pi}{3}$ 인 삼각형은 정삼각형이다.","확인":null,"스킬":"S10"},{"제목":"코사인법칙으로 OH² 구하기","힌트":"$\\angle\\mathrm{OMB}=\\dfrac{\\pi}{2}$ 안에 $\\angle\\mathrm{BMH}=\\dfrac{\\pi}{3}$ 가 들어 있으면 $\\angle\\mathrm{OMH}$ 는? 삼각형 $\\mathrm{OMH}$ 에서 $\\overline{\\mathrm{OH}}^{\\,2}$ 는?","식":["$\\angle\\mathrm{OMH}=\\dfrac{\\pi}{2}-\\dfrac{\\pi}{3}=\\dfrac{\\pi}{6},\\quad \\overline{\\mathrm{OM}}=\\overline{\\mathrm{HM}}=\\sqrt{2}$","$\\overline{\\mathrm{OH}}^{\\,2}=2+2-2\\times\\sqrt{2}\\times\\sqrt{2}\\times\\cos\\dfrac{\\pi}{6}=4-2\\sqrt{3}$"],"설명":"$\\mathrm{H}$ 는 $\\mathrm{O}$ 와 직선 $\\mathrm{AB}$ 의 같은 쪽에 있으므로 $\\angle\\mathrm{OMH}=\\angle\\mathrm{OMB}-\\angle\\mathrm{BMH}$ 이다. $\\cos\\dfrac{\\pi}{6}=\\dfrac{\\sqrt{3}}{2}$ 이다.","확인":null,"스킬":"S6"},{"제목":"m, n 을 읽어 m²+n² 구하기","힌트":"$4-2\\sqrt{3}=m+n\\sqrt{3}$ 에서 $m$, $n$ 은? $m^2+n^2$ 은?","식":["$m=4,\\quad n=-2$","$m^2+n^2=16+4=20$"],"설명":"$m$, $n$ 이 유리수이므로 유리수 부분과 $\\sqrt{3}$ 의 계수를 각각 비교한다.","확인":"20","스킬":"S6"}]},"고2-202009-28":{"길":"(1/2)^x 를 치환해 인수분해하고 3n 과 16 의 대소로 나누어 정수 x 가 2 개인 n 을 센다","단계":[{"제목":"치환해 인수분해하기","힌트":"$\\left(\\dfrac{1}{2}\\right)^x=X$ 로 놓으면 $\\left(\\dfrac{1}{4}\\right)^x$ 은? 부등식을 $X$ 에 대한 이차식으로 쓰고 인수분해하면?","식":["$X^2-(3n+16)X+48n\\le0$","$(X-3n)(X-16)\\le0$"],"설명":"$\\left(\\dfrac{1}{4}\\right)^x=\\left\\{\\left(\\dfrac{1}{2}\\right)^x\\right\\}^2=X^2$ 이고, $48n=3n\\times16$, $3n+16$ 이므로 합과 곱이 맞는다.","확인":null,"스킬":"A1"},{"제목":"정수 x 를 2 의 거듭제곱으로 바꿔 경우 나누기","힌트":"$x=-k$ 로 놓으면 $X=2^k$ 이다. $(X-3n)(X-16)\\le0$ 의 해는 $3n$ 과 $16$ 중 어느 쪽이 작은가에 따라 어떻게 달라지는가?","식":["$3n\\le16$ 이면 $3n\\le2^k\\le16$","$3n>16$ 이면 $16\\le2^k\\le3n$"],"설명":"두 근 사이에서 이차식이 $0$ 이하이다. 정수 $x$ 의 개수는 정수 $k$ 의 개수와 같다. $16=2^4$ 은 어느 경우에도 범위의 끝에 들어 있다.","확인":null,"스킬":"C2"},{"제목":"3n≤16 일 때 가능한 n 의 개수","힌트":"$16=2^4$ 이 범위에 들어 있다. 정수 $k$ 가 $2$ 개이려면 $k$ 는 어떤 두 값이고, 그때 $3n$ 은 $2$ 의 어떤 거듭제곱 사이에 있는가?","식":["$k=3,\\ 4$ 이려면 $2^2<3n\\le2^3$","$4<3n\\le8$ 에서 자연수 $n$ 은 $1$ 개"],"설명":"$3n\\le16$ 이므로 $n\\le5$ 이다. $4<3n\\le8$ 을 만족시키는 자연수는 $n=2$ 하나뿐이다.","확인":"1","스킬":"C2"},{"제목":"3n>16 일 때 가능한 n 의 개수","고비":true,"힌트":"$16=2^4$ 이 범위의 왼쪽 끝이다. 정수 $k$ 가 $2$ 개이려면 $k$ 는 어떤 두 값이고, 그때 $3n$ 의 범위는? 그 범위의 자연수 $n$ 은 몇 개인가?","식":["$k=4,\\ 5$ 이려면 $2^5\\le3n<2^6$","$32\\le3n<64$ 에서 $n=11,\\ 12,\\ \\cdots,\\ 21$","$21-11+1=11$ 개"],"설명":"$k=6$ 이 포함되지 않도록 $3n<64$ 이고, $k=5$ 가 포함되도록 $3n\\ge32$ 이다. $3n>16$ 은 이 범위에서 항상 성립한다.","확인":"11","스킬":"C2"},{"제목":"경우의 개수 합하기","힌트":"두 경우는 서로 겹치지 않는다. 합은?","식":["$1+11=12$"],"설명":"$3n\\le16$ 인 경우와 $3n>16$ 인 경우는 겹치지 않으므로 개수를 더한다.","확인":"12","스킬":"C2"}]},"고2-202009-29":{"길":"A, B 가 y=x 에 대칭임을 쓰고 합동인 직각삼각형으로 각을 구한 뒤 사인법칙으로 p 를 정한다","단계":[{"제목":"A, B 의 좌표 사이의 관계 찾기","힌트":"$\\mathrm{A}(p,q)$ 라 하면 $q$ 와 $p+q$ 는 각각 무엇과 같은가? $y=\\log_ax$ 는 $y=a^x$ 의 무엇이므로 $\\mathrm{B}$ 의 좌표는?","식":["$q=a^p,\\quad p+q=t$","$\\mathrm{B}(q,p),\\quad \\overline{\\mathrm{AB}}=\\sqrt{2(q-p)^2}=\\sqrt{2}(q-p)$"],"설명":"$\\mathrm{A}$ 는 직선 $y=-x+t$ 위의 점이므로 $p+q=t$ 이다. $y=\\log_ax$ 는 $y=a^x$ 의 역함수이므로 두 그래프는 직선 $y=x$ 에 대칭이고, $\\mathrm{A}(p,q)$ 에 대응하는 점이 $\\mathrm{B}(q,p)$ 이다. $q>p$ 이다.","확인":null,"스킬":"T1"},{"제목":"(가)로 p, q 의 관계식 세우기","힌트":"$\\overline{\\mathrm{OH}}=p$ 이다. $\\overline{\\mathrm{OH}}:\\overline{\\mathrm{AB}}=1:2$ 를 식으로 쓰면 $q$ 는 $p$ 의 몇 배인가?","식":["$2\\overline{\\mathrm{OH}}=\\overline{\\mathrm{AB}},\\quad 2p=\\sqrt{2}(q-p)$","$q=\\left(1+\\sqrt{2}\\right)p$"],"설명":"$\\mathrm{H}(p,0)$ 이므로 $\\overline{\\mathrm{OH}}=p$ 이다. $\\sqrt{2}\\,q=(2+\\sqrt{2})p$ 에서 $q=\\dfrac{2+\\sqrt{2}}{\\sqrt{2}}p=\\left(\\sqrt{2}+1\\right)p$ 이다.","확인":null,"스킬":"C7"},{"제목":"합동인 두 직각삼각형 찾기","힌트":"$\\mathrm{O}$ 에서 직선 $\\mathrm{AB}$ 에 내린 수선의 발을 $\\mathrm{O}'$ 이라 하자. $\\overline{\\mathrm{OA}}$ 와 $\\overline{\\mathrm{OB}}$ 의 길이를 비교하면 $\\mathrm{O}'$ 은 $\\overline{\\mathrm{AB}}$ 의 어디이고 $\\overline{\\mathrm{BO}'}$ 은 어느 선분과 같은가?","식":["$\\overline{\\mathrm{OA}}=\\overline{\\mathrm{OB}},\\quad \\overline{\\mathrm{BO}'}=\\dfrac{1}{2}\\overline{\\mathrm{AB}}=\\overline{\\mathrm{OH}}$","$\\triangle\\mathrm{AOH}\\equiv\\triangle\\mathrm{OBO}'\\ \\Rightarrow\\ \\angle\\mathrm{AOH}=\\angle\\mathrm{OBO}'$"],"설명":"$\\mathrm{A}(p,q)$ 와 $\\mathrm{B}(q,p)$ 는 원점에서 거리가 같으므로 삼각형 $\\mathrm{OAB}$ 는 이등변삼각형이고 $\\mathrm{O}'$ 은 $\\overline{\\mathrm{AB}}$ 의 중점이다. 두 직각삼각형은 빗변과 다른 한 변의 길이가 각각 같으므로 합동이다.","확인":null,"스킬":"S2"},{"제목":"각 AOB 의 크기 구하기","고비":true,"힌트":"$\\angle\\mathrm{AOB}=\\theta$ 라 하자. 직선 $\\mathrm{OO}'$ 은 직선 $y=x$ 위에 있다. $\\angle\\mathrm{AOH}$ 와 $\\angle\\mathrm{OBO}'$ 을 $\\theta$ 로 나타내어 같다고 놓으면?","식":["$\\angle\\mathrm{AOH}=\\angle\\mathrm{O}'\\mathrm{OH}+\\angle\\mathrm{AOO}'=\\dfrac{\\pi}{4}+\\dfrac{\\theta}{2}$","$\\angle\\mathrm{OBO}'=\\dfrac{\\pi}{2}-\\angle\\mathrm{BOO}'=\\dfrac{\\pi}{2}-\\dfrac{\\theta}{2}$","$\\dfrac{\\pi}{4}+\\dfrac{\\theta}{2}=\\dfrac{\\pi}{2}-\\dfrac{\\theta}{2}\\ \\Rightarrow\\ \\theta=\\dfrac{\\pi}{4}$"],"설명":"$\\mathrm{OO}'$ 은 이등변삼각형의 꼭지각을 이등분하므로 $\\angle\\mathrm{AOO}'=\\angle\\mathrm{BOO}'=\\dfrac{\\theta}{2}$ 이다. 직선 $y=x$ 가 $x$ 축과 이루는 각이 $\\dfrac{\\pi}{4}$ 이므로 $\\angle\\mathrm{O}'\\mathrm{OH}=\\dfrac{\\pi}{4}$ 이다.","확인":null,"스킬":"S10"},{"제목":"사인법칙으로 p 구하기","힌트":"삼각형 $\\mathrm{AOB}$ 의 외접원의 반지름이 $\\dfrac{\\sqrt{2}}{2}$ 이면 $\\overline{\\mathrm{AB}}$ 는? $\\overline{\\mathrm{AB}}=2p$ 이므로 $p$ 는?","식":["$\\overline{\\mathrm{AB}}=2\\times\\dfrac{\\sqrt{2}}{2}\\times\\sin\\dfrac{\\pi}{4}=1$","$2p=1,\\quad p=\\dfrac{1}{2}$"],"설명":"사인법칙 $\\dfrac{\\overline{\\mathrm{AB}}}{\\sin\\theta}=2R$ 에서 $\\overline{\\mathrm{AB}}=2R\\sin\\theta$ 이다. (가)에서 $\\overline{\\mathrm{AB}}=2\\overline{\\mathrm{OH}}=2p$ 이다.","확인":"1/2","스킬":"S6"},{"제목":"q, t, a 구하기","힌트":"$q=\\left(1+\\sqrt{2}\\right)p$ 에 $p$ 를 넣으면? $t=p+q$ 이고 $q=a^p$ 에서 $a$ 는 $q$ 로 어떻게 나타나는가?","식":["$q=\\dfrac{1}{2}+\\dfrac{\\sqrt{2}}{2},\\quad t=p+q=1+\\dfrac{\\sqrt{2}}{2}$","$a^{\\frac{1}{2}}=q\\ \\Rightarrow\\ a=q^2=\\dfrac{3}{4}+\\dfrac{\\sqrt{2}}{2}$"],"설명":"$q=a^p$ 에 $p=\\dfrac{1}{2}$ 을 넣으면 $q=\\sqrt{a}$ 이므로 양변을 제곱한다. $q^2=\\dfrac{1}{4}+\\dfrac{\\sqrt{2}}{2}+\\dfrac{1}{2}$ 이다.","확인":null,"스킬":"A9"},{"제목":"200(t−a) 구하기","힌트":"$t-a$ 를 먼저 구하면 $\\sqrt{2}$ 가 들어 있는 항은 어떻게 되는가?","식":["$t-a=\\left(1+\\dfrac{\\sqrt{2}}{2}\\right)-\\left(\\dfrac{3}{4}+\\dfrac{\\sqrt{2}}{2}\\right)=\\dfrac{1}{4}$","$200(t-a)=50$"],"설명":"$\\dfrac{\\sqrt{2}}{2}$ 가 서로 없어지고 $1-\\dfrac{3}{4}=\\dfrac{1}{4}$ 이 남는다.","확인":"50","스킬":"A9"}]},"고2-202011-05":{"길":"제4항을 S_4 와 S_3 의 차로 나타내 값을 대입한다","단계":[{"제목":"a₄ 를 S 로 나타내기","힌트":"제$4$항까지의 합에서 제$3$항까지의 합을 빼면 어느 항만 남는가?","식":["$a_4=S_4-S_3$"],"설명":"$S_4=a_1+a_2+a_3+a_4$, $S_3=a_1+a_2+a_3$ 이므로 차는 $a_4$ 이다.","확인":null,"스킬":"P6"},{"제목":"S₄, S₃ 를 대입해 a₄ 구하기","고비":true,"힌트":"$S_n=n^3+n$ 에 $n=4$, $n=3$ 을 넣고 빼면?","식":["$S_4=4^3+4=68,\\quad S_3=3^3+3=30$","$a_4=68-30=38$"],"설명":"$S_n$ 의 식에 각각 대입한 뒤 뺀다.","확인":"38","스킬":"P6"}]},"고2-202011-06":{"길":"2 를 상용로그로 바꿔 진수의 범위를 구하고 정수의 최댓값을 찾는다","단계":[{"제목":"진수의 범위 구하기","고비":true,"힌트":"$2$ 를 $\\log100$ 으로 바꾸고 밑이 $1$ 보다 크다는 것을 쓰면 $x$ 의 범위는?","식":["$\\log3x<2=\\log100$","$0<3x<100,\\quad 0<x<\\dfrac{100}{3}$"],"설명":"밑이 $10$ 으로 $1$ 보다 크므로 부등호의 방향이 그대로이다. 진수는 양수이어야 한다.","확인":"100/3","스킬":"T3"},{"제목":"정수 x 의 최댓값 구하기","힌트":"$\\dfrac{100}{3}=33.\\cdots$ 보다 작은 정수 중 가장 큰 수는?","식":["$x=33$"],"설명":"$\\dfrac{100}{3}$ 은 정수가 아니므로 그 바로 아래 정수가 최댓값이다.","확인":"33","스킬":"T3"}]},"고2-202011-08":{"길":"우변을 log_2 a 로 바꿔 log_2 a 에 대한 방정식을 풀고 a 를 구한다","단계":[{"제목":"우변을 log₂ a 로 나타내기","고비":true,"힌트":"$\\dfrac{1}{\\log_a2}$ 은 밑을 바꾸면 어떤 로그인가?","식":["$\\dfrac{1}{\\log_a2}=\\log_2a$","$\\dfrac{2}{\\log_a2}=2\\log_2a$"],"설명":"$\\log_ab=\\dfrac{1}{\\log_ba}$ 이다.","확인":null,"스킬":"A9"},{"제목":"log₂ a 의 값 구하기","힌트":"$\\log_28a$ 를 $\\log_28+\\log_2a$ 로 쪼개고 $\\log_2a=L$ 로 놓아 방정식을 풀면?","식":["$\\log_28+\\log_2a=2\\log_2a$","$3+L=2L,\\quad L=3$"],"설명":"곱의 로그는 로그의 합이고 $\\log_28=3$ 이다.","확인":"3","스킬":"A9"},{"제목":"a 의 값 구하기","힌트":"$\\log_2a=3$ 이면 $a$ 는?","식":["$a=2^3=8$"],"설명":"로그의 정의에 따라 지수로 바꾼다.","확인":"8","스킬":"A9"}]},"고2-202011-10":{"길":"처음 몇 항을 나열해 같은 값이 돌아오는 주기를 찾고 제10항을 구한다","단계":[{"제목":"a₂ 부터 a₄ 까지 구하기","힌트":"$a_1=4$ 는 $6$ 보다 작다. 한 항씩 조건에 맞는 식을 골라 $a_4$ 까지 구하면?","식":["$a_2=(4-1)^2=9$","$a_3=9-3=6$","$a_4=6-3=3$"],"설명":"$a_n<6$ 이면 $(a_n-1)^2$, $a_n\\ge6$ 이면 $a_n-3$ 을 쓴다. $a_2=9$ 와 $a_3=6$ 은 모두 $6$ 이상이다.","확인":"3","스킬":"P7"},{"제목":"반복되는 주기 찾기","고비":true,"힌트":"$a_5$ 와 $a_6$ 을 구하면 앞에서 나온 값이 다시 나오는가?","식":["$a_5=(3-1)^2=4=a_1$","$a_6=(4-1)^2=9=a_2$","$a_{n+4}=a_n$"],"설명":"$a_5$ 가 $a_1$ 과 같으므로 이후는 같은 계산이 되풀이되어 $4$ 항마다 같은 값이 나온다.","확인":null,"스킬":"P7"},{"제목":"a₁₀ 구하기","힌트":"$10$ 을 $4$ 로 나눈 나머지로 $a_{10}$ 이 어느 항과 같은지 찾으면?","식":["$a_{10}=a_6=a_2=9$"],"설명":"$10=4\\times2+2$ 이므로 $a_{10}=a_2$ 이다.","확인":"9","스킬":"P7"}]},"고2-202011-11":{"길":"a 와 k, a 와 ∛4 의 관계를 거듭제곱근으로 쓰고 지수를 이어 k 를 구한다","단계":[{"제목":"a 를 k 의 거듭제곱으로 나타내기","힌트":"$k$ 의 세제곱근 중 실수인 것을 거듭제곱 꼴로 쓰면?","식":["$a=\\sqrt[3]{k}=k^{\\frac{1}{3}}$"],"설명":"양수 $k$ 의 세제곱근 중 실수인 것은 하나뿐이다.","확인":null,"스킬":"A9"},{"제목":"네제곱근 조건 식으로 쓰기","힌트":"$a$ 의 네제곱근 중 양수인 것을 $a$ 의 거듭제곱으로 쓰고 $\\sqrt[3]{4}$ 를 $2$ 의 거듭제곱으로 쓰면?","식":["$\\sqrt[4]{a}=a^{\\frac{1}{4}}$","$\\sqrt[3]{4}=2^{\\frac{2}{3}}=a^{\\frac{1}{4}}$"],"설명":"$\\sqrt[3]{4}=4^{\\frac{1}{3}}=\\left(2^2\\right)^{\\frac{1}{3}}$ 이다.","확인":null,"스킬":"A9"},{"제목":"k 의 값 구하기","고비":true,"힌트":"$a=k^{\\frac{1}{3}}$ 을 넣으면 $a^{\\frac{1}{4}}$ 은 $k$ 의 몇 제곱인가? 양변을 거듭제곱해 $k$ 만 남기면?","식":["$2^{\\frac{2}{3}}=\\left(k^{\\frac{1}{3}}\\right)^{\\frac{1}{4}}=k^{\\frac{1}{12}}$","$k=\\left(2^{\\frac{2}{3}}\\right)^{12}=2^8=256$"],"설명":"지수끼리 곱하면 $\\dfrac{1}{3}\\times\\dfrac{1}{4}=\\dfrac{1}{12}$ 이다. 양변을 $12$ 제곱하면 $k$ 만 남는다.","확인":"256","스킬":"A9"}]},"고2-202011-12":{"길":"각의 변환 공식으로 식을 cos θ 로 줄인 뒤 값을 대입한다","단계":[{"제목":"식을 cos θ 로 나타내기","힌트":"$\\sin\\left(\\dfrac{\\pi}{2}+\\theta\\right)$ 와 $\\cos(\\pi-\\theta)$ 는 각각 $\\cos\\theta$ 의 몇 배인가?","식":["$\\sin\\left(\\dfrac{\\pi}{2}+\\theta\\right)=\\cos\\theta,\\quad \\cos(\\pi-\\theta)=-\\cos\\theta$","$3\\cos\\theta-\\cos\\theta=2\\cos\\theta$"],"설명":"$\\dfrac{\\pi}{2}+\\theta$ 는 사인이 코사인으로 바뀌고 부호는 그대로이다. $\\pi-\\theta$ 는 코사인의 부호가 바뀐다.","확인":null,"스킬":"T5"},{"제목":"식의 값 구하기","고비":true,"힌트":"$2\\cos\\theta$ 에 $\\cos\\theta=\\dfrac{1}{4}$ 을 넣으면?","식":["$2\\cos\\theta=2\\times\\dfrac{1}{4}=\\dfrac{1}{2}$"],"설명":"주어진 값을 대입한다.","확인":"1/2","스킬":"T5"}]},"고2-202011-13":{"길":"역함수 g 의 식을 구해 점근선으로 a, 지나는 점으로 b 를 정한다","단계":[{"제목":"역함수 g(x) 구하기","힌트":"$y=\\log_2(x+a)+b$ 를 $x$ 에 대해 풀면?","식":["$y-b=\\log_2(x+a)\\ \\Rightarrow\\ x+a=2^{y-b}$","$g(x)=2^{x-b}-a$"],"설명":"$x$ 와 $y$ 를 서로 바꾸면 역함수이다.","확인":null,"스킬":"T1"},{"제목":"점근선으로 a 구하기","고비":true,"힌트":"$y=2^{x-b}-a$ 의 점근선은 어떤 직선인가? 그것이 $y=1$ 이면 $a$ 는?","식":["점근선 $y=-a$","$-a=1,\\quad a=-1$"],"설명":"$2^{x-b}$ 은 $x$ 축($y=0$)을 점근선으로 가지므로 $y$ 축 방향으로 $-a$ 만큼 옮긴 점근선은 $y=-a$ 이다.","확인":"-1","스킬":"T4"},{"제목":"점 (3, 2) 로 b 구하기","힌트":"$g(x)=2^{x-b}+1$ 에 $x=3$ 을 넣어 $g(3)=2$ 로 놓으면?","식":["$g(3)=2^{3-b}+1=2$","$2^{3-b}=1,\\quad b=3$"],"설명":"$2^{3-b}=2^0$ 이므로 지수가 $0$ 이다.","확인":"3","스킬":"T1"},{"제목":"a + b 구하기","힌트":"$a=-1$, $b=3$ 을 더하면?","식":["$a+b=-1+3=2$"],"설명":"앞에서 구한 두 값을 더한다.","확인":"2","스킬":"T1"}]},"고2-202011-14":{"길":"호의 길이로 중심각을 구해 부채꼴과 삼각형의 넓이를 OP 의 식으로 쓰고 비로 OP 를 구한다","단계":[{"제목":"중심각과 부채꼴의 넓이 S 구하기","힌트":"호의 길이는 반지름과 중심각의 곱이다. 중심각 $\\theta$ 는? 그때 부채꼴의 넓이는?","식":["$\\pi=4\\theta\\ \\Rightarrow\\ \\theta=\\dfrac{\\pi}{4}$","$S=\\dfrac{1}{2}\\times4\\times\\pi=2\\pi$"],"설명":"부채꼴의 호의 길이는 $r\\theta$, 넓이는 $\\dfrac{1}{2}r\\cdot l$ 이다.","확인":null,"스킬":"C7"},{"제목":"삼각형 OAP 의 넓이 T 를 OP 로 나타내기","고비":true,"힌트":"삼각형 $\\mathrm{OAP}$ 는 두 변 $\\overline{\\mathrm{OA}}=4$, $\\overline{\\mathrm{OP}}$ 와 그 끼인각 $\\theta$ 가 있다. 넓이를 $\\overline{\\mathrm{OP}}$ 로 쓰면?","식":["$T=\\dfrac{1}{2}\\times\\overline{\\mathrm{OP}}\\times4\\times\\sin\\dfrac{\\pi}{4}=\\sqrt{2}\\,\\overline{\\mathrm{OP}}$"],"설명":"두 변과 끼인각을 알 때 넓이는 $\\dfrac{1}{2}bc\\sin A$ 이다. 점 $\\mathrm{P}$ 가 선분 $\\mathrm{OB}$ 위에 있으므로 끼인각은 $\\angle\\mathrm{AOB}=\\dfrac{\\pi}{4}$ 이다.","확인":null,"스킬":"S8"},{"제목":"S/T 조건으로 OP 구하기","힌트":"$\\dfrac{S}{T}=\\pi$ 에 $S$, $T$ 를 넣어 $\\overline{\\mathrm{OP}}$ 에 대해 풀면?","식":["$\\dfrac{2\\pi}{\\sqrt{2}\\,\\overline{\\mathrm{OP}}}=\\pi$","$\\overline{\\mathrm{OP}}=\\dfrac{2}{\\sqrt{2}}=\\sqrt{2}$"],"설명":"양변을 $\\pi$ 로 나누고 정리한다.","확인":null,"스킬":"S8"}]},"고2-202011-15":{"길":"a_n 을 2 의 거듭제곱으로 고쳐 log 를 부분분수로 나누고 합을 앞뒤 소거로 구한다","단계":[{"제목":"a_n 을 2 의 거듭제곱으로 나타내기","힌트":"거듭제곱근을 유리수 지수로 고쳐 $4$ 를 $2^2$ 으로 쓰면 지수는 어떻게 되는가?","식":["$a_n=\\left(4^{\\frac{1}{n+2}}\\right)^{\\frac{1}{n+1}}=\\left(2^{\\frac{2}{n+2}}\\right)^{\\frac{1}{n+1}}$","$a_n=2^{\\frac{2}{(n+1)(n+2)}}$"],"설명":"안쪽 근호를 먼저 지수로 바꾸고, 바깥 근호의 지수를 곱한다.","확인":null,"스킬":"A9"},{"제목":"log₂ a_k 를 부분분수로 나누기","고비":true,"힌트":"$\\log_2a_k$ 는 얼마인가? $\\dfrac{1}{(k+1)(k+2)}$ 을 $\\dfrac{1}{k+1}$ 과 $\\dfrac{1}{k+2}$ 의 차로 쓰면?","식":["$\\log_2a_k=\\dfrac{2}{(k+1)(k+2)}$","$=2\\left(\\dfrac{1}{k+1}-\\dfrac{1}{k+2}\\right)$"],"설명":"$\\log_22^x=x$ 이다. $\\dfrac{1}{k+1}-\\dfrac{1}{k+2}=\\dfrac{1}{(k+1)(k+2)}$ 이다.","확인":null,"스킬":"P6"},{"제목":"k=1 부터 10 까지 합하기","힌트":"합을 나열하면 어느 항이 남는가?","식":["$\\displaystyle\\sum_{k=1}^{10}\\log_2a_k=2\\left\\{\\left(\\dfrac{1}{2}-\\dfrac{1}{3}\\right)+\\left(\\dfrac{1}{3}-\\dfrac{1}{4}\\right)+\\cdots+\\left(\\dfrac{1}{11}-\\dfrac{1}{12}\\right)\\right\\}$","$=2\\left(\\dfrac{1}{2}-\\dfrac{1}{12}\\right)=\\dfrac{5}{6}$"],"설명":"가운데 항은 더해졌다가 빼져 사라지고 첫 항 $\\dfrac{1}{2}$ 과 끝 항 $-\\dfrac{1}{12}$ 만 남는다.","확인":"5/6","스킬":"P6"}]},"고2-202011-16":{"길":"양변에 cos θ 를 곱해 sin θ+cos θ 와 sin θ cos θ 의 관계를 만들고 제곱해서 값을 구한다","단계":[{"제목":"양변에 cos θ 를 곱해 합의 꼴 만들기","힌트":"$\\tan\\theta=\\dfrac{\\sin\\theta}{\\cos\\theta}$ 이므로 양변에 $\\cos\\theta$ 를 곱하면 $\\sin\\theta$, $\\cos\\theta$ 의 곱과 합 사이의 식이 되는가?","식":["$3\\sin\\theta\\cos\\theta-4\\sin\\theta=4\\cos\\theta$","$3\\sin\\theta\\cos\\theta=4(\\sin\\theta+\\cos\\theta)\\quad\\cdots\\ \\textcircled{1}$"],"설명":"$-4\\sin\\theta$ 를 우변으로 옮겨 $4\\cos\\theta$ 와 묶는다.","확인":null,"스킬":"A2"},{"제목":"제곱해 sin θ cos θ 만의 식 만들기","힌트":"$\\textcircled{1}$ 의 양변을 제곱하고 $(\\sin\\theta+\\cos\\theta)^2=1+2\\sin\\theta\\cos\\theta$ 를 쓰면?","식":["$9\\sin^2\\theta\\cos^2\\theta=16\\left(1+2\\sin\\theta\\cos\\theta\\right)$","$9\\sin^2\\theta\\cos^2\\theta-32\\sin\\theta\\cos\\theta-16=0$"],"설명":"$\\sin^2\\theta+\\cos^2\\theta=1$ 이므로 합의 제곱이 곱만의 식이 된다.","확인":null,"스킬":"A2"},{"제목":"sin θ cos θ 의 값 구하기","고비":true,"힌트":"$\\sin\\theta\\cos\\theta=X$ 로 놓고 인수분해하면 $X$ 는 어떤 두 값인가? $\\sin\\theta$, $\\cos\\theta$ 의 범위로 하나를 버리면?","식":["$(9X+4)(X-4)=0$","$X=-\\dfrac{4}{9}\\ \\text{또는}\\ X=4$","$-1\\le\\sin\\theta\\le1,\\ -1\\le\\cos\\theta\\le1$ 이므로 $X=-\\dfrac{4}{9}$"],"설명":"두 수의 절댓값이 각각 $1$ 이하이면 곱의 절댓값도 $1$ 이하이므로 $4$ 는 불가능하다.","확인":"-4/9","스킬":"T3"},{"제목":"sin θ + cos θ 의 값 구하기","힌트":"$\\textcircled{1}$ 에 $\\sin\\theta\\cos\\theta$ 의 값을 넣으면?","식":["$\\sin\\theta+\\cos\\theta=\\dfrac{3}{4}\\sin\\theta\\cos\\theta=\\dfrac{3}{4}\\times\\left(-\\dfrac{4}{9}\\right)=-\\dfrac{1}{3}$"],"설명":"$\\textcircled{1}$ 의 양변을 $4$ 로 나눈 식을 쓴다.","확인":"-1/3","스킬":"A2"}]},"고2-202011-17":{"길":"시그마를 항으로 나열해 겹치는 항을 지우고 등차중항으로 짝 지어 a_21 을 구한다","단계":[{"제목":"두 시그마를 항으로 나열해 차 구하기","힌트":"$\\displaystyle\\sum_{k=1}^{20}a_{2k}$ 와 $\\displaystyle\\sum_{k=1}^{12}a_{2k+8}$ 이 각각 어떤 항부터 어떤 항까지인가? 겹치는 항을 빼면 어떤 항이 남는가?","식":["$\\displaystyle\\sum_{k=1}^{20}a_{2k}=a_2+a_4+\\cdots+a_{40},\\quad \\sum_{k=1}^{12}a_{2k+8}=a_{10}+a_{12}+\\cdots+a_{32}$","차 $=a_2+a_4+a_6+a_8+a_{34}+a_{36}+a_{38}+a_{40}$"],"설명":"$a_{10}$ 부터 $a_{32}$ 까지는 앞의 합에도 들어 있어서 서로 없어진다.","확인":null,"스킬":"P6"},{"제목":"등차중항으로 짝 지어 a₂₁ 구하기","고비":true,"힌트":"번호의 합이 $42$ 인 두 항 $a_m$, $a_l$ 의 합은 어느 항의 몇 배인가? 남은 여덟 항을 번호의 합이 $42$ 가 되게 짝 지으면?","식":["$a_m+a_l=2a_{21}\\quad(m+l=42)$","$(a_2+a_{40})+(a_4+a_{38})+(a_6+a_{36})+(a_8+a_{34})=4\\times2a_{21}=48$","$a_{21}=6$"],"설명":"등차수열에서 번호의 합이 같으면 항의 합도 같고, 번호가 $m$, $l$ 인 두 항의 합은 그 가운데 번호 $\\dfrac{m+l}{2}$ 인 항의 $2$ 배이다.","확인":"6","스킬":"P1"},{"제목":"a₃₉ 구하기","힌트":"번호의 합이 $42$ 인 짝 $a_3$, $a_{39}$ 에서 $a_{39}$ 는?","식":["$a_3+a_{39}=2a_{21}=12$","$a_{39}=12-1=11$"],"설명":"$3+39=42$ 이고 $a_3=1$ 이다.","확인":"11","스킬":"P1"}]},"고2-202011-18":{"길":"두 곡선의 교점 A 를 구하고 BC 가 기울기 -1 인 직선 위임을 이용해 B 를 찾아 넓이를 구한다","단계":[{"제목":"교점 A 의 좌표 구하기","힌트":"두 식을 같다고 놓고 $2^{x-1}=4\\times2^{x-3}$ 임을 쓰면 $x$ 는?","식":["$2^{x-3}+1=2^{x-1}-2\\ \\Rightarrow\\ 3\\times2^{x-3}=3$","$x=3,\\quad \\mathrm{A}(3,2)$"],"설명":"$2^{x-1}=2^2\\times2^{x-3}$ 이므로 $2^{x-3}+1=4\\times2^{x-3}-2$ 이다.","확인":null,"스킬":"G1"},{"제목":"B, C 의 좌표를 a 로 나타내기","힌트":"$\\mathrm{B}$ 의 $x$ 좌표를 $a$ 라 하자. 두 점 $\\mathrm{B}$, $\\mathrm{C}$ 는 기울기가 $-1$ 인 직선 위에 있고 $\\overline{\\mathrm{BC}}=\\sqrt{2}$ 이면 $\\mathrm{C}$ 는 $\\mathrm{B}$ 에서 $x$, $y$ 로 각각 얼마 옮긴 점인가?","식":["$\\mathrm{B}\\left(a,\\ 2^{a-3}+1\\right)$","$\\mathrm{C}\\left(a-1,\\ 2^{a-3}+2\\right)$"],"설명":"기울기가 $-1$ 이면 $x$ 가 $1$ 줄 때 $y$ 가 $1$ 늘고, 그때 두 점 사이의 거리는 $\\sqrt{1^2+1^2}=\\sqrt{2}$ 이다. 그림에서 $\\mathrm{C}$ 는 $\\mathrm{B}$ 의 왼쪽 위에 있다.","확인":null,"스킬":"G9"},{"제목":"C 가 곡선 위의 점임을 써서 a 구하기","고비":true,"힌트":"$\\mathrm{C}$ 의 좌표를 $y=2^{x-1}-2$ 에 대입하면? $2^{a-2}$ 를 $2^{a-3}$ 으로 나타내면?","식":["$2^{a-3}+2=2^{a-2}-2=2\\times2^{a-3}-2$","$2^{a-3}=4,\\quad a=5$"],"설명":"$2^{a-2}=2\\times2^{a-3}$ 이므로 $2^{a-3}$ 에 대한 일차방정식이 된다.","확인":"5","스킬":"G1"},{"제목":"직선의 식과 A 에서 직선까지의 거리","힌트":"$\\mathrm{B}$ 의 좌표를 $y=-x+k$ 에 대입해 $k$ 를 구하고, $\\mathrm{A}(3,2)$ 에서 이 직선까지의 거리를 구하면?","식":["$\\mathrm{B}(5,5)$ 이므로 $k=10$, 직선 $x+y-10=0$","$d=\\dfrac{|3+2-10|}{\\sqrt{1^2+1^2}}=\\dfrac{5}{\\sqrt{2}}$"],"설명":"$\\mathrm{B}$ 의 $y$ 좌표는 $2^{5-3}+1=5$ 이다. 이 거리가 밑변 $\\mathrm{BC}$ 에 대한 삼각형 $\\mathrm{ABC}$ 의 높이이다.","확인":null,"스킬":"G9"},{"제목":"삼각형 ABC 의 넓이 구하기","힌트":"밑변 $\\overline{\\mathrm{BC}}=\\sqrt{2}$, 높이 $\\dfrac{5}{\\sqrt{2}}$ 인 삼각형의 넓이는?","식":["$\\triangle\\mathrm{ABC}=\\dfrac{1}{2}\\times\\sqrt{2}\\times\\dfrac{5}{\\sqrt{2}}=\\dfrac{5}{2}$"],"설명":"삼각형의 넓이는 밑변 × 높이 ÷ 2 이다.","확인":"5/2","스킬":"S8"}]},"고2-202011-19":{"길":"각 항을 공차 d 로 나타내 부호에 따라 절댓값을 풀고 이차식의 최솟값에서 공차를 정한다","단계":[{"제목":"(가) a₄ 구하기","힌트":"등차수열에서 $a_3$ 과 $a_5$ 의 가운데 항은 어느 항인가? 그 합은 그 항의 몇 배인가?","식":["$a_3+a_5=2a_4=2$","$a_4=1$"],"설명":"$a_4$ 는 $a_3$ 과 $a_5$ 의 등차중항이다.","확인":"1","스킬":"P1"},{"제목":"각 항을 d 로 나타내고 부호 정하기","고비":true,"힌트":"$a_4=1$ 에서 공차 $d$ 를 이용해 $a_1$ 부터 $a_5$ 까지 쓰고, $d>1$ 일 때 각 항이 양수인지 음수인지 따지면?","식":["$a_1=1-3d,\\ a_2=1-2d,\\ a_3=1-d,\\ a_4=1,\\ a_5=1+d$","$d>1$ 이므로 $a_1<0,\\ a_2<0,\\ a_3<0,\\ a_4>0,\\ a_5>0$"],"설명":"$d>1$ 이면 $1-d<0$ 이고 $1-2d$, $1-3d$ 는 더 작다. $a_5=1+d>0$ 이다.","확인":null,"스킬":"C2"},{"제목":"(나) 절댓값의 합 f(d) 구하기","힌트":"음수인 항은 부호를 바꿔 절댓값을 풀면 합은 $d$ 의 어떤 식인가?","식":["$\\displaystyle\\sum_{k=1}^{5}\\left|a_k\\right|=(3d-1)+(2d-1)+(d-1)+1+(1+d)$","$f(d)=7d-1$"],"설명":"$|1-3d|=3d-1$, $|1-2d|=2d-1$, $|1-d|=d-1$ 이다.","확인":null,"스킬":"P6"},{"제목":"(다) 최솟값을 갖는 공차 구하기","힌트":"$\\displaystyle\\sum_{k=1}^{5}\\left(a_k^{\\,2}-5\\left|a_k\\right|\\right)$ 을 $d$ 의 이차식으로 쓰고 완전제곱 꼴로 고치면 꼭짓점의 $d$ 좌표는? 그 값이 $d>1$ 에 들어 있는가?","식":["$(15d^2-10d+5)-5(7d-1)=15d^2-45d+10$","$=15\\left(d-\\dfrac{3}{2}\\right)^2-\\dfrac{95}{4}$"],"설명":"$d=\\dfrac{3}{2}$ 은 $d>1$ 을 만족시키므로 이 값에서 최소가 된다.","확인":"3/2","스킬":"A6"},{"제목":"f(p+2q) 구하기","힌트":"$p=1$, $q=\\dfrac{3}{2}$ 이면 $p+2q$ 는? 그 값을 $f(d)=7d-1$ 에 넣으면?","식":["$p+2q=1+3=4$","$f(4)=7\\times4-1=27$"],"설명":"(가)의 값이 $p$, (다)의 값이 $q$ 이다.","확인":"27","스킬":"C6"}]},"고2-202011-21":{"길":"AP, BQ 를 문자로 놓고 코사인법칙으로 관계식을 세운 뒤 보기를 하나씩 따진다","단계":[{"제목":"변의 길이를 a, b 로 나타내기","힌트":"$\\overline{\\mathrm{AP}}=a$, $\\overline{\\mathrm{BQ}}=b$ 라 하면 $\\overline{\\mathrm{CR}}$, $\\overline{\\mathrm{BP}}$, $\\overline{\\mathrm{AR}}$ 은?","식":["$\\overline{\\mathrm{CR}}=1-a-b$","$\\overline{\\mathrm{BP}}=1-a,\\quad \\overline{\\mathrm{AR}}=1-\\overline{\\mathrm{CR}}=a+b$"],"설명":"$\\overline{\\mathrm{AP}}+\\overline{\\mathrm{BQ}}+\\overline{\\mathrm{CR}}=1$ 이고 한 변의 길이가 $1$ 이다.","확인":null,"스킬":"C7"},{"제목":"PR², PQ² 를 코사인법칙으로 쓰기","힌트":"삼각형 $\\mathrm{APR}$ 에서 $\\angle\\mathrm{A}=\\dfrac{\\pi}{3}$, 삼각형 $\\mathrm{PBQ}$ 에서 $\\angle\\mathrm{B}=\\dfrac{\\pi}{3}$ 이다. 각각 코사인법칙을 쓰면?","식":["$\\overline{\\mathrm{PR}}^{\\,2}=a^2+(a+b)^2-a(a+b)=a^2+ab+b^2$","$\\overline{\\mathrm{PQ}}^{\\,2}=b^2+(1-a)^2-b(1-a)=a^2+ab-2a+b^2-b+1$"],"설명":"$2\\times\\text{(두 변의 곱)}\\times\\cos\\dfrac{\\pi}{3}$ 은 두 변의 곱과 같다.","확인":null,"스킬":"S6"},{"제목":"ㄱ 판별: PR=PQ 로 관계식 구하기","고비":true,"힌트":"$\\overline{\\mathrm{PR}}^{\\,2}=\\overline{\\mathrm{PQ}}^{\\,2}$ 으로 $a$, $b$ 사이의 식을 세우면? 그 식에서 $3a+2b$ 는 $2$ 와 어떻게 비교되는가?","식":["$a^2+ab+b^2=a^2+ab-2a+b^2-b+1\\ \\Rightarrow\\ 2a+b=1$","$3a+2b=2(2a+b)-a=2-a<2$"],"설명":"$a=\\overline{\\mathrm{AP}}>0$ 이므로 $3\\overline{\\mathrm{AP}}+2\\overline{\\mathrm{BQ}}$ 는 $2$ 보다 작다. 따라서 ㄱ 은 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"ㄴ 판별: 삼각형 CRQ 의 모양과 QR","힌트":"$b=1-2a$ 를 써서 $\\overline{\\mathrm{CQ}}$, $\\overline{\\mathrm{CR}}$ 을 $a$ 로 나타내면 두 변의 길이의 비는? $\\angle\\mathrm{C}=\\dfrac{\\pi}{3}$ 이면 삼각형 $\\mathrm{CRQ}$ 는 어떤 삼각형인가?","식":["$\\overline{\\mathrm{CQ}}=1-b=2a,\\quad \\overline{\\mathrm{CR}}=1-a-b=a$","$\\angle\\mathrm{QRC}=\\dfrac{\\pi}{2},\\quad \\overline{\\mathrm{QR}}=\\sqrt{(2a)^2-a^2}=\\sqrt{3}\\,a$"],"설명":"한 각이 $\\dfrac{\\pi}{3}$ 이고 그 끼인 두 변의 비가 $2:1$ 이면 나머지 한 각이 $\\dfrac{\\pi}{2}$ 인 직각삼각형이다. 따라서 ㄴ 은 옳다.","확인":null,"스킬":"S6"},{"제목":"ㄷ 판별: 외접원 조건을 변의 식으로 바꾸기","힌트":"두 삼각형의 외접원의 반지름을 $R_1$, $R_2$ 라 하면 넓이가 $2$ 배일 때 $R_1$ 과 $R_2$ 의 관계는? 사인법칙으로 $\\overline{\\mathrm{PQ}}$ 와 $\\overline{\\mathrm{QR}}$ 의 관계를 구하면?","식":["$R_1=\\sqrt{2}\\,R_2$","$\\dfrac{\\overline{\\mathrm{PQ}}}{\\sin\\frac{\\pi}{3}}=2R_1,\\quad \\dfrac{\\overline{\\mathrm{QR}}}{\\sin\\frac{\\pi}{3}}=2R_2\\ \\Rightarrow\\ \\overline{\\mathrm{PQ}}^{\\,2}=2\\,\\overline{\\mathrm{QR}}^{\\,2}$"],"설명":"원의 넓이는 반지름의 제곱에 비례하므로 넓이가 $2$ 배이면 반지름은 $\\sqrt{2}$ 배이다. 두 삼각형 모두 $\\sin\\dfrac{\\pi}{3}$ 의 각이 마주 보는 변이 $\\overline{\\mathrm{PQ}}$, $\\overline{\\mathrm{QR}}$ 이다.","확인":null,"스킬":"S6"},{"제목":"ㄷ 판별: AP 의 값 구하기","힌트":"$b=1-2a$ 를 $\\overline{\\mathrm{PQ}}^{\\,2}$ 에 넣고 $\\overline{\\mathrm{QR}}^{\\,2}=3a^2$ 과 $\\overline{\\mathrm{PQ}}^{\\,2}=2\\overline{\\mathrm{QR}}^{\\,2}$ 에 넣으면 $a$ 는?","식":["$\\overline{\\mathrm{PQ}}^{\\,2}=3a^2-3a+1,\\quad \\overline{\\mathrm{QR}}^{\\,2}=3a^2$","$3a^2-3a+1=6a^2\\ \\Rightarrow\\ 3a^2+3a-1=0$","$a=\\dfrac{-3+\\sqrt{21}}{6}$"],"설명":"$a>0$ 이므로 근의 공식에서 $+$ 부호의 해만 택한다. 따라서 ㄷ 은 옳고, 옳은 것은 ㄴ, ㄷ 이다.","확인":null,"스킬":"S6"}]},"고2-202011-23":{"길":"밑이 1 보다 큰 로그함수는 증가하므로 구간의 오른쪽 끝에서 최댓값을 갖는다","단계":[{"제목":"최댓값을 갖는 위치 찾기","힌트":"밑 $2$ 가 $1$ 보다 크면 $x$ 가 커질 때 $y$ 는 어떻게 변하는가? 그러면 최댓값은 구간의 어느 끝에서 나오는가?","식":["$y=\\log_2(x+1)+2$ 는 증가함수","$x=7$ 일 때 최대"],"설명":"증가함수는 $x$ 가 클수록 $y$ 도 크다.","확인":null,"스킬":"T3"},{"제목":"최댓값 계산하기","고비":true,"힌트":"$x=7$ 을 대입하면 $\\log_28$ 의 값은?","식":["$y=\\log_2(7+1)+2=\\log_28+2=3+2=5$"],"설명":"$\\log_28=\\log_22^3=3$ 이다.","확인":"5","스킬":"T3"}]},"고2-202011-24":{"길":"4^a 를 2 의 거듭제곱으로 바꿔 2^a 를 구하고 2^{3-a} 에 대입한다","단계":[{"제목":"2^a 의 값 구하기","고비":true,"힌트":"$4^a$ 를 $2$ 의 거듭제곱으로 쓰면 $2^a$ 의 제곱이다. $2^a$ 의 값은 양수이어야 한다.","식":["$4^a=\\left(2^a\\right)^2=\\dfrac{4}{9}$","$2^a=\\dfrac{2}{3}$"],"설명":"$2^a>0$ 이므로 제곱해서 $\\dfrac{4}{9}$ 가 되는 양수는 $\\dfrac{2}{3}$ 뿐이다.","확인":"2/3","스킬":"A9"},{"제목":"2^{3−a} 구하기","힌트":"$2^{3-a}$ 를 $2^3$ 과 $2^{-a}$ 의 곱으로 나누고 $2^{-a}$ 는 $2^a$ 의 역수로 쓰면?","식":["$2^{3-a}=2^3\\times2^{-a}=8\\times\\dfrac{3}{2}=12$"],"설명":"$2^{-a}=\\dfrac{1}{2^a}=\\dfrac{3}{2}$ 이다.","확인":"12","스킬":"A9"}]},"고2-202011-25":{"길":"공차를 첫째항으로 나타내 제곱의 합 조건에 넣고 양수인 첫째항을 구한다","단계":[{"제목":"공차를 첫째항으로 나타내기","힌트":"공차를 $d$ 라 하고 $a_5=a_1+4d$ 를 $3a_1$ 과 같게 놓으면 $a_1$ 과 $d$ 의 관계는?","식":["$a_1+4d=3a_1$","$a_1=2d$"],"설명":"$a_5=a_1+4d$ 이다. $a_1=2d$ 이므로 $d=\\dfrac{a_1}{2}$ 이다.","확인":null,"스킬":"P1"},{"제목":"a₁ 의 값 구하기","고비":true,"힌트":"$a_3=a_1+2d$ 를 $a_1$ 로 나타내고 $a_1^{\\,2}+a_3^{\\,2}=20$ 에 넣으면? 첫째항이 양수임을 쓰면?","식":["$a_3=a_1+2d=2a_1$","$a_1^{\\,2}+\\left(2a_1\\right)^2=5a_1^{\\,2}=20,\\quad a_1^{\\,2}=4$","$a_1=2$"],"설명":"첫째항이 양수이므로 $a_1=-2$ 는 버린다.","확인":"2","스킬":"P1"},{"제목":"a₅ 구하기","힌트":"$a_5=3a_1$ 에 $a_1$ 을 넣으면?","식":["$a_5=3a_1=3\\times2=6$"],"설명":"조건 $a_5=3a_1$ 을 그대로 쓴다.","확인":"6","스킬":"P1"}]},"고2-202011-26":{"길":"시그마의 성질로 b_k 의 합을 구하고 k 의 합을 더한다","단계":[{"제목":"Σ b_k 구하기","힌트":"$\\displaystyle\\sum_{k=1}^{10}\\left(a_k+b_k\\right)$ 를 $a_k$ 의 합과 $b_k$ 의 합으로 나누면?","식":["$\\displaystyle\\sum_{k=1}^{10}\\left(a_k+b_k\\right)=\\sum_{k=1}^{10}a_k+\\sum_{k=1}^{10}b_k=9$","$\\displaystyle\\sum_{k=1}^{10}b_k=9-3=6$"],"설명":"합의 시그마는 각각의 시그마의 합으로 나눌 수 있다.","확인":"6","스킬":"P6"},{"제목":"Σ k 구하기","힌트":"$1$ 부터 $10$ 까지 자연수의 합은?","식":["$\\displaystyle\\sum_{k=1}^{10}k=\\dfrac{10\\times11}{2}=55$"],"설명":"자연수의 합 공식 $\\dfrac{n(n+1)}{2}$ 을 쓴다.","확인":"55","스킬":"P6"},{"제목":"Σ(b_k + k) 구하기","고비":true,"힌트":"$\\displaystyle\\sum_{k=1}^{10}\\left(b_k+k\\right)$ 을 두 시그마로 나누어 앞에서 구한 값을 더하면?","식":["$\\displaystyle\\sum_{k=1}^{10}\\left(b_k+k\\right)=\\sum_{k=1}^{10}b_k+\\sum_{k=1}^{10}k=6+55=61$"],"설명":"앞에서 구한 두 값을 더한다.","확인":"61","스킬":"P6"}]},"고2-202011-27":{"길":"근과 계수의 관계로 두 근의 합이 0 임을 써서 sin θ 를 구하고 곱에서 k 를 구한다","단계":[{"제목":"두 근의 합으로 식 세우기","힌트":"$x^2-k=0$ 의 두 근의 합은? $\\tan\\theta=\\dfrac{\\sin\\theta}{\\cos\\theta}$ 로 바꾸고 양변에 $\\cos\\theta$ 를 곱하면?","식":["$6\\cos\\theta+5\\tan\\theta=0$","$6\\cos^2\\theta+5\\sin\\theta=0$"],"설명":"$x^2-k=0$ 에는 $x$ 의 일차항이 없으므로 두 근의 합은 $0$ 이다. 근이 존재하려면 $\\cos\\theta\\ne0$ 이다.","확인":null,"스킬":"A2"},{"제목":"sin θ 에 대한 이차방정식 만들기","힌트":"$\\cos^2\\theta=1-\\sin^2\\theta$ 를 넣어 $\\sin\\theta$ 만의 식으로 쓰고 인수분해하면?","식":["$6\\left(1-\\sin^2\\theta\\right)+5\\sin\\theta=0$","$6\\sin^2\\theta-5\\sin\\theta-6=0,\\quad (3\\sin\\theta+2)(2\\sin\\theta-3)=0$"],"설명":"$\\sin^2\\theta+\\cos^2\\theta=1$ 을 이용한다.","확인":null,"스킬":"T5"},{"제목":"sin θ 의 값 구하기","고비":true,"힌트":"두 해 중 $\\sin\\theta$ 의 범위 $-1\\le\\sin\\theta\\le1$ 에 맞는 것은?","식":["$\\sin\\theta=-\\dfrac{2}{3}\\ \\text{또는}\\ \\sin\\theta=\\dfrac{3}{2}$","$\\sin\\theta=-\\dfrac{2}{3}$"],"설명":"$\\dfrac{3}{2}$ 는 $1$ 보다 커서 사인의 값이 될 수 없다.","확인":"-2/3","스킬":"T3"},{"제목":"두 근의 곱으로 k 구하기","힌트":"두 근의 곱은 $-k$ 이다. $6\\cos\\theta\\times5\\tan\\theta$ 를 $\\sin\\theta$ 로 나타내면?","식":["$-k=6\\cos\\theta\\times5\\tan\\theta=30\\sin\\theta=-20$","$k=20$"],"설명":"$\\cos\\theta\\tan\\theta=\\sin\\theta$ 이다.","확인":"20","스킬":"A2"}]},"고2-202011-30":{"길":"g 를 두 직선과의 교점 수로 바꿔 g(18)=5 인 a, b 를 정하고 한 주기마다 늘어나는 교점 수로 α 의 범위를 구한다","단계":[{"제목":"주기와 a, b 의 관계 구하기","힌트":"$\\sin\\dfrac{\\pi}{6}(x-1)$ 의 주기는? $f(0)=8$ 에서 $a$ 를 $b$ 로 나타내면?","식":["주기 $\\dfrac{2\\pi}{\\frac{\\pi}{6}}=12$","$f(0)=a\\sin\\left(-\\dfrac{\\pi}{6}\\right)+b=-\\dfrac{a}{2}+b=8$","$a=2b-16$"],"설명":"사인의 주기 $2\\pi$ 를 $x$ 의 계수 $\\dfrac{\\pi}{6}$ 로 나눈다.","확인":"12","스킬":"T2"},{"제목":"g(t) 를 두 직선과의 교점 수로 바꾸기","힌트":"$|f(x)|=4$ 는 $f(x)$ 가 어떤 값일 때인가?","식":["$|f(x)|=4\\ \\Longleftrightarrow\\ f(x)=4$ 또는 $f(x)=-4$","$g(t)=$ ($y=f(x)$ 와 $y=4$ 의 교점 수) $+$ ($y=f(x)$ 와 $y=-4$ 의 교점 수)"],"설명":"$0<x<t$ 에서 $y=f(x)$ 가 두 직선 $y=4$, $y=-4$ 와 만나는 점의 개수를 각각 세어 더한다.","확인":null,"스킬":"G5"},{"제목":"a>0 이면 g(18)=5 가 불가능함 보이기","힌트":"$a=2b-16>0$ 이면 $b$ 의 범위와 $f(18)$ 은? $0<x<18$ 에서 $f$ 의 값이 $4$ 이하로 내려가는 구간은 몇 곳인가?","식":["$a>0\\ \\Rightarrow\\ b>8,\\quad f(18)=\\dfrac{a}{2}+b=2b-8>8$","$f$ 의 값이 $4$ 이하인 구간은 최솟값 부근 한 곳뿐이어서 $g(18)\\le2+2=4$"],"설명":"$f(0)=8$ 에서 $f$ 는 증가하여 최대가 된 뒤 감소하고 최소를 지나 다시 증가한다. $f(18)>8$ 이므로 그래프가 $y=4$ 아래로 내려가는 곳은 최솟값 부근의 한 곳뿐이고, 그곳에서 $y=4$, $y=-4$ 와 각각 최대 $2$ 번 만난다. 따라서 $g(18)=5$ 인 $a$, $b$ 는 없다.","확인":null,"스킬":"C2"},{"제목":"a<0 일 때 최솟값별로 g(18) 구하기","고비":true,"힌트":"$a<0$ 이면 $f$ 의 최솟값은 $b+a=3b-16$ 이다. 이 값을 $m$ 이라 하고, $m$ 이 $4$, $2$, $-4$, $-10$ 을 기준으로 어느 구간에 있는지에 따라 $f(18)$ 과 교점 수를 따지면?","식":["$4<m<8$ 이면 $g(18)=0,\\quad m=4$ 이면 $2,\\quad 2<m<4$ 이면 $4$","$-4<m\\le2$ 이면 $g(18)=3,\\quad m=-4$ 이면 $5$","$-10<m<-4$ 이면 $g(18)=7,\\quad m\\le-10$ 이면 $6$"],"설명":"$a<0$ 이면 $b<8$ 이고 $f(18)=2b-8$ 이다. $m$ 의 범위마다 $y=f(x)$ 의 그래프를 $0<x<18$ 에서 그려 두 직선과의 교점을 센다. $m=4$ 나 $m=-4$ 처럼 최솟값이 직선에 닿는 경우는 접점도 교점으로 센다. $g(18)=5$ 가 되는 경우는 $m=-4$ 뿐이다.","확인":null,"스킬":"C2"},{"제목":"a, b 의 값 구하기","힌트":"$g(18)=5$ 이려면 최솟값 $3b-16$ 은? 그때 $b$ 와 $a=2b-16$ 은?","식":["$3b-16=-4\\ \\Rightarrow\\ b=4$","$a=2b-16=-8$"],"설명":"$m=-4$ 일 때 $f(18)=0$ 이고 $0<x<18$ 에서 $y=4$ 와 $3$ 번, $y=-4$ 와 $2$ 번(접하는 점) 만나 합이 $5$ 이다.","확인":"-8","스킬":"T2"},{"제목":"한 주기마다 늘어나는 교점 수 구하기","힌트":"$f(x)=-8\\sin\\dfrac{\\pi}{6}(x-1)+4$ 가 $y=4$, $y=-4$ 와 만나는 $x$ 좌표를 작은 것부터 구하면? $|a-b|$ 는? 한 주기 $12$ 마다 교점은 몇 개씩 늘어나는가?","식":["$y=4$: $x=1,\\ 7,\\ 13,\\ 19,\\ \\cdots$ (간격 $6$), $y=-4$: $x=4,\\ 16,\\ 28,\\ \\cdots$ (간격 $12$)","$|a-b|=|-8-4|=12$","한 주기마다 $2+1=3$ 개씩 늘어난다"],"설명":"$f(x)=4$ 이면 $\\sin\\dfrac{\\pi}{6}(x-1)=0$, $f(x)=-4$ 이면 $\\sin\\dfrac{\\pi}{6}(x-1)=1$ 이다. $g(\\alpha)=12$ 가 되게 하는 $\\alpha$ 를 찾는다.","확인":"3","스킬":"T2"},{"제목":"g(α)=12 인 α 의 범위와 최댓값","힌트":"$7<\\alpha\\le13$ 이면 $0<x<\\alpha$ 에서 교점 $x=1,\\ 4,\\ 7$ 은 몇 개인가? 거기에 한 주기($12$)당 $3$ 개씩 몇 번 더하면 $12$ 개가 되는가?","식":["$7<\\alpha\\le13$ 일 때 $g(\\alpha)=3$","$3+3\\times3=12$ 이므로 $12\\times3$ 만큼 옮기면 $7+36<\\alpha\\le13+36$","$43<\\alpha\\le49$"],"설명":"$0<x<\\alpha$ 이므로 $\\alpha=13$ 일 때 $x=13$ 의 교점은 세지 않는다. $\\alpha$ 의 범위의 가장 큰 값이 최댓값이다.","확인":"49","스킬":"T2"}]},"고2-202106-04":{"길":"제2사분면의 해를 π 에서 기준각을 뺀 꼴로 놓고 코사인 값으로 기준각을 구한다","단계":[{"제목":"기준각 구하기","고비":true,"힌트":"$\\dfrac{\\pi}{2}\\le x\\le\\pi$ 이므로 $x=\\pi-\\theta\\ \\left(0\\le\\theta\\le\\dfrac{\\pi}{2}\\right)$ 로 놓으면 $\\cos x$ 는 $\\cos\\theta$ 로 어떻게 쓰이는가?","식":["$\\cos x=\\cos(\\pi-\\theta)=-\\cos\\theta=-\\dfrac{1}{2}$","$\\cos\\theta=\\dfrac{1}{2},\\quad \\theta=\\dfrac{\\pi}{3}$"],"설명":"$\\cos(\\pi-\\theta)=-\\cos\\theta$ 이다. $0\\le\\theta\\le\\dfrac{\\pi}{2}$ 에서 코사인이 $\\dfrac{1}{2}$ 인 각은 $\\dfrac{\\pi}{3}$ 뿐이다.","확인":null,"스킬":"T5"},{"제목":"x 의 값 구하기","힌트":"$x=\\pi-\\theta$ 에 $\\theta$ 를 넣으면?","식":["$x=\\pi-\\dfrac{\\pi}{3}=\\dfrac{2}{3}\\pi$"],"설명":"구한 기준각을 $\\pi$ 에서 뺀다.","확인":null,"스킬":"T5"}]},"고2-202106-05":{"길":"곱의 로그를 합으로 나누고 상용로그표에서 3.14 의 로그를 읽어 계산한다","단계":[{"제목":"로그를 합으로 나누기","고비":true,"힌트":"$\\log\\left(3.14\\times10^{-2}\\right)$ 를 $\\log3.14$ 와 $\\log10^{-2}$ 의 합으로 쓰면 $\\log10^{-2}$ 는?","식":["$\\log\\left(3.14\\times10^{-2}\\right)=\\log3.14+\\log10^{-2}$","$=\\log3.14-2$"],"설명":"곱의 로그는 로그의 합이다. 상용로그이므로 $\\log10^{-2}=-2$ 이다.","확인":null,"스킬":"A9"},{"제목":"표에서 log 3.14 를 읽어 값 구하기","힌트":"표에서 $3.1$ 이 있는 행과 $4$ 가 있는 열이 만나는 칸의 수는 $\\log3.14$ 이다. 거기서 $2$ 를 빼면?","식":["$\\log3.14=0.4969$","$\\log\\left(3.14\\times10^{-2}\\right)=0.4969-2=-1.5031$"],"설명":"$3.14$ 는 $3.1$ 의 행, $4$ 의 열로 찾는다.","확인":"-1.5031","스킬":"A9"}]},"고2-202106-06":{"길":"사인과 코사인의 제곱의 합으로 sin²θ 를 구하고 각이 속한 사분면으로 부호를 정한다","단계":[{"제목":"sin²θ 구하기","힌트":"$\\sin^2\\theta+\\cos^2\\theta=1$ 에 $\\cos\\theta=-\\dfrac{2}{3}$ 를 넣으면?","식":["$\\sin^2\\theta=1-\\cos^2\\theta=1-\\dfrac{4}{9}=\\dfrac{5}{9}$"],"설명":"$\\cos^2\\theta=\\left(-\\dfrac{2}{3}\\right)^2=\\dfrac{4}{9}$ 이다.","확인":"5/9","스킬":"T5"},{"제목":"부호를 정해 sin θ 구하기","고비":true,"힌트":"$\\pi<\\theta<\\dfrac{3}{2}\\pi$ 는 몇 사분면인가? 그 사분면에서 $\\sin\\theta$ 의 부호는?","식":["$\\sin\\theta=\\pm\\dfrac{\\sqrt{5}}{3}$","제$3$사분면에서 $\\sin\\theta<0$ 이므로 $\\sin\\theta=-\\dfrac{\\sqrt{5}}{3}$"],"설명":"$\\pi<\\theta<\\dfrac{3}{2}\\pi$ 는 제$3$사분면이고, 이 사분면에서 $\\sin\\theta$, $\\cos\\theta$ 는 모두 음수이다.","확인":null,"스킬":"T5"}]},"고2-202106-07":{"길":"지수의 로그를 하나로 합친 뒤 밑을 2 로 맞춰 a 의 log_a b 제곱 꼴로 만든다","단계":[{"제목":"지수를 log₂ 하나로 나타내기","힌트":"$1=\\log_22$ 로 쓰고 $\\log_23$ 과 더하면?","식":["$1+\\log_23=\\log_22+\\log_23=\\log_26$","$(\\sqrt{2})^{1+\\log_23}=(\\sqrt{2})^{\\log_26}$"],"설명":"로그의 합은 진수의 곱의 로그이다.","확인":null,"스킬":"A9"},{"제목":"밑을 2 로 바꿔 계산하기","고비":true,"힌트":"$\\sqrt{2}=2^{\\frac{1}{2}}$ 로 쓰고, 지수 $\\dfrac{1}{2}\\log_26$ 을 $\\log_2\\sqrt{6}$ 으로 고치면?","식":["$(\\sqrt{2})^{\\log_26}=2^{\\frac{1}{2}\\log_26}=2^{\\log_2\\sqrt{6}}$","$=\\sqrt{6}$"],"설명":"$a\\log_bc=\\log_bc^a$ 이고 $2^{\\log_2x}=x$ 이다.","확인":null,"스킬":"A9"}]},"고2-202106-08":{"길":"밑이 1 보다 작은 지수함수는 감소함을 이용해 양 끝에서 최댓값·최솟값을 두고 a, b 를 구한다","단계":[{"제목":"함수의 증감과 최대·최소의 위치 정하기","고비":true,"힌트":"$a\\times2^{2-x}$ 를 $4a\\times\\left(\\dfrac{1}{2}\\right)^x$ 으로 고치면 $a>0$ 일 때 $x$ 가 커지면 $y$ 는 어떻게 되는가?","식":["$f(x)=4a\\times\\left(\\dfrac{1}{2}\\right)^x+b$ 는 감소함수","$x=-1$ 에서 최대, $x=2$ 에서 최소"],"설명":"$2^{2-x}=2^2\\times2^{-x}=4\\times\\left(\\dfrac{1}{2}\\right)^x$ 이다. $a>0$ 이고 밑이 $1$ 보다 작으므로 감소한다.","확인":null,"스킬":"T3"},{"제목":"a, b 구하기","힌트":"$f(-1)=5$, $f(2)=-2$ 를 식으로 쓰고 두 식을 빼면?","식":["$f(-1)=a\\times2^3+b=8a+b=5$","$f(2)=a\\times2^0+b=a+b=-2$","$a=1,\\quad b=-3$"],"설명":"두 식을 변끼리 빼면 $7a=7$ 이다.","확인":"-3","스킬":"T3"},{"제목":"f(0) 구하기","힌트":"$f(0)=a\\times2^2+b$ 에 $a$, $b$ 를 넣으면?","식":["$f(0)=4a+b=4-3=1$"],"설명":"구한 $a$, $b$ 를 대입한다.","확인":"1","스킬":"T3"}]},"고2-202106-09":{"길":"점근선으로 a 를 정하고 지나는 점에서 b 를 구해 합한다","단계":[{"제목":"점근선으로 a 구하기","고비":true,"힌트":"$y=\\log_2(x-a)+1$ 의 점근선은 어떤 직선인가? 그것이 $x=3$ 이면 $a$ 는?","식":["점근선 $x=a$","$a=3$"],"설명":"$y=\\log_2x$ 의 점근선 $x=0$ 을 $x$ 축 방향으로 $a$ 만큼 옮긴 것이다.","확인":null,"스킬":"G4"},{"제목":"점 (7, b) 로 b 구하기","힌트":"$y=\\log_2(x-3)+1$ 에 $x=7$ 을 넣으면?","식":["$b=\\log_2(7-3)+1=\\log_24+1=3$"],"설명":"$\\log_24=2$ 이다.","확인":"3","스킬":"G4"},{"제목":"a + b 구하기","힌트":"$a=3$, $b=3$ 을 더하면?","식":["$a+b=3+3=6$"],"설명":"앞에서 구한 두 값을 더한다.","확인":"6","스킬":"G4"}]},"고2-202106-10":{"길":"그래프의 점근선 간격으로 주기를 읽어 b 를 정하고 지나는 두 점으로 c 와 a 를 구한다","단계":[{"제목":"주기로 b 구하기","고비":true,"힌트":"그림에서 이웃한 두 점근선 $x=-\\pi$, $x=\\pi$ 사이의 간격이 주기이다. $y=a\\tan bx+c$ 의 주기는 $\\dfrac{\\pi}{b}$ 이다. $b$ 는?","식":["주기 $=\\pi-(-\\pi)=2\\pi$","$\\dfrac{\\pi}{b}=2\\pi,\\quad b=\\dfrac{1}{2}$"],"설명":"탄젠트 함수는 주기마다 점근선이 하나씩 있다. $b>0$ 이다.","확인":"1/2","스킬":"T2"},{"제목":"점 (0, 2) 로 c 구하기","힌트":"$y=a\\tan\\dfrac{x}{2}+c$ 에 $x=0$ 을 넣으면?","식":["$2=a\\tan0+c=c$","$c=2$"],"설명":"$\\tan0=0$ 이므로 $y$ 절편이 $c$ 이다.","확인":null,"스킬":"T4"},{"제목":"점 (π/2, 5) 로 a 구하기","힌트":"$y=a\\tan\\dfrac{x}{2}+2$ 에 $x=\\dfrac{\\pi}{2}$ 를 넣으면?","식":["$5=a\\tan\\dfrac{\\pi}{4}+2=a+2$","$a=3$"],"설명":"$\\tan\\dfrac{\\pi}{4}=1$ 이다.","확인":null,"스킬":"T4"},{"제목":"a×b×c 구하기","힌트":"$a=3$, $b=\\dfrac{1}{2}$, $c=2$ 를 곱하면?","식":["$a\\times b\\times c=3\\times\\dfrac{1}{2}\\times2=3$"],"설명":"구한 세 값을 곱한다.","확인":"3","스킬":"T4"}]},"고2-202106-11":{"길":"양변의 밑을 2로 통일해 지수를 같게 놓고 이차방정식의 근을 모두 더한다","단계":[{"제목":"밑을 2로 통일해 지수 방정식 세우기","고비":true,"힌트":"$\\left(\\dfrac{1}{4}\\right)^{x^2}$ 을 밑이 $2$ 인 거듭제곱으로 나타내면? 그러면 지수끼리 어떤 관계가 되는가?","식":["$\\left(\\dfrac{1}{4}\\right)^{x^2}=\\left(2^{-2}\\right)^{x^2}=2^{-2x^2}$","$2^{x-6}=2^{-2x^2}$ 이므로 $x-6=-2x^2$"],"설명":"밑이 같고 $1$ 이 아닌 양수이면 지수가 같아야 하므로 지수끼리 같다고 놓는다.","확인":null,"스킬":"A9"},{"제목":"이차방정식의 해 구하기","힌트":"$2x^2+x-6=0$ 을 인수분해하면? 두 근 중 양수인 근은?","식":["$2x^2+x-6=0$","$(x+2)(2x-3)=0$","$x=-2$ 또는 $x=\\dfrac{3}{2}$"],"설명":"이항하여 인수분해한다.","확인":"3/2","스킬":"A2"},{"제목":"모든 해의 합 구하기","힌트":"두 근 $-2$ 와 $\\dfrac{3}{2}$ 를 더하면?","식":["$-2+\\dfrac{3}{2}=-\\dfrac{1}{2}$"],"설명":"해가 두 개이므로 모두 더한다.","확인":"-1/2","스킬":"A2"}]},"고2-202106-12":{"길":"주어진 관계식에 값을 넣어 로그의 값을 구하고 지수 꼴로 바꿔 a 를 구한다","단계":[{"제목":"관계식에 대입해 로그의 값 구하기","힌트":"$C=75$, $W=15$, $S=186$, $N=a$ 를 넣고 양변을 $15$ 로 나누면 $\\log_2$ 의 값은?","식":["$75=15\\log_2\\left(1+\\dfrac{186}{a}\\right)$","$\\log_2\\left(1+\\dfrac{186}{a}\\right)=5$"],"설명":"채널용량, 대역폭, 신호전력, 잡음전력을 각각 관계식의 $C$, $W$, $S$, $N$ 에 넣는다.","확인":"5","스킬":"C6"},{"제목":"로그를 지수 꼴로 바꾸기","고비":true,"힌트":"$\\log_2 X=5$ 이면 $X$ 는 $2$ 의 몇 제곱인가? $1+\\dfrac{186}{a}$ 는 얼마와 같은가?","식":["$1+\\dfrac{186}{a}=2^5=32$"],"설명":"$\\log_2 X=5$ 는 $X=2^5$ 과 같은 뜻이다.","확인":"32","스킬":"A9"},{"제목":"a 의 값 구하기","힌트":"$1+\\dfrac{186}{a}=32$ 에서 $\\dfrac{186}{a}$ 는? $a$ 는?","식":["$\\dfrac{186}{a}=31$","$a=6$"],"설명":"양변에서 $1$ 을 빼고 $a$ 에 대해 푼다.","확인":"6","스킬":"A9"}]},"고2-202106-13":{"길":"부등식을 sin x 의 범위로 바꾸고 그래프의 대칭축에서 α+β 를 읽어 코사인 값을 구한다","단계":[{"제목":"부등식을 sin x 의 범위로 바꾸기","힌트":"$3\\sin x-2>0$ 에서 $\\sin x$ 는 어떤 수보다 큰가?","식":["$3\\sin x-2>0$","$\\sin x>\\dfrac{2}{3}$"],"설명":"$-2$ 를 이항하고 양변을 $3$ 으로 나눈다.","확인":"2/3","스킬":"T5"},{"제목":"그래프에서 α, β 의 뜻 읽기","힌트":"$y=\\sin x$ 와 $y=\\dfrac{2}{3}$ 의 그래프에서 $\\sin x>\\dfrac{2}{3}$ 인 구간은 어디인가? $\\alpha$, $\\beta$ 는 각각 무엇인가?","식":["$0\\le x<2\\pi$ 에서 $y=\\sin x$ 와 $y=\\dfrac{2}{3}$ 의 두 교점의 $x$ 좌표가 $\\alpha$, $\\beta$","$0<\\alpha<\\dfrac{\\pi}{2}<\\beta<\\pi$"],"설명":"$\\sin x$ 가 $\\dfrac{2}{3}$ 보다 큰 구간은 두 교점 사이이고, 그 구간이 $\\alpha<x<\\beta$ 이다.","확인":null,"스킬":"T5"},{"제목":"대칭으로 α+β 구하기","고비":true,"힌트":"$y=\\sin x$ 의 그래프는 $x=\\dfrac{\\pi}{2}$ 에 대해 어떤 모양인가? $\\dfrac{\\pi}{2}-\\alpha$ 와 $\\beta-\\dfrac{\\pi}{2}$ 의 관계는?","식":["$\\dfrac{\\pi}{2}-\\alpha=\\beta-\\dfrac{\\pi}{2}$","$\\alpha+\\beta=\\pi$"],"설명":"그래프가 $x=\\dfrac{\\pi}{2}$ 에 대칭이므로 두 교점은 이 직선에서 같은 거리에 있다.","확인":null,"스킬":"T2"},{"제목":"cos(α+β) 의 값 구하기","힌트":"$\\alpha+\\beta=\\pi$ 를 $\\cos$ 안에 넣으면?","식":["$\\cos(\\alpha+\\beta)=\\cos\\pi=-1$"],"설명":"$\\cos\\pi$ 는 단위원에서 점 $(-1,\\ 0)$ 의 $x$ 좌표이다.","확인":"-1","스킬":"T5"}]},"고2-202106-14":{"길":"t 와 1/t 중 어느 쪽이 1 보다 큰지로 경우를 나누어 각 구간에서 t 를 구해 더한다","단계":[{"제목":"t 의 범위를 세 경우로 나누기","고비":true,"힌트":"$0<t<1$ 이면 $\\dfrac{1}{t}$ 은 $1$ 보다 큰가 작은가? 그때 $f(t)$ 와 $f\\left(\\dfrac{1}{t}\\right)$ 는 각각? $t=1$ 과 $t>1$ 도 같은 방법으로 따진다.","식":["$0<t<1$ 이면 $\\dfrac{1}{t}>1$ 이므로 $f(t)=0,\\ f\\left(\\dfrac{1}{t}\\right)=\\log_3\\dfrac{1}{t}$","$t=1$ 이면 $f(1)+f(1)=0\\ne2$","$t>1$ 이면 $0<\\dfrac{1}{t}<1$ 이므로 $f(t)=\\log_3t,\\ f\\left(\\dfrac{1}{t}\\right)=0$"],"설명":"$f$ 의 식이 $x$ 가 $1$ 이하인지 $1$ 보다 큰지에 따라 달라지므로 $t$ 와 $\\dfrac{1}{t}$ 가 어느 쪽에 있는지로 나눈다. $t=1$ 이면 합이 $0$ 이라 조건을 만족시키지 못한다.","확인":null,"스킬":"C2"},{"제목":"0<t<1 일 때의 t 구하기","힌트":"$0+\\log_3\\dfrac{1}{t}=2$ 에서 $\\dfrac{1}{t}$ 은? $t$ 는?","식":["$\\log_3\\dfrac{1}{t}=2$","$\\dfrac{1}{t}=3^2=9$","$t=\\dfrac{1}{9}$"],"설명":"로그를 지수 꼴로 바꾸면 $\\dfrac{1}{t}=9$ 이고, $0<t<1$ 을 만족한다.","확인":"1/9","스킬":"T3"},{"제목":"t>1 일 때의 t 구하기","힌트":"$\\log_3t+0=2$ 에서 $t$ 는?","식":["$\\log_3t=2$","$t=3^2=9$"],"설명":"$t=9$ 는 $t>1$ 을 만족한다.","확인":"9","스킬":"T3"},{"제목":"모든 양수 t 의 값의 합 구하기","힌트":"$\\dfrac{1}{9}$ 과 $9$ 를 더하면?","식":["$\\dfrac{1}{9}+9=\\dfrac{82}{9}$"],"설명":"조건을 만족시키는 양수 $t$ 는 $\\dfrac{1}{9}$ 과 $9$ 뿐이다.","확인":"82/9","스킬":"T3"}]},"고2-202106-15":{"길":"각의 이등분선의 비로 PC 를 k 로 두고 코사인법칙과 사인법칙으로 외접원의 반지름을 구한다","단계":[{"제목":"각의 이등분선의 성질로 길이 두기","힌트":"$\\mathrm{AP}$ 가 $\\angle\\mathrm{BAC}$ 의 이등분선이면 $\\overline{\\mathrm{BP}}:\\overline{\\mathrm{PC}}$ 는 어떤 두 변의 비와 같은가? $\\overline{\\mathrm{PC}}=k$ 라 하면 $\\overline{\\mathrm{BC}}$ 는?","식":["$\\overline{\\mathrm{BP}}:\\overline{\\mathrm{PC}}=\\overline{\\mathrm{AB}}:\\overline{\\mathrm{AC}}=3:1$","$\\overline{\\mathrm{PC}}=k,\\ \\overline{\\mathrm{BP}}=3k,\\ \\overline{\\mathrm{BC}}=4k$"],"설명":"각의 이등분선은 대변을 그 각을 낀 두 변의 길이의 비로 나눈다.","확인":null,"스킬":"S10"},{"제목":"삼각형 ABC 에서 코사인법칙으로 k 구하기","고비":true,"힌트":"삼각형 $\\mathrm{ABC}$ 에서 $\\cos\\dfrac{\\pi}{3}$ 를 세 변 $3$, $1$, $4k$ 로 나타내면? $k>0$ 이므로 $k$ 는?","식":["$\\cos\\dfrac{\\pi}{3}=\\dfrac{3^2+1^2-(4k)^2}{2\\times3\\times1}=\\dfrac{1}{2}$","$10-16k^2=3,\\quad k^2=\\dfrac{7}{16}$","$k=\\dfrac{\\sqrt{7}}{4}$"],"설명":"$\\angle\\mathrm{BAC}$ 를 낀 두 변이 $3$, $1$ 이고 마주 보는 변이 $\\overline{\\mathrm{BC}}=4k$ 이다.","확인":null,"스킬":"S6"},{"제목":"삼각형 APC 에서 사인법칙으로 반지름 구하기","힌트":"$\\angle\\mathrm{PAC}$ 의 크기는? 삼각형 $\\mathrm{APC}$ 에서 변 $\\mathrm{PC}$ 와 그 마주 보는 각으로 사인법칙을 쓰면 $R$ 은?","식":["$\\angle\\mathrm{PAC}=\\dfrac{1}{2}\\times\\dfrac{\\pi}{3}=\\dfrac{\\pi}{6}$","$\\dfrac{\\overline{\\mathrm{PC}}}{\\sin\\frac{\\pi}{6}}=2R,\\quad 2R=2k$","$R=k=\\dfrac{\\sqrt{7}}{4}$"],"설명":"변 $\\mathrm{PC}$ 는 각 $\\mathrm{PAC}$ 의 맞은편 변이므로 $\\dfrac{\\overline{\\mathrm{PC}}}{\\sin\\angle\\mathrm{PAC}}$ 가 외접원의 지름과 같다.","확인":null,"스킬":"S6"},{"제목":"외접원의 넓이 구하기","힌트":"반지름이 $\\dfrac{\\sqrt{7}}{4}$ 인 원의 넓이는?","식":["$\\pi R^2=\\pi\\times\\dfrac{7}{16}=\\dfrac{7}{16}\\pi$"],"설명":"원의 넓이 $\\pi R^2$ 에 $R^2=\\dfrac{7}{16}$ 을 넣는다.","확인":null,"스킬":"S5"}]},"고2-202106-16":{"길":"두 삼각형이 밑변 CB 를 공유함을 이용해 높이의 비를 로그로 나타내고 log2 a 를 구한다","단계":[{"제목":"넓이의 비를 높이의 비로 바꾸기","힌트":"$\\mathrm{C}$ 와 $\\mathrm{B}$ 는 $y$ 좌표가 같다. 두 삼각형의 공통 밑변을 $\\overline{\\mathrm{CB}}$ 로 보면 높이는 각각 어느 선분의 길이인가? 직선 $x=k$ 와 $x$ 축의 교점을 $\\mathrm{E}$ 라 하면?","식":["$\\overline{\\mathrm{AB}}=\\overline{\\mathrm{AE}}-\\overline{\\mathrm{BE}}$,  $\\overline{\\mathrm{BE}}=\\log_ak$,  $\\overline{\\mathrm{AE}}=\\log_2k$","$\\dfrac{1}{2}\\times\\overline{\\mathrm{CB}}\\times\\overline{\\mathrm{AB}}:\\dfrac{1}{2}\\times\\overline{\\mathrm{CB}}\\times\\overline{\\mathrm{BE}}=3:2$","$\\overline{\\mathrm{AB}}:\\overline{\\mathrm{BE}}=3:2$"],"설명":"$\\overline{\\mathrm{CB}}$ 는 $x$ 축에 평행하고 $\\overline{\\mathrm{AB}}$ 는 $y$ 축에 평행하므로 삼각형 $\\mathrm{ACB}$ 의 높이는 $\\overline{\\mathrm{AB}}$ 이다. $\\mathrm{D}$ 는 $x$ 축 위의 점이므로 삼각형 $\\mathrm{BCD}$ 의 높이는 $\\mathrm{B}$ 의 $y$ 좌표인 $\\overline{\\mathrm{BE}}$ 이다.","확인":null,"스킬":"G10"},{"제목":"AE 와 BE 의 비를 로그로 나타내기","힌트":"$\\overline{\\mathrm{AB}}:\\overline{\\mathrm{BE}}=3:2$ 이면 $\\overline{\\mathrm{AE}}:\\overline{\\mathrm{BE}}$ 는? 이를 $\\log_2k$, $\\log_ak$ 로 쓰면?","식":["$\\overline{\\mathrm{AE}}:\\overline{\\mathrm{BE}}=5:2$","$\\log_2k:\\log_ak=5:2$,  $\\log_2k=\\dfrac{5}{2}\\log_ak$"],"설명":"$\\overline{\\mathrm{AE}}=\\overline{\\mathrm{AB}}+\\overline{\\mathrm{BE}}$ 이므로 비의 항을 더한다.","확인":null,"스킬":"G10"},{"제목":"밑 변환으로 log2 a 구하기","고비":true,"힌트":"$\\log_ak$ 를 밑이 $2$ 인 로그로 바꾸면? $\\log_2k$ 로 양변을 나누면 $\\log_2a$ 는?","식":["$\\log_ak=\\dfrac{\\log_2k}{\\log_2a}$","$\\log_2k=\\dfrac{5}{2}\\times\\dfrac{\\log_2k}{\\log_2a}$","$\\log_2a=\\dfrac{5}{2}$"],"설명":"$k>1$ 이므로 $\\log_2k\\ne0$ 이어서 양변을 $\\log_2k$ 로 나눌 수 있다.","확인":"5/2","스킬":"A9"},{"제목":"상수 a 의 값 구하기","힌트":"$\\log_2a=\\dfrac{5}{2}$ 를 지수 꼴로 바꾸면 $a$ 는?","식":["$a=2^{\\frac{5}{2}}=2^2\\times2^{\\frac{1}{2}}=4\\sqrt{2}$"],"설명":"로그를 지수 꼴로 바꾼다. $a>2$ 를 만족한다.","확인":null,"스킬":"A9"}]},"고2-202106-17":{"길":"각을 차례로 따라가 두 삼각형에 사인법칙을 쓰고 빈칸 식과 수를 구해 곱한다","단계":[{"제목":"(가) 를 구해 f(π/6) 구하기","힌트":"삼각형 $\\mathrm{ABD}$ 에서 $\\overline{\\mathrm{AB}}$ 의 맞은편 각은? 그 각의 사인이 (가) 이므로 $\\theta=\\dfrac{\\pi}{6}$ 일 때의 값은?","식":["$\\angle\\mathrm{DAB}=3\\theta-\\theta=2\\theta,\\quad \\angle\\mathrm{BDA}=\\pi-3\\theta$","$\\dfrac{\\overline{\\mathrm{AD}}}{\\sin\\theta}=\\dfrac{\\overline{\\mathrm{AB}}}{\\sin(\\pi-3\\theta)}$ 이므로 $f(\\theta)=\\sin(\\pi-3\\theta)$","$f\\left(\\dfrac{\\pi}{6}\\right)=\\sin\\left(\\pi-\\dfrac{\\pi}{2}\\right)=1$"],"설명":"사인법칙에서 변 $\\mathrm{AB}$ 는 각 $\\mathrm{BDA}$ 의 맞은편이므로 분모에 $\\sin(\\pi-3\\theta)$ 가 들어간다.","확인":"1","스킬":"S6"},{"제목":"삼각형 ADE 의 세 각 구하기","힌트":"$\\angle\\mathrm{EAD}$ 는 문제에서 어떤 각으로 주어졌는가? $\\angle\\mathrm{ADC}$ 는 $\\angle\\mathrm{BDA}$ 와 어떤 관계이며, 거기서 $\\angle\\mathrm{EDC}$ 를 빼면 $\\angle\\mathrm{ADE}$ 는?","식":["$\\angle\\mathrm{EAD}=\\angle\\mathrm{DAC}=\\theta$","$\\angle\\mathrm{ADC}=\\pi-(\\pi-3\\theta)=3\\theta,\\quad \\angle\\mathrm{ADE}=3\\theta-\\theta=2\\theta$","$\\angle\\mathrm{DEA}=\\pi-\\theta-2\\theta=\\pi-3\\theta$"],"설명":"점 $\\mathrm{D}$ 에서 직선 $\\mathrm{BC}$ 위의 두 각의 합은 $\\pi$ 이다. 삼각형의 세 내각의 합이 $\\pi$ 이다.","확인":null,"스킬":"S10"},{"제목":"사인법칙으로 DE 를 AD 로 나타내 p 구하기","고비":true,"힌트":"삼각형 $\\mathrm{ADE}$ 에서 $\\overline{\\mathrm{DE}}$ 와 $\\overline{\\mathrm{AD}}$ 에 사인법칙을 쓰면? $\\dfrac{\\sin\\theta}{\\sin(\\pi-3\\theta)}$ 는 앞에서 구한 $\\overline{\\mathrm{AD}}$ 의 식과 어떤 관계인가?","식":["$\\dfrac{\\overline{\\mathrm{DE}}}{\\sin\\theta}=\\dfrac{\\overline{\\mathrm{AD}}}{\\sin(\\pi-3\\theta)}$ 에서 $\\overline{\\mathrm{DE}}=\\dfrac{\\sin\\theta}{\\sin(\\pi-3\\theta)}\\times\\overline{\\mathrm{AD}}$","$\\overline{\\mathrm{AD}}=\\dfrac{3\\sin\\theta}{\\sin(\\pi-3\\theta)}$ 에서 $\\dfrac{\\sin\\theta}{\\sin(\\pi-3\\theta)}=\\dfrac{\\overline{\\mathrm{AD}}}{3}$","$\\overline{\\mathrm{DE}}=\\dfrac{1}{3}\\overline{\\mathrm{AD}}^{\\,2},\\quad p=\\dfrac{1}{3}$"],"설명":"삼각형 $\\mathrm{ADE}$ 의 $\\overline{\\mathrm{DE}}$ 는 각 $\\mathrm{EAD}=\\theta$ 의 맞은편이고 $\\overline{\\mathrm{AD}}$ 는 각 $\\mathrm{DEA}$ 의 맞은편이다. 사인의 비를 $\\overline{\\mathrm{AD}}$ 의 식으로 바꿔 $\\overline{\\mathrm{AD}}^{\\,2}$ 꼴로 만든다.","확인":"1/3","스킬":"S6"},{"제목":"넓이 식에서 g 를 구해 g(π/12) 구하기","힌트":"$S(\\theta)=\\dfrac{1}{2}\\times\\overline{\\mathrm{AD}}\\times\\overline{\\mathrm{DE}}\\times\\sin(\\angle\\mathrm{ADE})$ 에 $\\overline{\\mathrm{DE}}=\\dfrac{1}{3}\\overline{\\mathrm{AD}}^{\\,2}$ 를 넣으면 (다) 는? $\\theta=\\dfrac{\\pi}{12}$ 일 때의 값은?","식":["$S(\\theta)=\\dfrac{1}{2}\\times\\overline{\\mathrm{AD}}\\times\\dfrac{1}{3}\\overline{\\mathrm{AD}}^{\\,2}\\times\\sin2\\theta=\\dfrac{1}{6}\\overline{\\mathrm{AD}}^{\\,3}\\sin2\\theta$","$\\dfrac{1}{6}\\times27\\left(\\dfrac{\\sin\\theta}{\\sin3\\theta}\\right)^3\\sin2\\theta$ 이므로 $g(\\theta)=\\sin2\\theta$","$g\\left(\\dfrac{\\pi}{12}\\right)=\\sin\\dfrac{\\pi}{6}=\\dfrac{1}{2}$"],"설명":"$\\angle\\mathrm{ADE}=2\\theta$ 이고 $\\overline{\\mathrm{AD}}^{\\,3}=27\\left(\\dfrac{\\sin\\theta}{\\sin3\\theta}\\right)^3$ 이다. 남는 인수가 (다) 이다.","확인":"1/2","스킬":"S6"},{"제목":"세 값의 곱 구하기","힌트":"$p=\\dfrac{1}{3}$, $f\\left(\\dfrac{\\pi}{6}\\right)=1$, $g\\left(\\dfrac{\\pi}{12}\\right)=\\dfrac{1}{2}$ 를 곱하면?","식":["$p\\times f\\left(\\dfrac{\\pi}{6}\\right)\\times g\\left(\\dfrac{\\pi}{12}\\right)=\\dfrac{1}{3}\\times1\\times\\dfrac{1}{2}=\\dfrac{1}{6}$"],"설명":"세 값을 그대로 곱한다.","확인":"1/6","스킬":"S6"}]},"고2-202106-18":{"길":"접선의 길이로 세 변을 문자로 두고 넓이를 두 방식으로 나타내 같다고 놓는다","단계":[{"제목":"접선의 길이로 세 변 나타내기","힌트":"$\\mathrm{A}$ 에서 접점 $\\mathrm{E}$, $\\mathrm{F}$ 까지의 길이를 $a$ 라 하면 $\\overline{\\mathrm{AB}}$, $\\overline{\\mathrm{AC}}$, $\\overline{\\mathrm{BC}}$ 는 각각?","식":["$\\overline{\\mathrm{AE}}=\\overline{\\mathrm{AF}}=a$","$\\overline{\\mathrm{AB}}=12+a,\\quad \\overline{\\mathrm{AC}}=4+a,\\quad \\overline{\\mathrm{BC}}=12+4=16$"],"설명":"한 점에서 원에 그은 두 접선의 길이는 같다. $\\overline{\\mathrm{BE}}=\\overline{\\mathrm{BD}}=12$, $\\overline{\\mathrm{CF}}=\\overline{\\mathrm{CD}}=4$ 이다.","확인":null,"스킬":"S5"},{"제목":"각 C 의 크기 구하기","힌트":"내접원의 중심을 $\\mathrm{O}$ 라 하면 직각삼각형 $\\mathrm{ODC}$ 에서 $\\tan(\\angle\\mathrm{OCD})$ 는? $\\overline{\\mathrm{CO}}$ 는 $\\angle\\mathrm{ACB}$ 를 어떻게 나누는가?","식":["$\\tan(\\angle\\mathrm{OCD})=\\dfrac{\\overline{\\mathrm{OD}}}{\\overline{\\mathrm{DC}}}=\\dfrac{\\frac{4\\sqrt{3}}{3}}{4}=\\dfrac{\\sqrt{3}}{3}$","$\\angle\\mathrm{OCD}=\\dfrac{\\pi}{6},\\quad \\angle\\mathrm{ACB}=\\dfrac{\\pi}{3}$"],"설명":"$\\overline{\\mathrm{OD}}$ 는 반지름이고 접점에서 반지름은 접선에 수직이다. 내심 $\\mathrm{O}$ 는 각의 이등분선 위에 있으므로 $\\angle\\mathrm{ACB}$ 는 $\\angle\\mathrm{OCD}$ 의 두 배이다.","확인":null,"스킬":"S10"},{"제목":"넓이를 두 가지로 나타내 방정식 세우기","고비":true,"힌트":"삼각형 $\\mathrm{ABC}$ 의 넓이를 $\\overline{\\mathrm{BC}}$, $\\overline{\\mathrm{AC}}$ 와 $\\sin\\dfrac{\\pi}{3}$ 로 나타내면? 또 $\\mathrm{O}$ 에서 세 변까지의 거리가 반지름이므로 세 삼각형 $\\mathrm{OAB}$, $\\mathrm{OBC}$, $\\mathrm{OCA}$ 의 넓이의 합으로 나타내면?","식":["$\\triangle\\mathrm{ABC}=\\dfrac{1}{2}\\times16\\times(a+4)\\times\\sin\\dfrac{\\pi}{3}=4\\sqrt{3}(a+4)$","$\\triangle\\mathrm{ABC}=\\dfrac{1}{2}\\times\\dfrac{4\\sqrt{3}}{3}\\times\\{(a+12)+16+(a+4)\\}=\\dfrac{4\\sqrt{3}}{3}(a+16)$","$4\\sqrt{3}(a+4)=\\dfrac{4\\sqrt{3}}{3}(a+16)$"],"설명":"변 $\\mathrm{BC}$ 와 $\\mathrm{AC}$ 의 끼인각이 $\\angle\\mathrm{ACB}=\\dfrac{\\pi}{3}$ 이다. 세 삼각형은 높이가 모두 반지름이고 밑변이 세 변이다.","확인":null,"스킬":"S8"},{"제목":"a 의 값 구하기","힌트":"$3(a+4)=a+16$ 에서 $a$ 는?","식":["$3a+12=a+16$","$a=2$"],"설명":"양변에 $\\dfrac{3}{4\\sqrt{3}}$ 을 곱하면 $3(a+4)=a+16$ 이다.","확인":"2","스킬":"S8"},{"제목":"삼각형 ABC 의 둘레 구하기","힌트":"세 변의 길이를 구해 더하면?","식":["$\\overline{\\mathrm{AB}}=14,\\quad \\overline{\\mathrm{AC}}=6,\\quad \\overline{\\mathrm{BC}}=16$","$14+6+16=36$"],"설명":"$a=2$ 를 세 변의 식에 넣어 더한다. 둘레는 $2\\times(12+4+2)$ 와 같다.","확인":"36","스킬":"S5"}]},"고2-202106-19":{"길":"우변의 밑을 √2−1 로 맞춰 지수만 비교하되 밑이 1 보다 작은 것을 반영해 순서쌍을 센다","단계":[{"제목":"우변을 밑 √2−1 의 거듭제곱으로 바꾸기","힌트":"$\\left(\\sqrt{2}-1\\right)^2$ 을 전개하면 어떤 수가 되는가? 그러면 $\\left(3-2\\sqrt{2}\\right)^{5-n}$ 의 지수는 얼마가 되는가?","식":["$\\left(\\sqrt{2}-1\\right)^2=3-2\\sqrt{2}$","$\\left(3-2\\sqrt{2}\\right)^{5-n}=\\left(\\sqrt{2}-1\\right)^{2(5-n)}=\\left(\\sqrt{2}-1\\right)^{10-2n}$"],"설명":"$p=\\sqrt{2}-1$ 이라 하면 $p^2=3-2\\sqrt{2}$ 이다. 부등식은 $p^m\\ge p^{10-2n}$ 이 된다.","확인":null,"스킬":"A9"},{"제목":"밑이 1 보다 작음을 반영해 m 의 범위 구하기","고비":true,"힌트":"$0<p<1$ 이면 $p^m\\ge p^{10-2n}$ 에서 지수의 부등호 방향은 어떻게 되는가?","식":["$0<\\sqrt{2}-1<1$","$p^m\\ge p^{10-2n}\\ \\Longleftrightarrow\\ m\\le10-2n$"],"설명":"밑이 $0$ 과 $1$ 사이이면 지수함수가 감소하므로 지수를 비교할 때 부등호의 방향이 바뀐다.","확인":null,"스킬":"A9"},{"제목":"자연수 m 이 있기 위한 n 의 범위 구하기","힌트":"$m$ 은 자연수이므로 $1\\le m\\le10-2n$ 이 성립하려면 $10-2n$ 은 얼마 이상이어야 하는가? 이를 만족하는 자연수 $n$ 의 최댓값은?","식":["$1\\le m\\le10-2n$ 에서 $10-2n\\ge1$","$n\\le\\dfrac{9}{2}$ 이므로 $n=1,\\ 2,\\ 3,\\ 4$"],"설명":"$n\\ge5$ 이면 $10-2n\\le0$ 이라 조건을 만족하는 자연수 $m$ 이 없다.","확인":"4","스킬":"C2"},{"제목":"순서쌍의 개수 구하기","힌트":"$n=1,2,3,4$ 일 때 자연수 $m$ 은 각각 몇 개인가? 모두 더하면?","식":["$n=1:\\ 1\\le m\\le8$ 이므로 $8$ 개,  $n=2:\\ 6$ 개","$n=3:\\ 4$ 개,  $n=4:\\ 2$ 개","$8+6+4+2=20$"],"설명":"각 $n$ 에서 $m$ 은 $1$ 이상 $10-2n$ 이하의 자연수이므로 $10-2n$ 개이다.","확인":"20","스킬":"C2"}]},"고2-202106-20":{"길":"두 교점의 좌표로 f(n) 의 식을 세우고 보기마다 n 의 범위를 로그로 따져 참거짓을 가른다","단계":[{"제목":"교점 좌표로 f(n) 의 식을 세워 ㄱ 판별하기","힌트":"$y=1$ 과 $y=2^x-1$ 의 교점 $\\mathrm{A}$ 의 $x$ 좌표는? $y=1$ 과 $y=-\\left(1+\\log_2n\\right)x+7$ 의 교점 $\\mathrm{B}$ 의 $x$ 좌표는? $n=2$ 를 넣으면?","식":["$2^x-1=1$ 에서 $\\mathrm{A}(1,\\ 1)$","$-\\left(1+\\log_2n\\right)x+7=1$ 에서 $\\mathrm{B}\\left(\\dfrac{6}{1+\\log_2n},\\ 1\\right)$","$f(n)=\\left|\\dfrac{6}{1+\\log_2n}-1\\right|,\\quad f(2)=\\left|\\dfrac{6}{2}-1\\right|=2$ 이므로 ㄱ 참"],"설명":"두 점의 $y$ 좌표가 같으므로 거리는 $x$ 좌표의 차의 절댓값이다.","확인":null,"스킬":"G1"},{"제목":"f(n)≥1 인 n 의 범위로 ㄴ 판별하기","힌트":"$\\dfrac{6}{1+\\log_2n}>0$ 이므로 $f(n)\\ge1$ 이면 절댓값 안은 어느 부호인가? 그때 $1+\\log_2n$ 의 범위는?","식":["$f(n)\\ge1\\ \\Longleftrightarrow\\ \\dfrac{6}{1+\\log_2n}-1\\ge1$","$1+\\log_2n\\le3,\\quad \\log_2n\\le2,\\quad 1\\le n\\le4$","$n=1,\\ 2,\\ 3,\\ 4$ 이므로 $4$ 개이고 ㄴ 참"],"설명":"$\\dfrac{6}{1+\\log_2n}-1$ 은 $-1$ 보다 크므로 절댓값이 $1$ 이상이려면 $1$ 이상이어야 한다.","확인":null,"스킬":"C3"},{"제목":"ㄷ 의 조건을 f(n) 의 두 범위로 바꾸기","힌트":"$|f(n)-1|\\ge\\dfrac{2}{3}$ 를 풀면 $f(n)$ 은 어느 범위에 있는가? $f(n)\\ge0$ 임을 함께 쓰면?","식":["$f(n)-1\\ge\\dfrac{2}{3}$ 또는 $f(n)-1\\le-\\dfrac{2}{3}$","$f(n)\\ge\\dfrac{5}{3}$ 또는 $0\\le f(n)\\le\\dfrac{1}{3}$"],"설명":"절댓값 부등식을 두 경우로 나누고 $f(n)$ 이 절댓값이므로 $0$ 이상임을 쓴다.","확인":null,"스킬":"C2"},{"제목":"f(n)≥5/3 인 자연수 n 세기","힌트":"$\\dfrac{6}{1+\\log_2n}-1\\ge\\dfrac{5}{3}$ 에서 $\\log_2n$ 의 범위는? $2^{\\frac{5}{4}}$ 는 어느 두 자연수 사이인가? 이를 만족하는 $n$ 은 몇 개인가?","식":["$\\dfrac{6}{1+\\log_2n}\\ge\\dfrac{8}{3}$ 에서 $\\log_2n\\le\\dfrac{5}{4}$","$1\\le n\\le2^{\\frac{5}{4}},\\quad 2<2^{\\frac{5}{4}}<3$ 이므로 $n=1,\\ 2$"],"설명":"$f(n)\\ge\\dfrac{5}{3}$ 이면 절댓값 안이 $\\dfrac{5}{3}$ 이상이다. $2<2^{\\frac{5}{4}}<2^{\\frac{3}{2}}<3$ 이므로 자연수 $n$ 은 $1$, $2$ 의 $2$ 개이다.","확인":"2","스킬":"C2"},{"제목":"0≤f(n)≤1/3 인 자연수 n 의 범위 구하기","고비":true,"힌트":"$\\left|\\dfrac{6}{1+\\log_2n}-1\\right|\\le\\dfrac{1}{3}$ 에서 $\\dfrac{6}{1+\\log_2n}$ 의 범위는? 그때 $\\log_2n$ 의 범위는? 가장 작은 자연수 $n$ 은?","식":["$\\dfrac{2}{3}\\le\\dfrac{6}{1+\\log_2n}\\le\\dfrac{4}{3}$","$\\dfrac{9}{2}\\le1+\\log_2n\\le9$ 이므로 $\\dfrac{7}{2}\\le\\log_2n\\le8$","$2^{\\frac{7}{2}}\\le n\\le2^8,\\quad 11<2^{\\frac{7}{2}}<12$ 이므로 $n=12,\\ 13,\\ \\cdots,\\ 256$"],"설명":"각 변의 역수를 취하면 부등호 방향이 바뀐다. $2^{\\frac{7}{2}}=8\\sqrt{2}$ 는 $11$ 과 $12$ 사이의 수이다.","확인":"12","스킬":"C2"},{"제목":"ㄷ 의 개수를 합쳐 참거짓 판별하기","힌트":"두 범위의 $n$ 의 개수를 더하면 얼마인가? 보기 ㄷ 에 적힌 개수와 같은가?","식":["$n=1,\\ 2$ 의 $2$ 개와 $n=12,\\ 13,\\ \\cdots,\\ 256$ 의 $245$ 개","$2+245=247\\ne245$ 이므로 ㄷ 거짓","옳은 것은 ㄱ, ㄴ"],"설명":"$12$ 부터 $256$ 까지의 자연수는 $256-12+1=245$ 개이고 앞의 두 개를 더하면 $247$ 개이다.","확인":null,"스킬":"C3"}]},"고2-202106-21":{"길":"f 의 두 식이 역함수 관계임을 보고 k 의 범위를 잡아 a 마다 f(a), g(a) 사이의 정수 b 를 센다","단계":[{"제목":"일대일대응이 되는 k 의 뜻 읽기","힌트":"$y=2^{-x-2}-2$ 와 $y=-\\log_2(x+2)-2$ 는 어떤 직선에 대하여 대칭인가? $f$ 가 일대일대응이려면 $x=k$ 에서 두 식의 값이 어떠해야 하는가?","식":["$y=2^{-x-2}-2$ 의 역함수는 $y=-\\log_2(x+2)-2$ 이므로 두 곡선은 직선 $y=x$ 에 대하여 대칭","$f$ 가 일대일대응이면 $k$ 는 두 곡선의 교점의 $x$ 좌표"],"설명":"$f$ 는 두 곡선 중 $x<k$ 에서 앞 식, $x\\ge k$ 에서 뒤 식을 쓰는데 실수 전체에서 끊김 없이 이어진 감소함수가 되어야 하므로 $x=k$ 에서 두 식의 값이 같아야 한다.","확인":null,"스킬":"T7"},{"제목":"k 의 범위 구하기","고비":true,"힌트":"$y=-\\log_2(x+2)-2$ 가 $x$ 축과 만나는 점의 $x$ 좌표는? $k\\ge-1$ 이라 가정하면 $k=-\\log_2(k+2)-2$ 의 우변은 얼마 이하인가?","식":["$-\\log_2(x+2)-2=0$ 에서 $x=-\\dfrac{7}{4}$ 이므로 $k>-\\dfrac{7}{4}$","$k\\ge-1$ 이면 $k=-\\log_2(k+2)-2\\le-2$ 로 모순이므로 $k<-1$","$-\\dfrac{7}{4}<k<-1$"],"설명":"이 곡선은 감소하고 $x=-\\dfrac{7}{4}$ 에서 $y=0$ 이며 직선 $y=x$ 는 증가하므로 교점은 그보다 오른쪽에 있다. 또 $k\\ge-1$ 이면 $k+2\\ge1$ 이라 $-\\log_2(k+2)-2\\le-2$ 가 되어 $k\\ge-1$ 과 어긋난다.","확인":null,"스킬":"C2"},{"제목":"a 마다 f, g 의 어느 식을 쓰는지 정하기","힌트":"$-\\dfrac{7}{4}<k<-1$ 이면 $-k$ 는 어떤 두 수 사이에 있는가? $a=-2,\\ -1,\\ 0,\\ 1,\\ 2$ 는 $k$ 와 $-k$ 를 기준으로 어느 구간에 있는가?","식":["$1<-k<\\dfrac{7}{4}$ 이므로 $-2<k<-1<0<1<-k<2$","$a=-2$ 는 $x<k$ 구간, $a=-1,\\ 0,\\ 1$ 은 $k\\le x<-k$ 구간, $a=2$ 는 $-k\\le x\\le2$ 구간"],"설명":"$f$ 는 $x<k$ 와 $x\\ge k$ 에서, $g$ 는 $x<-k$ 와 $x\\ge-k$ 에서 식이 다르므로 정수 $a$ 가 어느 구간에 들어가는지 먼저 정한다.","확인":null,"스킬":"C2"},{"제목":"a=-2, 2 에서 정수 b 의 개수 구하기","힌트":"$a=-2$ 에서 $f(-2)=2^{-x-2}-2$ 의 값과 $g(-2)=\\log_2(2-x)+2$ 의 값은? $a=2$ 에서 $f(2)=-\\log_2(x+2)-2$ 와 $g(2)=-2^{x-2}+2$ 의 값은? 각각 $b$ 는 몇 개인가?","식":["$a=-2$: $f(-2)=2^{0}-2=-1,\\ g(-2)=\\log_24+2=4$ 이므로 $-1\\le b\\le4$, $6$ 개","$a=2$: $f(2)=-\\log_24-2=-4,\\ g(2)=-2^{0}+2=1$ 이므로 $-4\\le b\\le1$, $6$ 개","$6+6=12$"],"설명":"$f(a)\\le b\\le g(a)$ 를 만족시키는 정수 $b$ 는 두 값 사이의 정수이다.","확인":"12","스킬":"G6"},{"제목":"a=-1, 0, 1 에서 정수 b 의 개수 구하기","힌트":"이 세 값에서는 $f(x)=-\\log_2(x+2)-2$, $g(x)=\\log_2(2-x)+2$ 이다. 각 $a$ 에서 $f(a)$ 와 $g(a)$ 는? $\\log_23$ 은 $1$ 과 $2$ 사이인 점에 주의하면 $b$ 는 각각 몇 개인가?","식":["$a=-1$: $f(-1)=-2,\\ g(-1)=\\log_23+2\\ (3<g(-1)<4)$ 이므로 $-2\\le b\\le3$, $6$ 개","$a=0$: $f(0)=-3,\\ g(0)=3$ 이므로 $-3\\le b\\le3$, $7$ 개","$a=1$: $f(1)=-\\log_23-2\\ (-4<f(1)<-3),\\ g(1)=2$ 이므로 $-3\\le b\\le2$, $6$ 개"],"설명":"$\\log_23$ 은 $1$ 보다 크고 $2$ 보다 작으므로 $g(-1)$ 은 $3$ 과 $4$ 사이, $f(1)$ 은 $-4$ 와 $-3$ 사이이다. 그 사이에 있는 정수만 센다. 세 값을 더하면 $6+7+6=19$ 이다.","확인":"19","스킬":"G6"},{"제목":"순서쌍의 총 개수 구하기","힌트":"$a=-2,\\ 2$ 에서의 개수와 $a=-1,\\ 0,\\ 1$ 에서의 개수를 더하면?","식":["$12+19=31$"],"설명":"각 $a$ 마다 센 정수 $b$ 의 개수를 모두 더한다.","확인":"31","스킬":"G6"}]},"고2-202106-22":{"길":"밑이 같은 지수의 나눗셈은 지수끼리 뺀다","단계":[{"제목":"지수끼리 빼기","고비":true,"힌트":"$5^{\\frac{7}{3}}\\div5^{\\frac{1}{3}}$ 에서 밑이 같으면 지수는 어떻게 하는가? 지수 $\\dfrac{7}{3}-\\dfrac{1}{3}$ 은?","식":["$5^{\\frac{7}{3}}\\div5^{\\frac{1}{3}}=5^{\\frac{7}{3}-\\frac{1}{3}}$","$\\dfrac{7}{3}-\\dfrac{1}{3}=2$"],"설명":"$a^m\\div a^n=a^{m-n}$ 이다.","확인":"2","스킬":"A9"},{"제목":"값 구하기","힌트":"$5^2$ 은?","식":["$5^2=25$"],"설명":"지수가 $2$ 인 거듭제곱을 계산한다.","확인":"25","스킬":"A9"}]},"고2-202106-23":{"길":"로그 방정식을 지수 꼴로 바꾸어 x−2 의 값을 정한다","단계":[{"제목":"지수 꼴로 바꾸기","고비":true,"힌트":"$\\log_3(x-2)=1$ 은 $x-2$ 가 $3$ 의 몇 제곱이라는 뜻인가? $x-2$ 의 값은?","식":["$\\log_3(x-2)=1$ 에서 $x-2=3^1$","$x-2=3$"],"설명":"$\\log_a X=b$ 는 $X=a^b$ 과 같은 뜻이다.","확인":"3","스킬":"A9"},{"제목":"해 구하기","힌트":"$x-2=3$ 에서 $x$ 는?","식":["$x=5$"],"설명":"$x=5$ 이면 진수 $x-2=3>0$ 이므로 조건을 만족시킨다.","확인":"5","스킬":"A9"}]},"고2-202106-24":{"길":"tan 값을 sin 과 cos 의 비로 읽고 sin²+cos²=1 에 넣어 cos² 를 구한다","단계":[{"제목":"sin 을 cos 로 나타내기","힌트":"$\\tan\\theta=\\dfrac{\\sin\\theta}{\\cos\\theta}$ 이므로 $\\sin\\theta$ 는 $\\cos\\theta$ 의 몇 배인가?","식":["$\\dfrac{\\sin\\theta}{\\cos\\theta}=\\dfrac{1}{3}$","$\\sin\\theta=\\dfrac{\\cos\\theta}{3}$"],"설명":"$\\tan\\theta$ 는 $\\sin\\theta$ 를 $\\cos\\theta$ 로 나눈 값이다.","확인":null,"스킬":"T5"},{"제목":"cos² 의 값 구하기","고비":true,"힌트":"$\\sin^2\\theta+\\cos^2\\theta=1$ 에 $\\sin\\theta=\\dfrac{\\cos\\theta}{3}$ 를 넣으면 $\\cos^2\\theta$ 는?","식":["$\\left(\\dfrac{\\cos\\theta}{3}\\right)^2+\\cos^2\\theta=1$","$\\dfrac{10}{9}\\cos^2\\theta=1$","$\\cos^2\\theta=\\dfrac{9}{10}$"],"설명":"$\\sin^2\\theta=\\dfrac{\\cos^2\\theta}{9}$ 이므로 $\\cos^2\\theta$ 에 대한 일차식이 된다.","확인":"9/10","스킬":"T5"},{"제목":"50cos²θ 의 값 구하기","힌트":"$50\\times\\dfrac{9}{10}$ 는?","식":["$50\\cos^2\\theta=50\\times\\dfrac{9}{10}=45$"],"설명":"구한 $\\cos^2\\theta$ 에 $50$ 을 곱한다.","확인":"45","스킬":"T5"}]},"고2-202106-25":{"길":"지나는 점의 좌표를 식에 넣고 sin 의 값을 읽어 k 를 구한다","단계":[{"제목":"점의 좌표를 넣어 sin 의 값 읽기","힌트":"$x=\\dfrac{\\pi}{6}$, $y=2$ 를 넣으면 $\\sin$ 안의 각은? 그 사인의 값은?","식":["$2=2\\sin\\left(\\dfrac{\\pi}{6}-\\dfrac{\\pi}{3}\\right)+k=2\\sin\\left(-\\dfrac{\\pi}{6}\\right)+k$","$\\sin\\left(-\\dfrac{\\pi}{6}\\right)=-\\dfrac{1}{2}$"],"설명":"$\\sin(-\\theta)=-\\sin\\theta$ 이고 $\\sin\\dfrac{\\pi}{6}=\\dfrac{1}{2}$ 이다.","확인":"-1/2","스킬":"T5"},{"제목":"k 의 값 구하기","고비":true,"힌트":"$2=2\\times\\left(-\\dfrac{1}{2}\\right)+k$ 에서 $k$ 는?","식":["$2=-1+k$","$k=3$"],"설명":"$2\\times\\left(-\\dfrac{1}{2}\\right)=-1$ 을 이항한다.","확인":"3","스킬":"T5"}]},"고2-202106-26":{"길":"평행이동한 식을 쓰고 y=x 대칭은 역함수임을 이용해 f 를 구한 뒤 점을 대입한다","단계":[{"제목":"평행이동한 그래프의 식 쓰기","힌트":"$y=\\log_2x$ 를 $x$ 축의 방향으로 $m$ 만큼 평행이동하면 식은?","식":["$y=\\log_2(x-m)$"],"설명":"$x$ 축의 방향으로 $m$ 만큼 옮기면 $x$ 대신 $x-m$ 을 넣는다.","확인":null,"스킬":"G4"},{"제목":"y=x 대칭으로 f(x) 구하기","고비":true,"힌트":"직선 $y=x$ 에 대한 대칭이동은 $x$ 와 $y$ 를 바꾸는 것이다. $y=\\log_2(x-m)$ 에서 $x$ 와 $y$ 를 바꾸고 $y$ 에 대해 풀면?","식":["$x=\\log_2(y-m)$","$y-m=2^x$","$f(x)=2^x+m$"],"설명":"$y=x$ 에 대하여 대칭인 두 함수는 서로 역함수이다.","확인":null,"스킬":"T1"},{"제목":"점 (1, 5) 로 m 구하기","힌트":"$f(1)=5$ 에서 $m$ 은?","식":["$f(1)=2^1+m=5$","$m=3$"],"설명":"그래프가 지나는 점의 좌표를 $f(x)=2^x+m$ 에 넣는다.","확인":"3","스킬":"T1"},{"제목":"f(m) 의 값 구하기","힌트":"$f(x)=2^x+3$ 에서 $f(3)$ 은?","식":["$f(m)=f(3)=2^3+3=11$"],"설명":"$m=3$ 이므로 $f(3)$ 을 계산한다.","확인":"11","스킬":"T1"}]},"고2-202106-27":{"길":"세 로그를 k 의 배수로 나타내고 세 로그의 곱이 1 임을 이용해 k³ 을 구한다","단계":[{"제목":"세 로그를 k 로 나타내기","힌트":"$\\log_ab=k$ 이고 $\\dfrac{\\log_bc}{2}=k$, $\\dfrac{\\log_ca}{3}=k$ 에서 $\\log_bc$, $\\log_ca$ 는 각각?","식":["$\\log_ab=k,\\quad \\log_bc=2k,\\quad \\log_ca=3k$"],"설명":"세 비가 모두 $k$ 와 같다는 조건을 각각 로그의 값으로 풀어 쓴다.","확인":null,"스킬":"A8"},{"제목":"세 로그의 곱 구하기","고비":true,"힌트":"$\\log_ab\\times\\log_bc\\times\\log_ca$ 를 밑 변환 공식으로 하나의 로그로 묶으면 얼마인가?","식":["$\\log_ab\\times\\log_bc\\times\\log_ca=\\dfrac{\\log b}{\\log a}\\times\\dfrac{\\log c}{\\log b}\\times\\dfrac{\\log a}{\\log c}$","$=1$"],"설명":"밑 변환으로 분자와 분모가 차례로 약분된다. $a$, $b$, $c$ 가 모두 $1$ 보다 크므로 각 로그가 정의된다.","확인":"1","스킬":"A9"},{"제목":"k³ 의 값 구하기","힌트":"$k\\times2k\\times3k=1$ 에서 $k^3$ 은?","식":["$k\\times2k\\times3k=6k^3=1$","$k^3=\\dfrac{1}{6}$"],"설명":"앞의 세 식을 곱한 값 $6k^3$ 이 $1$ 과 같다.","확인":"1/6","스킬":"A8"},{"제목":"120k³ 의 값 구하기","힌트":"$120\\times\\dfrac{1}{6}$ 은?","식":["$120k^3=120\\times\\dfrac{1}{6}=20$"],"설명":"구한 $k^3$ 에 $120$ 을 곱한다.","확인":"20","스킬":"A8"}]},"고2-202106-28":{"길":"외분점을 곡선에 넣어 b 와 a 의 관계를 얻고 집합의 원소가 연속한 5 개 정수임을 이용해 a 의 범위를 정한다","단계":[{"제목":"외분점의 좌표 구하기","힌트":"선분 $\\mathrm{AB}$ 를 $2:1$ 로 외분하는 점의 좌표를 $a$, $\\log_4b$, $1$, $\\log_8\\sqrt[4]{27}$ 로 나타내면? $2\\log_8\\sqrt[4]{27}$ 은 밑이 $4$ 인 로그로 얼마인가?","식":["외분점 $\\left(\\dfrac{2\\times1-a}{2-1},\\ \\dfrac{2\\log_8\\sqrt[4]{27}-\\log_4b}{2-1}\\right)$","$2\\log_8\\sqrt[4]{27}=\\log_8\\sqrt{27}=\\dfrac{3}{2}\\log_83=\\dfrac{1}{2}\\log_23=\\log_43$","외분점 $\\left(2-a,\\ \\log_4\\dfrac{3}{b}\\right)$"],"설명":"$\\mathrm{A}(x_1,y_1)$, $\\mathrm{B}(x_2,y_2)$ 를 $m:n$ 으로 외분하는 점의 좌표는 $\\left(\\dfrac{mx_2-nx_1}{m-n},\\ \\dfrac{my_2-ny_1}{m-n}\\right)$ 이다.","확인":null,"스킬":"A9"},{"제목":"곡선 위의 점 조건으로 a, b 의 관계 구하기","힌트":"외분점의 $x$ 좌표 $2-a$ 를 $y=-\\log_4(3-x)$ 에 넣으면 $y$ 좌표는? 이것이 $\\log_4\\dfrac{3}{b}$ 와 같다고 놓으면?","식":["$y=-\\log_4\\{3-(2-a)\\}=-\\log_4(a+1)=\\log_4\\dfrac{1}{a+1}$","$\\log_4\\dfrac{3}{b}=\\log_4\\dfrac{1}{a+1}$ 에서 $\\dfrac{3}{b}=\\dfrac{1}{a+1}$","$b=3(a+1)$"],"설명":"외분점이 곡선 위에 있으므로 외분점의 좌표가 곡선의 식을 만족시킨다.","확인":null,"스킬":"A9"},{"제목":"집합의 원소의 개수 구하기","힌트":"$b<2^n\\times a\\le32b$ 의 각 변을 $a$ 로 나누고 $\\log_2$ 를 취하면 $n$ 의 범위는? 그 구간의 길이는? 조건을 만족시키는 정수 $n$ 은 몇 개인가?","식":["$\\dfrac{b}{a}<2^n\\le\\dfrac{32b}{a}$","$\\log_2\\dfrac{b}{a}<n\\le5+\\log_2\\dfrac{b}{a}$","구간의 길이가 $5$ 이고 왼쪽 끝이 열려 있으므로 정수 $n$ 은 $5$ 개"],"설명":"$a$ 는 자연수이므로 양수로 나누어도 부등호의 방향이 그대로이다. 길이가 $5$ 인 구간 $(L,\\ L+5]$ 에는 정수가 항상 $5$ 개 들어 있다.","확인":"5","스킬":"A9"},{"제목":"원소의 합이 25 가 되는 정수 n 구하기","힌트":"원소 $5$ 개가 연속한 정수이므로 가장 작은 원소를 $m$ 이라 하면 합은? 합이 $25$ 인 $m$ 은?","식":["$m+(m+1)+(m+2)+(m+3)+(m+4)=5m+10=25$","$m=3$ 이므로 $n=3,\\ 4,\\ 5,\\ 6,\\ 7$"],"설명":"원소가 모두 정수이고 구간 안에 연속해서 들어 있으므로 연속한 정수 $5$ 개이다.","확인":"3","스킬":"C7"},{"제목":"b/a 의 범위 구하기","고비":true,"힌트":"$n=2$ 는 원소가 아니고 $n=3$ 은 원소이다. 이 두 조건으로 $\\log_2\\dfrac{b}{a}$ 는 어떤 범위에 있는가? 그러면 $\\dfrac{b}{a}$ 는?","식":["$n=2$ 가 원소가 아니므로 $\\log_2\\dfrac{b}{a}\\ge2$, $n=3$ 이 원소이므로 $\\log_2\\dfrac{b}{a}<3$","$2\\le\\log_2\\dfrac{b}{a}<3$","$4\\le\\dfrac{b}{a}<8$"],"설명":"원소가 $n=3$ 부터 $n=7$ 까지이려면 구간의 왼쪽 끝 $\\log_2\\dfrac{b}{a}$ 가 $2$ 이상 $3$ 미만이어야 한다. $n=7$, $n=8$ 의 조건도 같은 범위를 준다.","확인":null,"스킬":"C9"},{"제목":"자연수 a 의 값 구하기","힌트":"$b=3(a+1)$ 을 $4\\le\\dfrac{b}{a}<8$ 에 넣으면 $a$ 의 범위는? 이를 만족시키는 자연수 $a$ 중 가장 큰 수는?","식":["$4\\le\\dfrac{3(a+1)}{a}<8$","$4a\\le3a+3$ 에서 $a\\le3$, $3a+3<8a$ 에서 $a>\\dfrac{3}{5}$","$a=1,\\ 2,\\ 3$"],"설명":"$a>0$ 이므로 각 변에 $a$ 를 곱해도 부등호의 방향이 그대로이다.","확인":"3","스킬":"C2"},{"제목":"a+b 의 최댓값 구하기","힌트":"$a=1,\\ 2,\\ 3$ 에서 $b=3(a+1)$ 은? $a+b$ 가 가장 큰 경우는?","식":["$(a,\\ b)=(1,\\ 6),\\ (2,\\ 9),\\ (3,\\ 12)$","$a+b=7,\\ 11,\\ 15$ 이므로 최댓값은 $15$"],"설명":"$a$ 가 커질수록 $b=3(a+1)$ 도 커지므로 $a=3$ 일 때 최대이다.","확인":"15","스킬":"C2"}]},"고2-202106-29":{"길":"넓이비로 BC 와 DC 의 비를 구하고 코사인법칙과 외접원의 사인법칙으로 길이를 정해 넓이를 더한다","단계":[{"제목":"삼각형 ABD 에서 BD 를 AB 로 나타내기","힌트":"$\\overline{\\mathrm{AB}}=a$ 라 하면 $\\overline{\\mathrm{DA}}=2a$ 이다. 삼각형 $\\mathrm{DAB}$ 에서 코사인법칙으로 $\\overline{\\mathrm{BD}}^2$ 을 구하면?","식":["$\\overline{\\mathrm{BD}}^2=a^2+(2a)^2-2\\times a\\times2a\\times\\cos\\dfrac{2}{3}\\pi$","$=5a^2+2a^2=7a^2$","$\\overline{\\mathrm{BD}}=\\sqrt{7}a$"],"설명":"$\\cos\\dfrac{2}{3}\\pi=-\\dfrac{1}{2}$ 이다.","확인":null,"스킬":"S6"},{"제목":"넓이비로 BC 와 DC 의 관계 구하기","고비":true,"힌트":"$\\mathrm{E}$ 가 $\\overline{\\mathrm{BD}}$ 를 $3:4$ 로 나누면 삼각형 $\\mathrm{ABC}$ 와 $\\mathrm{ADC}$ 의 넓이의 비는? 두 넓이를 $\\dfrac{1}{2}\\times$ 변 $\\times$ 변 $\\times\\sin$ 으로 쓰면? $\\angle\\mathrm{ABC}+\\angle\\mathrm{ADC}$ 는?","식":["$\\triangle\\mathrm{ABC}:\\triangle\\mathrm{ADC}=\\overline{\\mathrm{BE}}:\\overline{\\mathrm{ED}}=3:4$","$\\angle\\mathrm{ABC}=\\theta$ 이면 $\\angle\\mathrm{ADC}=\\pi-\\theta$ 이고 $\\sin(\\pi-\\theta)=\\sin\\theta$ 이므로 $\\overline{\\mathrm{BA}}\\times\\overline{\\mathrm{BC}}:\\overline{\\mathrm{DA}}\\times\\overline{\\mathrm{DC}}=3:4$","$a\\times\\overline{\\mathrm{BC}}:2a\\times\\overline{\\mathrm{DC}}=3:4$ 에서 $\\overline{\\mathrm{BC}}=\\dfrac{3}{2}\\overline{\\mathrm{DC}}$"],"설명":"두 삼각형은 밑변 $\\mathrm{AC}$ 를 공유하므로 넓이의 비는 높이의 비이고, 그 높이의 비가 $\\overline{\\mathrm{BE}}:\\overline{\\mathrm{ED}}$ 이다. 원에 내접하는 사각형에서 마주 보는 두 각의 합은 $\\pi$ 이다.","확인":null,"스킬":"S8"},{"제목":"삼각형 BCD 에서 코사인법칙으로 DC 구하기","힌트":"$\\angle\\mathrm{BCD}$ 의 크기는? $\\overline{\\mathrm{DC}}=k$ 라 하면 $\\overline{\\mathrm{BC}}=\\dfrac{3}{2}k$ 이다. 코사인법칙으로 $\\overline{\\mathrm{BD}}^2$ 을 $k$ 로 나타내고 $7a^2$ 과 같다고 놓으면 $k$ 는 $a$ 의 몇 배인가?","식":["$\\angle\\mathrm{BCD}=\\pi-\\dfrac{2}{3}\\pi=\\dfrac{\\pi}{3}$","$\\overline{\\mathrm{BD}}^2=\\left(\\dfrac{3k}{2}\\right)^2+k^2-2\\times\\dfrac{3k}{2}\\times k\\times\\cos\\dfrac{\\pi}{3}=\\dfrac{7}{4}k^2$","$\\dfrac{7}{4}k^2=7a^2$ 에서 $k=2a$, 즉 $\\overline{\\mathrm{DC}}=2a,\\ \\overline{\\mathrm{BC}}=3a$"],"설명":"사각형 $\\mathrm{ABCD}$ 가 원에 내접하므로 $\\angle\\mathrm{DAB}+\\angle\\mathrm{BCD}=\\pi$ 이다.","확인":"2","스킬":"S6"},{"제목":"외접원의 사인법칙으로 a² 구하기","힌트":"삼각형 $\\mathrm{DAB}$ 의 외접원의 반지름이 $1$ 이므로 $\\dfrac{\\overline{\\mathrm{BD}}}{\\sin\\frac{2}{3}\\pi}$ 는? $\\overline{\\mathrm{BD}}=\\sqrt{7}a$ 에서 $a^2$ 은?","식":["$\\dfrac{\\overline{\\mathrm{BD}}}{\\sin\\frac{2}{3}\\pi}=2\\times1$","$\\overline{\\mathrm{BD}}=2\\times\\dfrac{\\sqrt{3}}{2}=\\sqrt{3}$ 이므로 $\\sqrt{7}a=\\sqrt{3}$","$a^2=\\dfrac{3}{7}$"],"설명":"삼각형 $\\mathrm{DAB}$ 의 외접원이 주어진 원이다. 사인법칙에서 한 변을 그 대각의 사인으로 나눈 값이 외접원의 지름과 같다.","확인":"3/7","스킬":"S5"},{"제목":"사각형 ABCD 의 넓이 구하기","힌트":"대각선 $\\mathrm{BD}$ 로 나눈 두 삼각형 $\\mathrm{ABD}$, $\\mathrm{BCD}$ 의 넓이를 $a^2$ 으로 나타내 더하면? 넓이를 $\\dfrac{q}{p}\\sqrt{3}$ 꼴로 쓰면 $\\dfrac{q}{p}$ 는?","식":["$\\triangle\\mathrm{ABD}=\\dfrac{1}{2}\\times a\\times2a\\times\\sin\\dfrac{2}{3}\\pi=\\dfrac{\\sqrt{3}}{2}a^2$","$\\triangle\\mathrm{BCD}=\\dfrac{1}{2}\\times3a\\times2a\\times\\sin\\dfrac{\\pi}{3}=\\dfrac{3\\sqrt{3}}{2}a^2$","$\\square\\mathrm{ABCD}=2\\sqrt{3}a^2=2\\sqrt{3}\\times\\dfrac{3}{7}=\\dfrac{6}{7}\\sqrt{3}$"],"설명":"사각형의 넓이는 두 삼각형의 넓이의 합이다.","확인":"6/7","스킬":"S12"},{"제목":"p+q 의 값 구하기","힌트":"$\\dfrac{q}{p}=\\dfrac{6}{7}$ 이고 $p$, $q$ 는 서로소인 자연수이다. $p+q$ 는?","식":["$p=7,\\ q=6$","$p+q=13$"],"설명":"$6$ 과 $7$ 은 서로소이므로 기약분수 그대로 읽는다.","확인":"13","스킬":"S12"}]},"고2-202106-30":{"길":"합성함수를 정리해 (가) 로 a, b 의 홀짝을 정하고 (나) 의 근의 합을 경우 나누어 a=14 를 찾는다","단계":[{"제목":"합성함수의 식과 (h∘g)(3/2) 정리하기","힌트":"$(f\\circ h)(x)=\\cos\\pi(ax+b)$ 는 $b$ 가 짝수일 때와 홀수일 때 각각 어떻게 간단해지는가? $(h\\circ g)\\left(\\dfrac{3}{2}\\right)$ 의 값은?","식":["$(f\\circ h)(x)=\\cos(a\\pi x+b\\pi)$ 이고 $b$ 가 짝수이면 $\\cos a\\pi x$, 홀수이면 $-\\cos a\\pi x$","$(h\\circ g)\\left(\\dfrac{3}{2}\\right)=a\\sin\\dfrac{3}{2}\\pi+b=-a+b$"],"설명":"$\\cos(\\theta+b\\pi)$ 는 $b$ 가 짝수이면 $\\cos\\theta$, 홀수이면 $-\\cos\\theta$ 이다. $\\sin\\dfrac{3}{2}\\pi=-1$ 이다.","확인":null,"스킬":"T5"},{"제목":"그래프와 직선 y=c 의 교점 개수 세기","힌트":"$y=\\cos a\\pi x$ 의 주기는? $0\\le x\\le4$ 에 주기가 몇 번 들어가는가? 직선 $y=c$ 가 $c=1$, $0$, $-1$ 일 때 교점은 각각 몇 개인가?","식":["$y=\\cos a\\pi x$ 의 주기는 $\\dfrac{2}{a}$ 이므로 $0\\le x\\le4$ 에 $2a$ 번 반복","$y=\\cos a\\pi x$ 와 $y=c$: $c=1$ 이면 $2a+1$ 개, $c=0$ 이면 $4a$ 개, $c=-1$ 이면 $2a$ 개","$y=-\\cos a\\pi x$ 와 $y=c$: $c=1$ 이면 $2a$ 개, $c=0$ 이면 $4a$ 개, $c=-1$ 이면 $2a+1$ 개"],"설명":"$x=0$ 과 $x=4$ 에서 모두 $\\cos a\\pi x=1$ 이므로 $y=1$ 과는 양 끝점이 더해져 한 개 더 많다. 그래프를 뒤집으면 $c=1$ 과 $c=-1$ 일 때의 개수가 서로 바뀐다.","확인":null,"스킬":"T2"},{"제목":"(가) 로 −a+b 와 a, b 의 홀짝 정하기","힌트":"$-a+b$ 는 정수이고 $\\cos$ 의 값은 $-1$ 이상 $1$ 이하이므로 근이 있으려면 $-a+b$ 는 어떤 값인가? 근의 개수가 홀수이려면 $b$ 가 짝수일 때와 홀수일 때 $-a+b$ 는 각각 얼마여야 하는가?","식":["근이 있으려면 $-a+b=-1,\\ 0,\\ 1$","$b$ 짝수: 홀수 개는 $-a+b=1$ 일 때뿐이므로 $b=a+1$ 이고 $a$ 는 홀수","$b$ 홀수: 홀수 개는 $-a+b=-1$ 일 때뿐이므로 $b=a-1$ 이고 $a$ 는 짝수"],"설명":"$b=a+1$ 에서 $b$ 가 짝수이면 $a$ 는 홀수이다. $b=a-1$ 에서 $b$ 가 홀수이면 $a$ 는 짝수이다.","확인":null,"스킬":"C2"},{"제목":"a 홀수, b=a+1 일 때 근의 합 따져 보기","힌트":"$(h\\circ g)(t)=a(\\sin\\pi t+1)+1$ 은 어떤 값 이상인가? 방정식이 근을 가지려면 그 값은 얼마인가? 근이 $x=2$ 에 대칭이면 근의 합은 (개수)$\\times2$ 이다. $a$ 는?","식":["$(h\\circ g)(t)=a(\\sin\\pi t+1)+1\\ge1$ 이므로 근이 있으려면 $\\cos a\\pi x=1$","근은 $2a+1$ 개이고 $x=2$ 에 대칭이므로 합은 $(2a+1)\\times2=4a+2$","$4a+2=56$ 에서 $a=\\dfrac{27}{2}$ 로 자연수가 아니다"],"설명":"$\\cos a\\pi x$ 는 $x=2$ 에 대하여 대칭이다. 이 경우는 조건을 만족시키는 $a$ 가 없다.","확인":"27/2","스킬":"T2"},{"제목":"a 짝수, b=a−1 일 때 근의 합으로 a, b 구하기","고비":true,"힌트":"$(h\\circ g)(t)=a(\\sin\\pi t+1)-1$ 은 어떤 값 이상인가? $-\\cos a\\pi x=c$ 에서 $c=-1$, $-1<c<1$, $c=1$ 인 세 경우 근의 개수와 합은? 합이 $56$ 이 되는 짝수 $a$ 는?","식":["$c=-1$: $2a+1$ 개, 합 $4a+2=56$ 에서 자연수 $a$ 가 없다","$-1<c<1$: $4a$ 개, 합 $8a=56$ 에서 $a=7$ 이나 $a$ 는 짝수이므로 불가","$c=1$: $2a$ 개, 합 $4a=56$ 에서 $a=14,\\ b=a-1=13$"],"설명":"$-\\cos a\\pi x$ 도 $x=2$ 에 대하여 대칭이므로 근의 합은 (개수)$\\times2$ 이다. $c$ 는 $-1$ 이상이고 $c>1$ 이면 근이 없다.","확인":"14","스킬":"C2"},{"제목":"sin πt 와 cos²πt 구하기","힌트":"$c=1$ 이므로 $14\\sin\\pi t+13=1$ 에서 $\\sin\\pi t$ 는? $\\cos^2\\pi t$ 는?","식":["$14\\sin\\pi t+13=1$ 에서 $\\sin\\pi t=-\\dfrac{6}{7}$","$\\cos^2\\pi t=1-\\dfrac{36}{49}=\\dfrac{13}{49}$"],"설명":"$c=1$ 인 경우가 합 $56$ 을 만드는 유일한 경우이므로 $(h\\circ g)(t)=1$ 이다.","확인":"13/49","스킬":"T5"},{"제목":"구하는 값 계산하기","힌트":"$\\dfrac{a\\times b}{\\cos^2\\pi t}$ 에 $a=14$, $b=13$, $\\cos^2\\pi t=\\dfrac{13}{49}$ 를 넣으면?","식":["$\\dfrac{14\\times13}{\\frac{13}{49}}=14\\times13\\times\\dfrac{49}{13}=686$"],"설명":"분모의 $\\dfrac{13}{49}$ 은 역수를 곱한다.","확인":"686","스킬":"T5"}]},"고2-202109-04":{"길":"등비중항의 성질로 두 항의 곱을 가운데 항의 제곱으로 바꾼다","단계":[{"제목":"두 항의 곱을 가운데 항의 제곱으로 나타내기","고비":true,"힌트":"등비수열에서 $a_4$ 와 $a_6$ 은 $a_5$ 와 공비 $r$ 로 어떻게 나타내는가? 곱 $a_4\\times a_6$ 은?","식":["$a_4=\\dfrac{a_5}{r},\\quad a_6=a_5r$","$a_4\\times a_6=a_5^{\\,2}=64$"],"설명":"$a_5$ 는 $a_4$ 와 $a_6$ 의 등비중항이다.","확인":null,"스킬":"A2"},{"제목":"a₅ 의 값 구하기","힌트":"$a_5^{\\,2}=64$ 이고 모든 항이 양수이면 $a_5$ 는?","식":["$a_5^{\\,2}=64$","$a_5=8$"],"설명":"모든 항이 양수이므로 $a_5=-8$ 은 버린다.","확인":"8","스킬":"A2"}]},"고2-202109-06":{"길":"tan 를 sin 과 cos 의 비로 바꿔 sin 값을 구하고 sin²+cos²=1 로 cos 를 구한다","단계":[{"제목":"곱을 sin 으로 바꾸기","힌트":"$\\tan\\theta=\\dfrac{\\sin\\theta}{\\cos\\theta}$ 를 $\\cos\\theta\\times\\tan\\theta$ 에 넣으면 무엇이 남는가?","식":["$\\cos\\theta\\times\\tan\\theta=\\cos\\theta\\times\\dfrac{\\sin\\theta}{\\cos\\theta}=\\sin\\theta$","$\\sin\\theta=\\dfrac{3}{5}$"],"설명":"$\\cos\\theta$ 가 약분되어 $\\sin\\theta$ 만 남는다.","확인":null,"스킬":"T5"},{"제목":"cos 의 값 구하기","고비":true,"힌트":"$\\sin^2\\theta+\\cos^2\\theta=1$ 에서 $\\cos^2\\theta$ 는? $0<\\theta<\\dfrac{\\pi}{2}$ 이면 $\\cos\\theta$ 의 부호는?","식":["$\\cos^2\\theta=1-\\sin^2\\theta=1-\\dfrac{9}{25}=\\dfrac{16}{25}$","$\\cos\\theta=\\dfrac{4}{5}$"],"설명":"$0<\\theta<\\dfrac{\\pi}{2}$ 에서 $\\cos\\theta>0$ 이므로 양수인 쪽을 택한다.","확인":"4/5","스킬":"T5"}]},"고2-202109-07":{"길":"첫째항 a 와 공차 d 로 두 조건을 식으로 쓰고 연립해 a₄ 를 구한다","단계":[{"제목":"두 조건을 a, d 의 식으로 쓰기","힌트":"첫째항을 $a$, 공차를 $d$ 라 하면 $a_3$, $a_6$, $a_8$ 은 각각 $a$ 와 $d$ 로 어떻게 나타내는가?","식":["$a_3+a_6=(a+2d)+(a+5d)=2a+7d=25$","$a_8=a+7d=23$"],"설명":"등차수열의 제 $n$ 항은 $a+(n-1)d$ 이다.","확인":null,"스킬":"P1"},{"제목":"연립해 a, d 구하기","고비":true,"힌트":"두 식을 변끼리 빼면 $a$ 는? 그때 공차 $d$ 는?","식":["$(2a+7d)-(a+7d)=25-23$ 에서 $a=2$","$2+7d=23$ 에서 $d=3$"],"설명":"$7d$ 가 같으므로 빼면 $d$ 가 소거된다.","확인":"3","스킬":"A10"},{"제목":"a₄ 의 값 구하기","힌트":"$a_4=a+3d$ 에 $a=2$, $d=3$ 을 넣으면?","식":["$a_4=a+3d=2+3\\times3=11$"],"설명":"제 $4$ 항은 첫째항에 공차를 $3$ 번 더한 값이다.","확인":"11","스킬":"P1"}]},"고2-202109-08":{"길":"평행이동한 식에서 점근선으로 n 을 읽고 지나는 점으로 m 을 구한다","단계":[{"제목":"평행이동한 식과 점근선으로 n 읽기","고비":true,"힌트":"$y=3^x$ 을 $x$ 축의 방향으로 $m$, $y$ 축의 방향으로 $n$ 만큼 옮긴 식은? 이 그래프의 점근선은 어떤 직선인가?","식":["$y=3^{x-m}+n$","점근선 $y=n$ 이 $y=2$ 이므로 $n=2$"],"설명":"$y=3^x$ 의 점근선은 $y=0$ 이고 $y$ 축의 방향으로 $n$ 만큼 옮기면 $y=n$ 이 된다.","확인":null,"스킬":"G4"},{"제목":"점 (7, 5) 로 m 구하기","힌트":"$y=3^{x-m}+2$ 에 $x=7$, $y=5$ 를 넣으면 $3^{7-m}$ 은? $m$ 은?","식":["$5=3^{7-m}+2$","$3^{7-m}=3$ 에서 $7-m=1$","$m=6$"],"설명":"밑이 같으므로 지수끼리 같다고 놓는다.","확인":"6","스킬":"A9"},{"제목":"m+n 의 값 구하기","힌트":"$m=6$, $n=2$ 를 더하면?","식":["$m+n=6+2=8$"],"설명":"구한 두 상수를 더한다.","확인":"8","스킬":"G4"}]},"고2-202109-09":{"길":"두 변과 끼인각으로 넓이를 sin θ 로 쓰고 sin θ 의 범위로 θ 의 구간을 구한다","단계":[{"제목":"넓이 조건을 sin θ 의 부등식으로 바꾸기","힌트":"두 변의 길이 $2$, $2$ 와 끼인각 $\\theta$ 로 삼각형 $\\mathrm{ABC}$ 의 넓이를 쓰면? 넓이가 $1$ 보다 크면 $\\sin\\theta$ 는 어떤 수보다 큰가?","식":["$\\triangle\\mathrm{ABC}=\\dfrac{1}{2}\\times2\\times2\\times\\sin\\theta=2\\sin\\theta$","$2\\sin\\theta>1$ 에서 $\\sin\\theta>\\dfrac{1}{2}$"],"설명":"넓이는 두 변의 길이의 곱의 절반에 끼인각의 사인을 곱한 값이다.","확인":"1/2","스킬":"S6"},{"제목":"θ 의 범위 α, β 구하기","고비":true,"힌트":"$0<\\theta<\\pi$ 에서 $y=\\sin\\theta$ 와 $y=\\dfrac{1}{2}$ 의 교점의 $\\theta$ 좌표는? $\\sin\\theta>\\dfrac{1}{2}$ 인 구간은?","식":["$\\sin\\theta=\\dfrac{1}{2}$ 에서 $\\theta=\\dfrac{\\pi}{6}$ 또는 $\\dfrac{5}{6}\\pi$","$\\dfrac{\\pi}{6}<\\theta<\\dfrac{5}{6}\\pi$ 이므로 $\\alpha=\\dfrac{\\pi}{6},\\ \\beta=\\dfrac{5}{6}\\pi$"],"설명":"$y=\\sin\\theta$ 의 그래프가 직선 $y=\\dfrac{1}{2}$ 보다 위에 있는 구간이 두 교점 사이이다.","확인":null,"스킬":"T5"},{"제목":"2α+β 의 값 구하기","힌트":"$\\alpha=\\dfrac{\\pi}{6}$, $\\beta=\\dfrac{5}{6}\\pi$ 를 넣으면?","식":["$2\\alpha+\\beta=2\\times\\dfrac{\\pi}{6}+\\dfrac{5}{6}\\pi=\\dfrac{7}{6}\\pi$"],"설명":"$2\\alpha=\\dfrac{2}{6}\\pi$ 와 $\\dfrac{5}{6}\\pi$ 를 더한다.","확인":null,"스킬":"T5"}]},"고2-202109-10":{"길":"교점의 좌표로 두 점 사이 거리의 제곱을 구해 부분분수로 쪼개고 연이어 소거한다","단계":[{"제목":"교점의 좌표와 {f(n)}² 구하기","힌트":"$x^2=\\sqrt{n}\\,x$ 의 해는? 두 교점의 좌표로 거리의 제곱 $\\{f(n)\\}^2$ 을 구하면?","식":["$x^2=\\sqrt{n}\\,x$ 에서 $x(x-\\sqrt{n})=0$ 이므로 교점 $(0,\\ 0)$, $\\left(\\sqrt{n},\\ n\\right)$","$\\{f(n)\\}^2=\\left(\\sqrt{n}-0\\right)^2+(n-0)^2=n+n^2=n(n+1)$"],"설명":"두 점 사이의 거리의 제곱은 $x$ 좌표의 차의 제곱과 $y$ 좌표의 차의 제곱의 합이다.","확인":null,"스킬":"G1"},{"제목":"부분분수로 쪼개기","고비":true,"힌트":"분모가 연속한 두 자연수의 곱인 $\\dfrac{1}{n(n+1)}$ 은 어떤 두 분수의 차로 나타낼 수 있는가?","식":["$\\dfrac{1}{n(n+1)}=\\dfrac{1}{n}-\\dfrac{1}{n+1}$"],"설명":"$\\dfrac{1}{n}-\\dfrac{1}{n+1}=\\dfrac{(n+1)-n}{n(n+1)}=\\dfrac{1}{n(n+1)}$ 이다.","확인":null,"스킬":"P6"},{"제목":"합을 차례로 소거해 구하기","힌트":"$n=1$ 부터 $10$ 까지 $\\left(\\dfrac{1}{n}-\\dfrac{1}{n+1}\\right)$ 을 더하면 어떤 항만 남는가?","식":["$\\left(1-\\dfrac{1}{2}\\right)+\\left(\\dfrac{1}{2}-\\dfrac{1}{3}\\right)+\\cdots+\\left(\\dfrac{1}{10}-\\dfrac{1}{11}\\right)$","$=1-\\dfrac{1}{11}=\\dfrac{10}{11}$"],"설명":"이웃한 항이 서로 지워져 처음 항 $1$ 과 마지막 항 $-\\dfrac{1}{11}$ 만 남는다.","확인":"10/11","스킬":"P6"}]},"고2-202109-11":{"길":"두 점근선으로 세 꼭짓점의 좌표를 정하고 밑변 AB 와 높이로 넓이를 p 에 대한 식으로 쓴다","단계":[{"제목":"점근선으로 세 점의 좌표 정하기","힌트":"$f(x)=\\log_2(x-p)$ 의 점근선과 $g(x)=2^x+1$ 의 점근선은? 점 $\\mathrm{A}$, $\\mathrm{B}$ 는 직선 $x=p$ 위, 점 $\\mathrm{C}$ 는 직선 $y=1$ 위이다. 세 점의 좌표는?","식":["$f$ 의 점근선은 $x=p$, $g$ 의 점근선은 $y=1$","$\\mathrm{A}\\left(p,\\ 2^p+1\\right),\\quad \\mathrm{B}(p,\\ 0)$","$\\log_2(x-p)=1$ 에서 $x=p+2$ 이므로 $\\mathrm{C}(p+2,\\ 1)$"],"설명":"$\\mathrm{A}$ 는 $y=g(x)$ 위의 점이므로 $x=p$ 를 대입하고 $\\mathrm{B}$ 는 $x$ 축 위의 점이다. $\\mathrm{C}$ 는 $y=f(x)$ 에 $y=1$ 을 넣어 구한다.","확인":null,"스킬":"T4"},{"제목":"넓이를 p 로 나타내 2^p 구하기","고비":true,"힌트":"$\\overline{\\mathrm{AB}}$ 를 밑변으로 보면 밑변의 길이는? 점 $\\mathrm{C}$ 에서 직선 $x=p$ 까지의 거리인 높이는? 넓이가 $6$ 이면 $2^p$ 은?","식":["$\\overline{\\mathrm{AB}}=2^p+1$, 높이 $=(p+2)-p=2$","$\\triangle\\mathrm{ABC}=\\dfrac{1}{2}\\times\\left(2^p+1\\right)\\times2=2^p+1=6$","$2^p=5$"],"설명":"$\\overline{\\mathrm{AB}}$ 가 $y$ 축에 평행하므로 높이는 $\\mathrm{C}$ 의 $x$ 좌표와 $p$ 의 차이다.","확인":"5","스킬":"G10"},{"제목":"p 의 값 구하기","힌트":"$2^p=5$ 를 로그로 나타내면 $p$ 는?","식":["$p=\\log_25$"],"설명":"$a^x=b$ 이면 $x=\\log_ab$ 이다.","확인":null,"스킬":"A9"}]},"고2-202109-12":{"길":"a₈ 에서 거꾸로 n 의 홀짝에 맞는 식을 골라 a₇, a₆ 을 차례로 구한다","단계":[{"제목":"a₇ 구하기","고비":true,"힌트":"$a_8$ 은 $n=7$ 일 때의 식으로 정해진다. $7$ 은 홀수인가 짝수인가? 그 식에서 $a_7$ 은?","식":["$n=7$ (홀수) 이므로 $a_8=\\log_2a_7=5$","$a_7=2^5=32$"],"설명":"$a_{n+1}$ 을 만드는 식은 $n$ 의 홀짝으로 정해지므로 $a_8$ 에는 $n=7$ 의 식을 쓴다.","확인":"32","스킬":"C5"},{"제목":"a₆ 구하기","힌트":"$a_7$ 은 $n=6$ 일 때의 식으로 정해진다. $6$ 은 홀수인가 짝수인가? 그 식에 $a_7=32$ 를 넣으면 $a_6$ 은?","식":["$n=6$ (짝수) 이므로 $a_7=2^{a_6+1}=32=2^5$","$a_6+1=5$ 에서 $a_6=4$"],"설명":"밑이 같으므로 지수끼리 같다고 놓는다.","확인":"4","스킬":"C5"},{"제목":"a₆+a₇ 의 값 구하기","힌트":"$a_6=4$, $a_7=32$ 를 더하면?","식":["$a_6+a_7=4+32=36$"],"설명":"구한 두 항을 더한다.","확인":"36","스킬":"C5"}]},"고2-202109-13":{"길":"동경이 일치하면 두 각의 차가 2π 의 정수배임을 식으로 쓰고 범위로 θ 를 정해 부채꼴의 넓이를 구한다","단계":[{"제목":"동경이 일치하는 조건을 식으로 쓰기","고비":true,"힌트":"각 $\\theta$ 와 $8\\theta$ 의 동경이 일치하면 두 각의 차는 $2\\pi$ 의 몇 배인가? 이를 $\\theta$ 에 대해 풀면?","식":["$8\\theta-\\theta=2n\\pi\\ (n$ 은 정수$)$","$\\theta=\\dfrac{2n}{7}\\pi$"],"설명":"동경이 같은 두 각은 $2\\pi$ 의 정수배만큼 차이가 난다.","확인":null,"스킬":"T5"},{"제목":"범위로 정수 n 구하기","힌트":"$0<\\dfrac{2n}{7}\\pi<\\dfrac{\\pi}{2}$ 에서 $n$ 의 범위는? 이를 만족시키는 정수 $n$ 은?","식":["$0<\\dfrac{2n}{7}\\pi<\\dfrac{\\pi}{2}$ 에서 $0<n<\\dfrac{7}{4}$","$n=1$ 이므로 $\\theta=\\dfrac{2}{7}\\pi$"],"설명":"정수 $n$ 이 $0$ 보다 크고 $\\dfrac{7}{4}$ 보다 작아야 하므로 $1$ 뿐이다.","확인":"1","스킬":"T5"},{"제목":"부채꼴의 넓이 구하기","힌트":"반지름 $2$, 중심각 $\\dfrac{2}{7}\\pi$ 인 부채꼴의 넓이 $\\dfrac{1}{2}r^2\\theta$ 는?","식":["$\\dfrac{1}{2}\\times2^2\\times\\dfrac{2}{7}\\pi=\\dfrac{4}{7}\\pi$"],"설명":"부채꼴의 넓이는 $\\dfrac{1}{2}r^2\\theta$ 이다.","확인":null,"스킬":"T5"}]},"고2-202109-14":{"길":"진수의 최대·최소 위치를 구간에서 정하고 로그의 합을 하나로 묶어 k 를 구한다","단계":[{"제목":"구간에서 진수의 최댓값과 최솟값 정하기","고비":true,"힌트":"$x^2-6x+k$ 를 $(x-3)^2$ 꼴로 고치면? $0\\le x\\le5$ 에서 꼭짓점 $x=3$ 에서 가장 먼 끝은 어느 쪽인가? 밑이 $3$ 이므로 $f$ 가 최대, 최소일 때 진수는?","식":["$x^2-6x+k=(x-3)^2+k-9$","진수의 최솟값은 $x=3$ 일 때 $k-9$, 최댓값은 $x=0$ 일 때 $k$","$f$ 의 최솟값 $\\log_3(k-9)$, 최댓값 $\\log_3k$"],"설명":"$k>9$ 이므로 진수가 양수이다. 밑 $3$ 이 $1$ 보다 커서 진수가 클수록 $f$ 도 크다. $x=0$ 이 $x=5$ 보다 $x=3$ 에서 더 멀어 진수가 더 크다.","확인":null,"스킬":"T3"},{"제목":"최대·최소의 합으로 방정식 세우기","힌트":"$\\log_3k+\\log_3(k-9)=2+\\log_34$ 의 양변을 $\\log_3$ 하나로 묶으면? $k(k-9)$ 는 얼마인가?","식":["$\\log_3k(k-9)=2+\\log_34=\\log_39+\\log_34=\\log_336$","$k(k-9)=36$"],"설명":"$2=\\log_39$ 이다. 로그의 합은 진수의 곱으로 묶는다.","확인":"36","스킬":"A9"},{"제목":"k 의 값 구하기","힌트":"$k^2-9k-36=0$ 을 인수분해하고 $k>9$ 인 해를 택하면?","식":["$k^2-9k-36=(k-12)(k+3)=0$","$k>9$ 이므로 $k=12$"],"설명":"$k=-3$ 은 $k>9$ 를 만족시키지 않는다.","확인":"12","스킬":"C2"}]},"고2-202109-15":{"길":"n 의 홀짝과 (2n−5)(2n−9) 의 부호로 실수인 n 제곱근의 개수를 정해 n=2 부터 8 까지 더한다","단계":[{"제목":"실수인 n제곱근의 개수 규칙 세우기","고비":true,"힌트":"$n$ 이 홀수이면 실수인 $n$제곱근은 몇 개인가? $n$ 이 짝수이면 근호 안의 수가 양수, $0$, 음수일 때 각각 몇 개인가?","식":["$n$ 홀수: 실수인 $n$제곱근은 $1$ 개이므로 $f(n)=1$","$n$ 짝수: $(2n-5)(2n-9)>0$ 이면 $\\pm\\sqrt[n]{(2n-5)(2n-9)}$ 의 $2$ 개, $<0$ 이면 $0$ 개"],"설명":"홀수 제곱근은 부호가 같은 실수가 하나 있고, 짝수 제곱근은 양수의 경우 부호가 다른 두 실수가 있으며 음수의 경우 실수가 없다.","확인":null,"스킬":"C2"},{"제목":"짝수 n 에서 f(n) 의 합 구하기","힌트":"$n=2,4,6,8$ 에서 $(2n-5)(2n-9)$ 의 값의 부호는? $f(n)$ 의 합은?","식":["$n=2$: $(-1)\\times(-5)=5>0$, $n=4$: $3\\times(-1)=-3<0$","$n=6$: $7\\times3=21>0$, $n=8$: $11\\times7=77>0$","$f(2)=2,\\ f(4)=0,\\ f(6)=2,\\ f(8)=2$ 이므로 합 $6$"],"설명":"$\\dfrac{5}{2}<n<\\dfrac{9}{2}$ 인 짝수 $n=4$ 에서만 값이 음수이다.","확인":"6","스킬":"C2"},{"제목":"홀수 n 을 더해 전체 합 구하기","힌트":"$n=3,5,7$ 에서 $f(n)$ 은 각각? 앞의 합 $6$ 과 더하면?","식":["$f(3)=f(5)=f(7)=1$","$\\displaystyle\\sum_{n=2}^{8}f(n)=6+3=9$"],"설명":"홀수 $n$ 에서는 근호 안의 부호와 관계없이 실수인 $n$제곱근이 $1$ 개이다.","확인":"9","스킬":"C2"}]},"고2-202109-16":{"길":"n=1 과 n=m+1 의 식 변형 과정에서 빈칸 (가) (나) (다) 를 차례로 맞추고 값을 계산한다","단계":[{"제목":"n=1 에서 (가) 구하기","힌트":"$n=1$ 일 때 우변 $\\dfrac{1\\times2}{4}\\left(2a_2-1\\right)$ 을 $a_2-\\boxed{\\text{(가)}}$ 꼴로 정리하면?","식":["$\\dfrac{1\\times2}{4}\\left(2a_2-1\\right)=\\dfrac{1}{2}\\left(2a_2-1\\right)=a_2-\\dfrac{1}{2}$","(가) $=\\dfrac{1}{2}$ 이므로 $p=\\dfrac{1}{2}$"],"설명":"분배법칙으로 $\\dfrac{1}{2}$ 을 곱해 $a_2$ 와 상수항으로 나눈다.","확인":"1/2","스킬":"C6"},{"제목":"(나) 구하기","힌트":"$\\dfrac{m(m+1)}{4}\\left(2a_{m+1}-1\\right)+(m+1)a_{m+1}$ 에서 $a_{m+1}$ 이 들어 있는 항을 $(m+1)a_{m+1}\\left(\\boxed{\\text{(나)}}+1\\right)$ 로 묶으면 (나) 는? $f(5)$ 는?","식":["$\\dfrac{m(m+1)}{4}\\times2a_{m+1}=(m+1)a_{m+1}\\times\\dfrac{m}{2}$","$=(m+1)a_{m+1}\\left(\\dfrac{m}{2}+1\\right)-\\dfrac{m(m+1)}{4}$","$f(m)=\\dfrac{m}{2},\\quad f(5)=\\dfrac{5}{2}$"],"설명":"$a_{m+1}$ 이 든 두 항에서 $(m+1)a_{m+1}$ 을 공통인수로 묶는다.","확인":"5/2","스킬":"C6"},{"제목":"(다) 구하기","고비":true,"힌트":"$a_{m+2}$ 와 $a_{m+1}$ 의 차는 $a_n=\\displaystyle\\sum_{k=1}^{n}\\dfrac{1}{k}$ 에서 얼마인가? $\\dfrac{(m+1)(m+2)}{2}a_{m+1}$ 을 $a_{m+2}$ 로 바꾸면 (다) 는? $g(3)$ 은?","식":["$a_{m+2}=a_{m+1}+\\dfrac{1}{m+2}$ 이므로 $a_{m+1}=a_{m+2}-\\dfrac{1}{m+2}$","$\\dfrac{(m+1)(m+2)}{2}a_{m+1}=\\dfrac{(m+1)(m+2)}{2}\\left(a_{m+2}-\\dfrac{1}{m+2}\\right)$","$g(m)=\\dfrac{1}{m+2},\\quad g(3)=\\dfrac{1}{5}$"],"설명":"$a_n$ 은 $\\dfrac{1}{k}$ 의 $n$ 항까지의 합이므로 한 항 더 더하면 $\\dfrac{1}{n+1}$ 이 늘어난다.","확인":"1/5","스킬":"P1"},{"제목":"p+f(5)/g(3) 의 값 구하기","힌트":"$p=\\dfrac{1}{2}$, $f(5)=\\dfrac{5}{2}$, $g(3)=\\dfrac{1}{5}$ 를 넣으면?","식":["$p+\\dfrac{f(5)}{g(3)}=\\dfrac{1}{2}+\\dfrac{\\frac{5}{2}}{\\frac{1}{5}}=\\dfrac{1}{2}+\\dfrac{25}{2}=13$"],"설명":"분수로 나누는 것은 역수를 곱하는 것과 같아 $\\dfrac{5}{2}\\times5=\\dfrac{25}{2}$ 이다.","확인":"13","스킬":"C6"}]},"고2-202109-17":{"길":"한 주기 안의 두 교점이 사인 그래프의 대칭축에 대칭임을 이용해 x_n 을 구하고 합을 더한다","단계":[{"제목":"주기와 교점의 개수 파악하기","힌트":"$y=2\\sin\\left(\\dfrac{\\pi}{2^n}x\\right)$ 의 주기는? $0\\le x\\le2^{n+1}$ 은 몇 주기인가? $0<\\dfrac{1}{n}<2$ 이면 직선 $y=\\dfrac{1}{n}$ 과 몇 점에서 만나는가?","식":["주기 $\\dfrac{2\\pi}{\\frac{\\pi}{2^n}}=2^{n+1}$ 이므로 $0\\le x\\le2^{n+1}$ 은 정확히 한 주기","최댓값 $2$, 최솟값 $-2$ 이고 $0<\\dfrac{1}{n}<2$ 이므로 서로 다른 두 점에서 만난다"],"설명":"한 주기 안에서 최솟값과 최댓값 사이의 값을 가지는 수평선은 두 번 만난다. 두 교점의 $x$ 좌표를 $\\alpha_n$, $\\beta_n$ 이라 한다.","확인":null,"스킬":"T2"},{"제목":"대칭으로 x_n 구하기","고비":true,"힌트":"$y=2\\sin\\left(\\dfrac{\\pi}{2^n}x\\right)$ 는 최댓값을 갖는 $x$ 값에 대하여 대칭이다. 그 $x$ 값은 주기의 몇 분의 일인가? 그러면 $\\alpha_n+\\beta_n$ 은?","식":["최댓값은 $x=\\dfrac{1}{4}\\times2^{n+1}=2^{n-1}$ 에서 가지므로 그래프는 $x=2^{n-1}$ 에 대칭","$\\alpha_n+\\beta_n=2\\times2^{n-1}$ 이므로 $\\beta_n=2^n-\\alpha_n$","$x_n=\\alpha_n+\\beta_n=2^n$"],"설명":"$\\sin$ 그래프는 한 주기의 $\\dfrac{1}{4}$ 지점에서 최대가 되고 그 지점을 기준으로 좌우가 대칭이다. 대칭인 두 점의 $x$ 좌표의 합은 대칭축의 $x$ 좌표의 $2$ 배이다.","확인":null,"스킬":"T2"},{"제목":"x_n 의 합 구하기","힌트":"$x_n=2^n$ 을 $n=1$ 부터 $6$ 까지 더하면?","식":["$\\displaystyle\\sum_{n=1}^{6}x_n=2+4+8+16+32+64$","$=\\dfrac{2\\left(2^6-1\\right)}{2-1}=126$"],"설명":"첫째항 $2$, 공비 $2$ 인 등비수열의 첫째항부터 제 $6$ 항까지의 합이다.","확인":"126","스킬":"T2"}]},"고2-202109-18":{"길":"앞의 항을 나열해 6 항마다 되풀이됨을 찾고 2021 을 6 으로 나눈 나머지 번째 항으로 바꾼다","단계":[{"제목":"앞의 항 나열하기","힌트":"$a_{n+1}=a_n+b_n$, $b_{n+1}=2\\cos\\dfrac{a_n}{3}\\pi$ 에 $(a_1,\\ b_1)=(1,\\ -1)$ 부터 차례로 넣어 $(a_7,\\ b_7)$ 까지 구하면? $b_5$ 는?","식":["$(a_2,\\ b_2)=(0,\\ 1),\\ (a_3,\\ b_3)=(1,\\ 2),\\ (a_4,\\ b_4)=(3,\\ 1)$","$(a_5,\\ b_5)=(4,\\ -2),\\ (a_6,\\ b_6)=(2,\\ -1),\\ (a_7,\\ b_7)=(1,\\ -1)$"],"설명":"$b_2=2\\cos\\dfrac{\\pi}{3}=1,\\ b_3=2\\cos0=2,\\ b_5=2\\cos\\pi=-2,\\ b_6=2\\cos\\dfrac{4}{3}\\pi=-1,\\ b_7=2\\cos\\dfrac{2}{3}\\pi=-1$ 이다.","확인":"-2","스킬":"P7"},{"제목":"되풀이되는 간격 찾기","힌트":"$(a_7,\\ b_7)$ 은 $(a_1,\\ b_1)$ 과 같은가? 같다면 그 뒤의 값은 어떻게 이어지는가?","식":["$(a_7,\\ b_7)=(a_1,\\ b_1)=(1,\\ -1)$","$a_{n+6}=a_n,\\quad b_{n+6}=b_n$"],"설명":"다음 항이 바로 앞 항 $a_n$ 과 $b_n$ 만으로 정해지므로 한 번 같은 쌍이 나오면 그 뒤도 같은 순서로 반복된다.","확인":null,"스킬":"P7"},{"제목":"2021 을 6 으로 나눈 나머지 구하기","고비":true,"힌트":"$2021=6\\times336+r$ 에서 $r$ 은? $a_{2021}$, $b_{2021}$ 은 $a_r$, $b_r$ 과 같은가?","식":["$2021=6\\times336+5$","$a_{2021}=a_5,\\quad b_{2021}=b_5$"],"설명":"$6$ 항마다 같은 값이 되풀이되므로 나머지가 $5$ 이면 제 $5$ 항과 같다.","확인":"5","스킬":"P7"},{"제목":"a₂₀₂₁−b₂₀₂₁ 의 값 구하기","힌트":"$a_5=4$, $b_5=-2$ 이면 $a_5-b_5$ 는?","식":["$a_{2021}-b_{2021}=a_5-b_5=4-(-2)=6$"],"설명":"나열한 값에서 $a_5=4$, $b_5=-2$ 를 읽어 뺀다.","확인":"6","스킬":"P7"}]},"고2-202109-19":{"길":"sin θ 와 cos θ 로 PA 를 구하고 점 P 를 꼭짓점으로 하는 세 삼각형의 넓이로 삼각형 ADC 를 쪼갠다","단계":[{"제목":"sin θ, cos θ 구하기","힌트":"$4\\sin\\theta=3\\cos\\theta$ 에서 $\\cos\\theta$ 를 $\\sin\\theta$ 로 나타내고 $\\sin^2\\theta+\\cos^2\\theta=1$ 에 넣으면 $\\sin\\theta$ 는? $\\theta$ 는 직각삼각형의 예각이다.","식":["$\\cos\\theta=\\dfrac{4}{3}\\sin\\theta$ 이므로 $\\sin^2\\theta+\\dfrac{16}{9}\\sin^2\\theta=1$","$\\sin^2\\theta=\\dfrac{9}{25}$","$\\sin\\theta=\\dfrac{3}{5},\\quad \\cos\\theta=\\dfrac{4}{5}$"],"설명":"$\\mathrm{AB}$ 가 지름이므로 $\\angle\\mathrm{APB}=\\dfrac{\\pi}{2}$ 이고 $\\theta$ 는 직각삼각형 $\\mathrm{APB}$ 의 예각이라 $\\sin\\theta>0$, $\\cos\\theta>0$ 이다.","확인":"3/5","스킬":"T5"},{"제목":"PA, PC, PD 의 길이 구하기","힌트":"삼각형 $\\mathrm{APB}$ 는 $\\angle\\mathrm{APB}=\\dfrac{\\pi}{2}$ 이고 빗변이 $\\overline{\\mathrm{AB}}=10$ 이다. $\\overline{\\mathrm{PA}}$ 는? $\\overline{\\mathrm{PC}}$, $\\overline{\\mathrm{PD}}$ 는?","식":["$\\overline{\\mathrm{PA}}=\\overline{\\mathrm{AB}}\\cos\\theta=10\\times\\dfrac{4}{5}=8$","$\\overline{\\mathrm{PA}}=\\overline{\\mathrm{PC}}=\\overline{\\mathrm{PD}}=8$"],"설명":"직각삼각형에서 $\\theta$ 에 이웃한 변은 빗변과 $\\cos\\theta$ 의 곱이다.","확인":"8","스킬":"S6"},{"제목":"점 P 에서의 세 각 구하기","고비":true,"힌트":"$\\overline{\\mathrm{OA}}=\\overline{\\mathrm{OP}}$ 이므로 $\\angle\\mathrm{APO}$ 는? 점 $\\mathrm{D}$ 는 반직선 $\\mathrm{PO}$ 위, 점 $\\mathrm{C}$ 는 반직선 $\\mathrm{PB}$ 위에 있다. $\\angle\\mathrm{APD}$, $\\angle\\mathrm{DPC}$, $\\angle\\mathrm{APC}$ 는 각각?","식":["$\\angle\\mathrm{APD}=\\angle\\mathrm{APO}=\\angle\\mathrm{OAP}=\\theta$","$\\angle\\mathrm{DPC}=\\angle\\mathrm{OPB}=\\dfrac{\\pi}{2}-\\theta$","$\\angle\\mathrm{APC}=\\angle\\mathrm{APB}=\\dfrac{\\pi}{2}$"],"설명":"이등변삼각형 $\\mathrm{OAP}$ 의 밑각이 $\\theta$ 이다. 점 $\\mathrm{D}$, $\\mathrm{C}$ 가 각각 반직선 $\\mathrm{PO}$, $\\mathrm{PB}$ 위에 있으므로 각의 크기가 그대로 이어진다.","확인":null,"스킬":"S10"},{"제목":"세 삼각형의 넓이로 삼각형 ADC 의 넓이 구하기","힌트":"사각형 $\\mathrm{PADC}$ 를 대각선 $\\mathrm{PD}$ 로 나눈 넓이에서 대각선 $\\mathrm{AC}$ 로 나눌 때의 삼각형 $\\mathrm{PAC}$ 의 넓이를 빼면 삼각형 $\\mathrm{ADC}$ 이다. 세 넓이를 $\\dfrac{1}{2}\\times8\\times8\\times\\sin$ 으로 쓰면?","식":["$\\triangle\\mathrm{PAD}=\\dfrac{1}{2}\\times8\\times8\\times\\sin\\theta=32\\times\\dfrac{3}{5},\\quad \\triangle\\mathrm{PDC}=\\dfrac{1}{2}\\times8\\times8\\times\\sin\\left(\\dfrac{\\pi}{2}-\\theta\\right)=32\\times\\dfrac{4}{5}$","$\\triangle\\mathrm{PAC}=\\dfrac{1}{2}\\times8\\times8=32$","$\\triangle\\mathrm{ADC}=\\triangle\\mathrm{PAD}+\\triangle\\mathrm{PDC}-\\triangle\\mathrm{PAC}=\\dfrac{96}{5}+\\dfrac{128}{5}-32=\\dfrac{64}{5}$"],"설명":"사각형 $\\mathrm{PADC}$ 의 넓이는 $\\triangle\\mathrm{PAD}+\\triangle\\mathrm{PDC}$ 이고 $\\triangle\\mathrm{ADC}+\\triangle\\mathrm{PAC}$ 이기도 하다. $\\sin\\left(\\dfrac{\\pi}{2}-\\theta\\right)=\\cos\\theta$ 이다.","확인":"64/5","스킬":"S12"}]},"고2-202109-20":{"길":"기울기와 길이로 변화량을 잡고 합동으로 C 까지 이어 ㄱ ㄴ ㄷ 을 차례로 가린다","단계":[{"제목":"ㄱ 판정: 두 점의 변화량 구하기","힌트":"점 $\\mathrm{B}$ 에서 $x$ 축에 내린 수선의 발을 $\\mathrm{P}$, 점 $\\mathrm{A}$ 에서 선분 $\\mathrm{BP}$ 에 내린 수선의 발을 $\\mathrm{Q}$ 라 하자. 기울기가 $\\dfrac{1}{3}$ 이면 $y_2-y_1$ 은 $x_2-x_1$ 의 몇 배인가? $\\overline{\\mathrm{AB}}=\\sqrt{10}$ 에서 $x_2-x_1$ 과 $y_2-y_1$ 은?","식":["$y_2-y_1=\\dfrac{1}{3}\\left(x_2-x_1\\right)$","$\\overline{\\mathrm{AB}}^{\\,2}=\\left(x_2-x_1\\right)^2+\\dfrac{1}{9}\\left(x_2-x_1\\right)^2=10$ 이므로 $\\left(x_2-x_1\\right)^2=9$","$x_2>x_1$ 이므로 $x_2-x_1=3,\\ y_2-y_1=1$ 이고 ㄱ 은 참"],"설명":"직각삼각형 $\\mathrm{AQB}$ 에서 $\\overline{\\mathrm{AQ}}=x_2-x_1$, $\\overline{\\mathrm{BQ}}=y_2-y_1$ 이므로 피타고라스 정리를 쓴다.","확인":"1","스킬":"G9"},{"제목":"삼각형 ABQ 와 BCR 의 합동 찾기","힌트":"점 $\\mathrm{C}$ 에서 선분 $\\mathrm{BP}$ 에 내린 수선의 발을 $\\mathrm{R}$ 이라 하자. $\\angle\\mathrm{ABQ}$ 와 $\\angle\\mathrm{BCR}$ 은 어떤 관계인가? $\\overline{\\mathrm{AB}}=\\overline{\\mathrm{BC}}$ 이므로 두 삼각형은 합동인가? 합동이면 $\\overline{\\mathrm{BR}}$, $\\overline{\\mathrm{CR}}$ 는?","식":["$\\angle\\mathrm{ABQ}+\\angle\\mathrm{CBR}=\\angle\\mathrm{BCR}+\\angle\\mathrm{CBR}=\\dfrac{\\pi}{2}$ 이므로 $\\angle\\mathrm{ABQ}=\\angle\\mathrm{BCR}$","$\\angle\\mathrm{AQB}=\\angle\\mathrm{BRC}=\\dfrac{\\pi}{2}$, $\\overline{\\mathrm{AB}}=\\overline{\\mathrm{BC}}$ 이므로 $\\triangle\\mathrm{ABQ}\\equiv\\triangle\\mathrm{BCR}$","$\\overline{\\mathrm{AQ}}=\\overline{\\mathrm{BR}}=3,\\ \\overline{\\mathrm{BQ}}=\\overline{\\mathrm{CR}}=1$"],"설명":"$\\overline{\\mathrm{BC}}\\perp l$ 이므로 점 $\\mathrm{B}$ 에서 세 각 $\\angle\\mathrm{ABQ}$, $\\angle\\mathrm{ABC}$, $\\angle\\mathrm{CBR}$ 의 합이 $\\pi$ 이다. 두 직각삼각형은 빗변과 한 예각이 같아 합동이고, 대응하는 변의 길이도 같다.","확인":null,"스킬":"S10","고비":true},{"제목":"ㄴ 판정: x₃−x₁ 과 y₁−y₃ 구하기","힌트":"$x_3-x_1$ 은 $\\overline{\\mathrm{AQ}}$ 와 $\\overline{\\mathrm{CR}}$ 로, $y_1-y_3$ 은 $\\overline{\\mathrm{BR}}$ 와 $\\overline{\\mathrm{BQ}}$ 로 어떻게 나타내는가?","식":["$x_3-x_1=\\overline{\\mathrm{AQ}}+\\overline{\\mathrm{CR}}=3+1=4$","$y_1-y_3=\\overline{\\mathrm{QR}}=\\overline{\\mathrm{BR}}-\\overline{\\mathrm{BQ}}=3-1=2$","$x_3-x_1=2\\left(y_1-y_3\\right)=4$ 이므로 ㄴ 은 참"],"설명":"$\\mathrm{A}$ 와 $\\mathrm{Q}$ 의 $y$ 좌표가 같고 $\\mathrm{C}$ 와 $\\mathrm{R}$ 의 $y$ 좌표가 같으므로 $y_1-y_3$ 은 선분 $\\mathrm{QR}$ 의 길이이다.","확인":"4","스킬":"C3"},{"제목":"ㄷ 판정: x₁ 구하기","힌트":"$\\mathrm{A}$, $\\mathrm{B}$ 는 곡선 $y=\\log_4 ax$ 위의 점이다. 좌표를 $\\mathrm{A}\\left(x_1,\\ y_1\\right)$, $\\mathrm{B}\\left(x_1+3,\\ y_1+1\\right)$ 로 쓰고 두 식을 빼면 $x_1$ 은?","식":["$y_1=\\log_4 ax_1,\\quad y_1+1=\\log_4 a\\left(x_1+3\\right)$","$1=\\log_4\\dfrac{x_1+3}{x_1}$ 이므로 $\\dfrac{x_1+3}{x_1}=4$","$x_1=1$"],"설명":"두 식의 차에서 $\\log_4 a$ 가 사라져 $x_1$ 만 남는다.","확인":"1","스킬":"A9"},{"제목":"ㄷ 판정: a 와 b 의 관계 구하기","힌트":"$\\mathrm{A}$ 는 곡선 $y=b\\times\\left(\\dfrac{1}{3}\\right)^x$ 위에도 있다. $x_1=1$ 일 때 $y_1$ 을 $\\log_4 a$ 와 $b$ 로 각각 쓰면? $a^2$ 은 $4^b$ 와 같은가?","식":["$y_1=\\log_4 a$ 이고 $y_1=b\\times\\dfrac{1}{3}=\\dfrac{b}{3}$ 이므로 $a=4^{\\frac{b}{3}}$","$a^2=4^{\\frac{2b}{3}}$ 이고 $b>0$ 이므로 $4^{\\frac{2b}{3}}\\ne4^b$, ㄷ 은 거짓","옳은 것은 ㄱ, ㄴ"],"설명":"밑이 같은 지수의 지수가 다르면 값도 다르다. 따라서 보기 중 ㄱ 과 ㄴ 만 옳다.","확인":null,"스킬":"C3"}]},"고2-202109-21":{"길":"S_n 을 n 의 이차식으로 쓰고 b 가 짝수일 때를 제외한 뒤 |S_n| 의 최솟값 조건으로 b 의 범위를 구한다","단계":[{"제목":"합 S_n 을 n 의 식으로 나타내기","힌트":"첫째항 $b$, 공차 $-4$ 인 등차수열의 첫째항부터 제 $n$ 항까지의 합 $S_n$ 을 $n$ 과 $b$ 로 나타내면?","식":["$S_n=\\dfrac{n\\left\\{2b+(n-1)\\times(-4)\\right\\}}{2}=n\\left(b+2-2n\\right)$","$S_n=-2n\\left(n-\\dfrac{b+2}{2}\\right)$"],"설명":"등차수열의 합 공식 $S_n=\\dfrac{n\\{2a+(n-1)d\\}}{2}$ 에 $a=b$, $d=-4$ 를 넣는다. $S_n$ 은 $n$ 에 대한 위로 볼록한 이차식이다.","확인":null,"스킬":"C6"},{"제목":"b 가 짝수인 경우 제외하기","힌트":"$b$ 가 짝수이면 $\\dfrac{b+2}{2}$ 는 자연수이다. 이 $n$ 에서 $S_n$ 은?","식":["$n=\\dfrac{b+2}{2}$ 이면 $S_n=0$","$\\left|S_n\\right|\\ge14$ 에 어긋나므로 $b$ 는 홀수"],"설명":"$S_n=0$ 이 되는 자연수 $n$ 이 있으면 모든 $n$ 에서 $\\left|S_n\\right|\\ge14$ 일 수 없다.","확인":null,"스킬":"C2"},{"제목":"b 가 홀수일 때 |S_n| 의 최솟값 구하기","힌트":"$S_n=0$ 이 되는 $n=\\dfrac{b+2}{2}$ 는 자연수가 아니다. $\\left|S_n\\right|$ 이 가장 작은 자연수 $n$ 은 이 값에 가장 가까운 두 수이다. 그 두 $n$ 에서 $S_n$ 은?","식":["$n=\\dfrac{b+1}{2}$ 일 때 $S_n=-2\\times\\dfrac{b+1}{2}\\times\\left(-\\dfrac{1}{2}\\right)=\\dfrac{b+1}{2}$","$n=\\dfrac{b+3}{2}$ 일 때 $S_n=-2\\times\\dfrac{b+3}{2}\\times\\dfrac{1}{2}=-\\dfrac{b+3}{2}$","$\\left|S_n\\right|$ 의 최솟값은 $\\dfrac{b+1}{2}$"],"설명":"그래프 $y=-2x\\left(x-\\dfrac{b+2}{2}\\right)$ 가 $x=\\dfrac{b+2}{2}$ 에서 $x$ 축과 만나므로 이 값에서 가까운 정수일수록 $\\left|S_n\\right|$ 이 작다.","확인":null,"스킬":"T3","고비":true},{"제목":"b 의 범위 구하기","힌트":"$\\left|S_n\\right|$ 의 최솟값 $\\dfrac{b+1}{2}$ 이 $14$ 이상이려면 $b$ 의 가장 작은 홀수 값은?","식":["$\\dfrac{b+1}{2}\\ge14$ 에서 $b\\ge27$","$b$ 는 홀수이므로 $b=27,\\ 29,\\ 31,\\ \\cdots$"],"설명":"$\\left|S_n\\right|$ 의 최솟값이 $14$ 이상이면 모든 $n$ 에서 $\\left|S_n\\right|\\ge14$ 이다.","확인":"27","스킬":"C1"},{"제목":"b_m 의 합 구하기","힌트":"$b_m$ 은 첫째항 $27$, 공차 $2$ 인 등차수열이다. $b_m$ 을 $m$ 의 식으로 쓰고 $m=1$ 부터 $10$ 까지 더하면?","식":["$b_m=27+2(m-1)=2m+25$","$\\displaystyle\\sum_{m=1}^{10}b_m=\\dfrac{10\\left(27+45\\right)}{2}=360$"],"설명":"제 $10$ 항은 $b_{10}=45$ 이고 등차수열의 합은 (첫째항+끝항)$\\times$항수$\\div2$ 이다.","확인":"360","스킬":"P6"}]},"고2-202109-22":{"길":"5π/3 를 2π−π/3 꼴로 바꿔 코사인 값을 읽고 10 을 곱한다","단계":[{"제목":"cos 5π/3 의 값 구하기","힌트":"$\\dfrac{5}{3}\\pi$ 를 $2\\pi$ 에서 어떤 각을 뺀 꼴로 쓰면? 그 각의 $\\cos$ 값은?","식":["$\\cos\\dfrac{5}{3}\\pi=\\cos\\left(2\\pi-\\dfrac{\\pi}{3}\\right)=\\cos\\dfrac{\\pi}{3}$","$\\cos\\dfrac{\\pi}{3}=\\dfrac{1}{2}$"],"설명":"$\\cos\\left(2\\pi-\\theta\\right)=\\cos\\theta$ 이다. 단위원에서 $\\dfrac{5}{3}\\pi$ 와 $\\dfrac{\\pi}{3}$ 의 $x$ 좌표가 같다.","확인":"1/2","스킬":"T5","고비":true},{"제목":"10 을 곱해 값 구하기","힌트":"$10\\cos\\dfrac{5}{3}\\pi$ 는?","식":["$10\\cos\\dfrac{5}{3}\\pi=10\\times\\dfrac{1}{2}=5$"],"설명":"앞에서 구한 $\\cos$ 값에 $10$ 을 곱한다.","확인":"5","스킬":"T5"}]},"고2-202109-23":{"길":"밑이 1 보다 작아 감소함수임을 보고 구간의 왼쪽 끝에서 최댓값을 잡는다","단계":[{"제목":"증가·감소 판별해 최대가 되는 x 찾기","힌트":"$y=\\left(\\dfrac{1}{3}\\right)^x+1$ 의 밑은 $1$ 보다 큰가 작은가? $x$ 가 커지면 $y$ 는 커지는가 작아지는가? 그러면 최댓값은 구간의 어느 끝에서 생기는가?","식":["밑 $\\dfrac{1}{3}<1$ 이므로 $y$ 는 감소함수","구간 $-4\\le x\\le-2$ 에서 최댓값은 가장 작은 $x$ 에서 생긴다"],"설명":"감소함수는 $x$ 가 작을수록 $y$ 가 크다.","확인":null,"스킬":"T3","고비":true},{"제목":"최댓값 구하기","힌트":"가장 작은 $x$ 에서의 함숫값은?","식":["$x=-4$ 일 때 $\\left(\\dfrac{1}{3}\\right)^{-4}+1=3^4+1=81+1=82$"],"설명":"$\\left(\\dfrac{1}{3}\\right)^{-4}=3^4=81$ 이다.","확인":"82","스킬":"A9"}]},"고2-202109-24":{"길":"로그의 밑을 3 으로 통일해 a 와 b 의 관계를 찾고 밑이 b 인 로그에 대입한다","단계":[{"제목":"log₉√a 를 log₃a 로 바꾸기","힌트":"$\\log_9\\sqrt{a}$ 를 밑이 $3$ 인 로그로 고치면 $\\log_3 a$ 의 몇 배인가?","식":["$\\log_9\\sqrt{a}=\\dfrac{\\log_3\\sqrt{a}}{\\log_3 9}=\\dfrac{\\frac{1}{2}\\log_3 a}{2}=\\dfrac{1}{4}\\log_3 a$"],"설명":"밑을 바꾸는 공식 $\\log_a b=\\dfrac{\\log_c b}{\\log_c a}$ 를 쓰고 $\\log_3 9=2$ 이다.","확인":"1/4","스킬":"A9"},{"제목":"a 와 b 의 관계 구하기","힌트":"$\\dfrac{1}{4}\\log_3 a=\\log_3 b$ 에서 $a$ 를 $b$ 의 거듭제곱으로 나타내면?","식":["$\\log_3 a=4\\log_3 b=\\log_3 b^4$","$a=b^4$"],"설명":"로그의 계수는 진수의 지수로 옮길 수 있고, 밑이 같은 로그가 같으면 진수도 같다.","확인":"4","스킬":"A9","고비":true},{"제목":"50 log_b √a 의 값 구하기","힌트":"$\\sqrt{a}$ 를 $b$ 의 거듭제곱으로 나타내면? 그러면 $\\log_b\\sqrt{a}$ 는?","식":["$\\sqrt{a}=\\sqrt{b^4}=b^2$ 이므로 $\\log_b\\sqrt{a}=\\log_b b^2=2$","$50\\times\\log_b\\sqrt{a}=50\\times2=100$"],"설명":"$b>1$ 이므로 $\\sqrt{b^4}=b^2$ 이다.","확인":"100","스킬":"A9"}]},"고2-202109-25":{"길":"시그마를 a_n² 과 a_n b_n 의 합으로 나눠 주어진 식에서 Σa_n b_n 을 구한다","단계":[{"제목":"Σ a_n b_n 의 값 구하기","힌트":"$\\displaystyle\\sum_{n=1}^{10}a_n\\left(2b_n-3a_n\\right)$ 를 $\\displaystyle\\sum a_nb_n$ 과 $\\displaystyle\\sum a_n^{\\,2}$ 로 나누어 쓰고 $\\displaystyle\\sum a_n^{\\,2}=10$ 을 넣으면?","식":["$\\displaystyle\\sum_{n=1}^{10}a_n\\left(2b_n-3a_n\\right)=2\\sum_{n=1}^{10}a_nb_n-3\\sum_{n=1}^{10}a_n^{\\,2}=16$","$2\\sum_{n=1}^{10}a_nb_n-30=16$ 이므로 $\\displaystyle\\sum_{n=1}^{10}a_nb_n=23$"],"설명":"괄호를 풀어 $a_nb_n$ 과 $a_n^{\\,2}$ 의 합으로 나누고 상수배는 시그마 밖으로 뺀다.","확인":"23","스킬":"P6","고비":true},{"제목":"구하는 합 계산하기","힌트":"$\\displaystyle\\sum a_n\\left(6a_n+7b_n\\right)$ 도 같은 두 합으로 나누면?","식":["$\\displaystyle\\sum_{n=1}^{10}a_n\\left(6a_n+7b_n\\right)=6\\sum a_n^{\\,2}+7\\sum a_nb_n$","$=6\\times10+7\\times23=221$"],"설명":"앞에서 구한 $\\displaystyle\\sum a_nb_n=23$ 과 주어진 $\\displaystyle\\sum a_n^{\\,2}=10$ 을 넣는다.","확인":"221","스킬":"P6"}]}});
